def _finite_float_or(value: Any, default: float) -> Optional[float]:
    if value is None:
        return float(default)
    try:
        v = float(value)
        return v if math.isfinite(v) else float(default)
    except (TypeError, ValueError, OverflowError):
        return float(default)


def _fast_fillna_1d(arr: np.ndarray) -> np.ndarray:
    try:
        a = np.asarray(arr, dtype=np.float64).ravel()
        bad = ~np.isfinite(a)
        if not np.any(bad):
            return a
        idx = np.where(~bad, np.arange(a.size), 0)
        np.maximum.accumulate(idx, out=idx)
        filled = a[idx]
        first_good = int(np.argmax(~bad)) if np.any(~bad) else 0
        if first_good > 0:
            filled[:first_good] = a[first_good] if math.isfinite(a[first_good]) else 0.0
        return filled
    except Exception:
        return np.asarray(arr, dtype=np.float64)


def _resolve_env_threshold_bundle() -> Dict[str, Any]:
    """باندل آستانه‌های محیط؛ در صورت نبود در ماژول بیرونی، پیش‌فرض ایمن."""
    try:
        fn = globals().get("_env_threshold_bundle")
        if callable(fn):
            out = fn()
            if isinstance(out, dict):
                return out
    except Exception:
        pass
    return {
        "quality_floor": 0.80,
        "ceiling": 0.95,
        "strong": 0.88,
        "env_threshold": 0.80,
    }


def _infer_hold_quality_from_reason(
    reason: str,
    is_fallback: bool = False,
    error_type: str = "None",
) -> float:
    """استنتاج کیفیت HOLD از متن دلیل (برای نمایش، نه احتمال برد)."""
    try:
        r = str(reason or "").lower()
        if is_fallback or (error_type and error_type != "None"):
            return 0.30
        if any(k in r for k in ("degenerate", "zero variance", "non-positive")):
            return 0.55
        if any(k in r for k in ("insufficient", "too short", "validation failed")):
            return 0.60
        if any(k in r for k in ("conflict", "cancel", "no directional")):
            return 0.70
        if any(k in r for k in ("below", "rejected", "thin evidence")):
            return 0.75
        return 0.65
    except Exception:
        return 0.60


def _hardware_profile() -> Dict[str, Any]:
    """پروفایل سخت‌افزار پایه (در صورت نبود در ماژول بیرونی)."""
    try:
        cores = int(os.cpu_count() or 2)
    except Exception:
        cores = 2
    tier = "LOW" if cores <= 2 else ("MID" if cores <= 8 else "HIGH")
    return {"tier": tier, "cores": cores, "total_ram_mb": 0.0}


def finalize_strategy_output(payload: Dict[str, Any], quality_floor: float = 0.80) -> Dict[str, Any]:
    """نهایی‌سازی خروجی استراتژی (امضای سازگار)."""
    try:
        out = dict(payload or {})
        sig = str(out.get("signal", "HOLD")).upper()
        if sig not in ("BUY", "SELL"):
            out["signal"] = "HOLD"
            out["confidence"] = 0.0
            out["is_analytical_hold"] = True
        else:
            conf = float(_finite_float_or(out.get("confidence"), 0.0) or 0.0)
            out["confidence"] = float(max(float(quality_floor), min(0.98, conf)))
        out.setdefault("strategy_name", "QuantitativeMethods")
        out.setdefault("timestamp", datetime.now(timezone.utc).isoformat())
        out.setdefault("score", 50.0)
        out.setdefault("metadata", {})
        return out
    except Exception:
        return {
            "signal": "HOLD",
            "confidence": 0.0,
            "hold_quality": 0.30,
            "reason": "finalize_strategy_output fallback",
            "strategy_name": "QuantitativeMethods",
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "is_fallback": True,
            "metadata": {},
        }


