class BoundedCache:
    """Thread-safe LRU Cache with TTL eviction and zero external dependencies."""
    __slots__ = ("_data", "_max_size", "_ttl", "_lock", "_hits", "_misses")

    def __init__(self, max_size: int = 64, ttl_seconds: float = 300.0) -> None:
        self._data: OrderedDict[str, Tuple[float, Any]] = OrderedDict()
        self._max_size = max(1, int(max_size))
        self._ttl = float(ttl_seconds) if ttl_seconds and ttl_seconds > 0 else 300.0
        self._lock = threading.Lock()
        self._hits = 0
        self._misses = 0

    def get(self, key: str, default: Any = None) -> Any:
        now = time.monotonic()
        with self._lock:
            item = self._data.get(key)
            if item is None:
                self._misses += 1
                return default
            stamp, value = item
            if now - stamp > self._ttl:
                self._data.pop(key, None)
                self._misses += 1
                return default
            self._data.move_to_end(key)
            self._hits += 1
            return value

    def __contains__(self, key: str) -> bool:
        sentinel = object()
        return self.get(key, sentinel) is not sentinel

    def __getitem__(self, key: str) -> Any:
        sentinel = object()
        value = self.get(key, sentinel)
        if value is sentinel:
            raise KeyError(key)
        return value

    def __len__(self) -> int:
        with self._lock:
            return len(self._data)

    def set(self, key: str, value: Any) -> None:
        with self._lock:
            self._data[key] = (time.monotonic(), value)
            self._data.move_to_end(key)
            while len(self._data) > self._max_size:
                self._data.popitem(last=False)

    def __setitem__(self, key: str, value: Any) -> None:
        self.set(key, value)

    def clear(self) -> None:
        with self._lock:
            self._data.clear()

    def stats(self) -> Dict[str, Any]:
        with self._lock:
            total = self._hits + self._misses
            return {
                "size": len(self._data),
                "max_size": self._max_size,
                "hits": self._hits,
                "misses": self._misses,
                "hit_rate": round(self._hits / total, 4) if total else 0.0,
            }


