def _parse_positive_int_env(name: str, default: int, floor: int = 1) -> int:
    try:
        default_safe = max(int(floor), int(default))
    except (TypeError, ValueError):
        default_safe = max(int(floor), 1)
    try:
        raw = os.getenv(name)
        if raw is None:
            return default_safe
        text = str(raw).strip()
        if not text:
            return default_safe
        value = int(float(text))
        return max(int(floor), value)
    except (TypeError, ValueError):
        return default_safe


_GLOBAL_MIN_BARS_REQUIRED: int = _parse_positive_int_env(
    "MIN_BARS_REQUIRED", 500, floor=20
)
_GLOBAL_MIN_BARS_STRICT: int = max(
    _GLOBAL_MIN_BARS_REQUIRED,
    _parse_positive_int_env(
        "MIN_BARS_REQUIRED_STRICT", _GLOBAL_MIN_BARS_REQUIRED, floor=20
    ),
)

def _safe_env_float(name: str, default: float) -> float:
    """
    خواندن امن یک متغیر محیطی عددی.

    قواعد:
      • مقدار خالی/نامعتبر/NaN/Inf → default
      • مقدار > 1.0 بهعنوان درصد تلقی میشود (80 → 0.80)
      • همیشه float متناهی برمیگرداند؛ هرگز exception پرتاب نمیکند.
    """
    try:
        fallback = float(default)
    except (TypeError, ValueError, OverflowError):
        fallback = 0.0
    if not math.isfinite(fallback):
        fallback = 0.0
    try:
        raw = os.getenv(str(name))
        if raw is None:
            return fallback
        text = str(raw).strip()
        if not text:
            return fallback
        value = float(text)
        if not math.isfinite(value):
            return fallback
        if value > 1.0:
            value = value / 100.0
        return float(value)
    except (TypeError, ValueError, OverflowError):
        return fallback

def _resolve_env_threshold_bundle() -> Dict[str, float]:
    """
    GLOBAL FUNCTION — تک منبع حقیقت آستانههای اعتماد (نسخهٔ 0.80-gate).

    تغییرات:
      1. quality_floor دیگر هرگز نمیتواند زیر ۰.۸۰ برود، حتی با env نادرست.
      2. ترتیب floor < strong < ceiling بهصورت ریاضی تضمین میشود.
      3. خروجی همیشه دقیقاً ۵ کلید float متناهی دارد.
    """

    def _clamp(value: Any, low: float, high: float) -> float:
        try:
            v = float(value)
        except (TypeError, ValueError, OverflowError):
            v = float(low)
        if not math.isfinite(v):
            v = float(low)
        if high < low:
            low, high = high, low
        return float(min(high, max(low, v)))

    env_threshold = _clamp(_ENV_DEFAULT_THRESHOLD, 0.50, 0.92)
    for key in (
        "CENTRAL_CONFIDENCE_THRESHOLD",
        "NDS_CONFIDENCE_THRESHOLD",
        "MIN_CONFIDENCE_THRESHOLD",
        "CONFIDENCE_THRESHOLD",
    ):
        raw = os.getenv(key)
        if raw is None or not str(raw).strip():
            continue
        candidate = _safe_env_float(key, _ENV_DEFAULT_THRESHOLD)
        if candidate <= 0.0:
            continue
        env_threshold = _clamp(candidate, 0.50, 0.92)
        break

    floor_override = _safe_env_float(
        "MIN_DELIVERABLE_CONFIDENCE", _MIN_DELIVERABLE_CONFIDENCE
    )
    quality_floor = _clamp(
        max(_MIN_DELIVERABLE_CONFIDENCE, floor_override, env_threshold),
        _MIN_DELIVERABLE_CONFIDENCE, 0.92,
    )

    raw_strong = _safe_env_float("NDS_STRONG_CONFIDENCE", _ENV_STRONG_THRESHOLD)
    strong = _clamp(
        max(raw_strong, quality_floor + 0.06),
        min(quality_floor + 0.02, 0.96), 0.96,
    )
    strong = _clamp(max(strong, quality_floor + 0.02), 0.50, 0.96)

    raw_ceiling = _safe_env_float("NDS_CONFIDENCE_CEILING", _ENV_HARD_CEILING_DEFAULT)
    ceiling = _clamp(
        max(raw_ceiling, strong + 0.02, quality_floor + 0.10),
        min(strong + 0.01, 0.98), 0.98,
    )
    ceiling = _clamp(max(ceiling, strong + 0.01), 0.90, 0.98)

    return {
        "env_threshold": float(env_threshold),
        "quality_floor": float(quality_floor),
        "strong": float(strong),
        "ceiling": float(ceiling),
        "dynamic_bias": 0.0,
    }

def _resolve_confidence_threshold() -> float:
    """آستانهٔ مرکزی اعتماد — همیشه از همان bundle واحد خوانده میشود."""
    try:
        value = float(_resolve_env_threshold_bundle()["env_threshold"])
        return float(value) if math.isfinite(value) else _ENV_DEFAULT_THRESHOLD
    except Exception as bundle_exc:
        logging.getLogger("StrategyQualityGate").debug(
            "threshold bundle unavailable (%s); using %.3f",
            bundle_exc, _ENV_DEFAULT_THRESHOLD,
        )
        return _ENV_DEFAULT_THRESHOLD


def _get_env_confidence_threshold() -> float:
    """
    تک منبع حقیقت برای تمام استراتژیها.

    برخلاف نسخه قبلی، این تابع دیگر مسیر جداگانهای از env نمیخواند؛
    مستقیماً همان باندل `_resolve_env_threshold_bundle` را برمیگرداند تا
    اختلاف بین استراتژیها از بین برود.
    """
    try:
        value = float(_resolve_env_threshold_bundle()["env_threshold"])
        return float(value) if math.isfinite(value) else _ENV_DEFAULT_THRESHOLD
    except Exception as bundle_exc:
        logging.getLogger("StrategyQualityGate").debug(
            "threshold bundle unavailable (%s); using %.3f",
            bundle_exc, _ENV_DEFAULT_THRESHOLD,
        )
        return _ENV_DEFAULT_THRESHOLD


def filter_module_inputs(results: Optional[Sequence[Any]]) -> Dict[str, Any]:
    """
    GLOBAL FUNCTION — واحد کامل قابلافزودن به «فایل تابع ماژول».

    چون فایل تابع ماژول ضمیمه نشده بود، نمیتوانم خود آن تابع را بازنویسی
    کنم (قانون ۲۰ پرامت). بهجای آن این دروازهٔ کامل را ارائه میکنم: خروجی
    ۱۴ استراتژی را قبل از هر وزندهی/ترکیبی از این تابع عبور دهید.
    دقت کنید واحد «strategy_output_is_combinable» را نیز در همان فایل ماژول
    قرار دهید (این تابع مستقل از ثابتهای فایل استراتژی نوشته شده است).

    تضمینها:
      • فقط خروجیهای strategy_output_is_combinable پذیرفته میشوند
        (یعنی جهتدار، confidence >= 0.80، بدون fallback، combine_allowed True).
      • اگر نتیجهٔ تجمیعی هم زیر ۰.۸۰ باشد → HOLD با confidence=0.0.
      • خروجی همیشه dict با کلیدهای ثابت و اعداد متناهی است.
    """

    def _f(value: Any, default: float) -> float:
        try:
            if value is None:
                return float(default)
            out = float(value)
            return out if math.isfinite(out) else float(default)
        except (TypeError, ValueError, OverflowError):
            return float(default)

    floor = 0.80
    try:
        resolver = globals().get("_resolve_env_threshold_bundle")
        if callable(resolver):
            floor = max(floor, float(resolver()["quality_floor"]))
    except Exception as exc:
        logging.getLogger("ModuleQualityGate").debug(
            "strategy threshold bundle unavailable: %s", exc
        )

    accepted: List[Dict[str, Any]] = []
    rejected: List[Dict[str, Any]] = []

    if results:
        for index, item in enumerate(results):
            name = str(item.get("strategy_name", f"strategy_{index}")) if isinstance(item, dict) else f"strategy_{index}"
            if strategy_output_is_combinable(item):
                token = str(item.get("signal", "HOLD")).upper()
                side = "BUY" if "BUY" in token else "SELL"
                accepted.append({
                    "index": int(index),
                    "name": name,
                    "signal": side,
                    "confidence": _f(item.get("confidence"), 0.0),
                })
            else:
                rejected.append({
                    "index": int(index),
                    "name": name,
                    "signal": str(item.get("signal", "HOLD")).upper() if isinstance(item, dict) else "INVALID",
                    "confidence": _f(item.get("confidence"), 0.0) if isinstance(item, dict) else 0.0,
                })

    if not accepted:
        return {
            "signal": "HOLD", "confidence": 0.0, "combine_allowed": False,
            "contributors": [], "rejected": rejected,
            "buy_weight": 0.0, "sell_weight": 0.0, "dominance": 0.0,
            "quality_floor": floor,
            "reason": "no combinable strategy output (all below 0.80 or HOLD)",
        }

    buy_weight = float(sum(row["confidence"] for row in accepted if row["signal"] == "BUY"))
    sell_weight = float(sum(row["confidence"] for row in accepted if row["signal"] == "SELL"))
    total_weight = buy_weight + sell_weight
    if total_weight <= 0.0:
        return {
            "signal": "HOLD", "confidence": 0.0, "combine_allowed": False,
            "contributors": accepted, "rejected": rejected,
            "buy_weight": 0.0, "sell_weight": 0.0, "dominance": 0.0,
            "quality_floor": floor,
            "reason": "zero aggregate weight",
        }

    dominance = abs(buy_weight - sell_weight) / total_weight
    mean_conf = total_weight / len(accepted)
    final_conf = float(min(0.98, max(0.0, mean_conf * (0.60 + 0.40 * dominance))))
    if final_conf + 1e-12 < floor:
        return {
            "signal": "HOLD", "confidence": 0.0, "combine_allowed": False,
            "contributors": accepted, "rejected": rejected,
            "buy_weight": float(buy_weight), "sell_weight": float(sell_weight),
            "dominance": float(dominance),
            "quality_floor": floor,
            "reason": "aggregate confidence below 0.80 floor",
        }

    direction = "BUY" if buy_weight > sell_weight else "SELL"
    return {
        "signal": direction,
        "confidence": round(final_conf, 6),
        "combine_allowed": True,
        "contributors": accepted,
        "rejected": rejected,
        "buy_weight": float(buy_weight),
        "sell_weight": float(sell_weight),
        "dominance": float(dominance),
        "quality_floor": floor,
        "reason": f"{len(accepted)} combinable strategies, {len(rejected)} rejected",
    }


def _resolve_min_bars_for_strategy(
    strategy_name: str,
    strategy_specific_default: int = 0,
) -> int:
    try:
        safe_name = "".join(
            ch for ch in str(strategy_name).upper() if ch.isalnum() or ch == "_"
        )
        specific_key = f"MIN_BARS_REQUIRED_{safe_name}"
        specific = os.getenv(specific_key)
        if specific is not None:
            try:
                val = int(float(specific))
                return max(20, val)
            except (TypeError, ValueError):
                pass

        global_val = os.getenv("MIN_BARS_REQUIRED")
        if global_val is not None:
            try:
                val = int(float(global_val))
                if val > 0:
                    return max(20, val)
            except (TypeError, ValueError):
                pass

        if strategy_specific_default > 0:
            return max(20, int(strategy_specific_default))

        return _GLOBAL_MIN_BARS_REQUIRED
    except Exception:
        return _GLOBAL_MIN_BARS_REQUIRED


def _get_cache_key(symbol: str, timeframe: str, df_hash: str, method: str) -> str:
    return f"{symbol}_{timeframe}_{df_hash[:12]}_{method}"


def _compute_df_hash(df: Optional[pd.DataFrame]) -> str:
    if df is None or df.empty:
        return "empty"
    try:
        cols = [c for c in ('open', 'high', 'low', 'close', 'volume') if c in df.columns]
        if not cols:
            cols = list(df.columns[:4])
        sub = df[cols]
        head = sub.head(20)
        tail = sub.tail(100)
        payload = b"|".join([
            str(len(df)).encode(),
            ",".join(cols).encode(),
            head.values.tobytes(),
            tail.values.tobytes(),
        ])
        return hashlib.md5(payload).hexdigest()
    except Exception:
        try:
            return hashlib.md5(str(len(df)).encode()).hexdigest()
        except Exception:
            return "hash_error"


def _shared_cache_read(cache: Any, key: str) -> Any:
    if not key:
        return _CACHE_MISS
    with _GLOBAL_CACHE_LOCK:
        try:
            return cache.get(key, _CACHE_MISS)
        except TypeError:
            value = cache.get(key)
            return _CACHE_MISS if value is None else value
        except Exception:
            return _CACHE_MISS


def _shared_cache_write(cache: Any, key: str, value: Any) -> None:
    if not key:
        return
    with _GLOBAL_CACHE_LOCK:
        try:
            setter = getattr(cache, "set", None)
            if callable(setter):
                setter(key, value)
            else:
                cache[key] = value
        except Exception:
            pass

# ═══════════════════════════════════════════════════════════════════════════
# SECTION 6 — Numba Kernels (pure math; no TA dependency)
# ═══════════════════════════════════════════════════════════════════════════

@njit(cache=True)
def _fast_fillna_1d(arr: np.ndarray) -> np.ndarray:
    """
    Forward-fill then back-fill non-finite values in O(n).
    If no finite value exists → full-zero output (crash-safe).
    """
    n = len(arr)
    out = np.empty(n, dtype=np.float64)
    if n == 0:
        return out
    last = 0.0
    seen = False
    first_idx = -1
    first_val = 0.0
    for i in range(n):
        v = arr[i]
        if not (v != v) and -1e308 < v < 1e308:
            out[i] = v
            last = v
            if not seen:
                seen = True
                first_idx = i
                first_val = v
        else:
            out[i] = last if seen else 0.0
    if seen and first_idx > 0:
        for i in range(first_idx):
            out[i] = first_val
    return out


@njit(cache=True)
def _fast_ema_1d(arr: np.ndarray, span: int) -> np.ndarray:
    """EMA with alpha=2/(span+1). NaN-safe."""
    n = len(arr)
    out = np.zeros(n, dtype=np.float64)
    if n == 0:
        return out
    span = max(2, span)
    alpha = 2.0 / (span + 1.0)

    seed = 0.0
    start = 0
    for i in range(n):
        v = arr[i]
        if not (v != v) and -1e308 < v < 1e308:
            seed = v
            start = i
            break
    out[start] = seed
    for i in range(start + 1, n):
        val = arr[i]
        if (val != val) or not (-1e308 < val < 1e308):
            out[i] = out[i - 1]
        else:
            out[i] = alpha * val + (1.0 - alpha) * out[i - 1]
    for i in range(start):
        out[i] = seed
    return out


@njit(cache=True)
def _fast_rma_1d(arr: np.ndarray, period: int) -> np.ndarray:
    """Wilder RMA (alpha=1/period). NaN-safe."""
    n = len(arr)
    out = np.zeros(n, dtype=np.float64)
    if n == 0:
        return out
    period = max(2, period)
    alpha = 1.0 / period

    seed = 0.0
    start = 0
    for i in range(n):
        v = arr[i]
        if not (v != v) and -1e308 < v < 1e308:
            seed = v
            start = i
            break
    out[start] = seed
    for i in range(start + 1, n):
        val = arr[i]
        if (val != val) or not (-1e308 < val < 1e308):
            out[i] = out[i - 1]
        else:
            out[i] = alpha * val + (1.0 - alpha) * out[i - 1]
    for i in range(start):
        out[i] = seed
    return out


@njit(cache=True)
def _fast_sma_1d(arr: np.ndarray, period: int) -> np.ndarray:
    """SMA with expanding window at the start (never NaN). O(n)."""
    n = len(arr)
    out = np.zeros(n, dtype=np.float64)
    if n == 0:
        return out
    period = max(1, period)
    csum = 0.0
    for i in range(n):
        v = arr[i]
        if (v != v) or not (-1e308 < v < 1e308):
            v = 0.0
        csum += v
        if i >= period:
            old = arr[i - period]
            if (old != old) or not (-1e308 < old < 1e308):
                old = 0.0
            csum -= old
            out[i] = csum / period
        else:
            out[i] = csum / (i + 1)
    return out


@njit(cache=True, fastmath=True)
def _linreg_vals_numba(series: np.ndarray, length: int) -> np.ndarray:
    n = len(series)
    result = np.full(n, np.nan, dtype=np.float64)
    if length < 2 or n < length:
        return result

    x = np.arange(length, dtype=np.float64)
    x_mean = np.mean(x)
    x_centered = x - x_mean
    x_var = np.sum(x_centered ** 2)

    for i in prange(length - 1, n):
        y = series[i - length + 1:i + 1]
        y_mean = np.mean(y)
        y_centered = y - y_mean
        slope = np.sum(x_centered * y_centered) / x_var if x_var > 1e-12 else 0.0
        result[i] = slope * (length - 1) + (y_mean - slope * x_mean)
    return result


@njit(cache=True, fastmath=True)
def _rsi_wilder_impl(prices: np.ndarray, period: int) -> np.ndarray:
    """Wilder RSI — canonical scalar implementation."""
    n = len(prices)
    if n == 0:
        return np.empty(0, dtype=np.float64)
    if n < 3:
        return np.full(n, 50.0, dtype=np.float64)

    period = max(2, period)
    delta = np.empty(n, dtype=np.float64)
    delta[0] = 0.0
    for i in range(1, n):
        delta[i] = prices[i] - prices[i - 1]

    rsi = np.full(n, 50.0, dtype=np.float64)
    if n < period + 1:
        return rsi

    sum_g = 0.0
    sum_l = 0.0
    for i in range(period):
        d = delta[i]
        if d > 0.0:
            sum_g += d
        else:
            sum_l -= d
    avg_g = sum_g / period
    avg_l = sum_l / period

    if avg_l < 1e-12:
        rsi[period - 1] = 100.0 if avg_g > 1e-12 else 50.0
    else:
        rsi[period - 1] = 100.0 - (100.0 / (1.0 + avg_g / avg_l))

    alpha = 1.0 / period
    for i in range(period, n):
        d = delta[i]
        g = d if d > 0.0 else 0.0
        l = -d if d < 0.0 else 0.0
        avg_g = (1.0 - alpha) * avg_g + alpha * g
        avg_l = (1.0 - alpha) * avg_l + alpha * l
        if avg_l < 1e-12:
            rsi[i] = 100.0 if avg_g > 1e-12 else 50.0
        else:
            rsi[i] = 100.0 - (100.0 / (1.0 + avg_g / avg_l))
    return rsi


# Aliases (DEDUP#2): one dispatcher, three public names preserved
_calc_rsi_numba = _rsi_wilder_impl
_fast_rsi_1d = _rsi_wilder_impl
_streak_rsi_numba = _rsi_wilder_impl


@njit(cache=True, fastmath=True)
def _compute_pct_rank_numba(roc: np.ndarray, period: int) -> np.ndarray:
    n = len(roc)
    result = np.zeros(n, dtype=np.float64)
    if n < period + 1:
        return result

    for i in range(period, n):
        window = roc[i - period:i]
        if len(window) > 0:
            count = 0
            for val in window:
                if val < roc[i]:
                    count += 1
            result[i] = (count / len(window)) * 100.0
    return result


@njit(cache=True, fastmath=True)
def _compute_kama_numba(close: np.ndarray, period: int, fast: int, slow: int) -> np.ndarray:
    n = len(close)
    kama = np.zeros(n, dtype=np.float64)
    if n < period:
        return kama

    fast_sc = 2.0 / (fast + 1)
    slow_sc = 2.0 / (slow + 1)

    kama[period - 1] = close[period - 1]

    for i in range(period, n):
        direction = abs(close[i] - close[i - period])
        volatility = 0.0
        for j in range(i - period + 1, i + 1):
            volatility += abs(close[j] - close[j - 1])
        er = direction / (volatility + 1e-8)
        sc = (er * (fast_sc - slow_sc) + slow_sc) ** 2
        kama[i] = kama[i - 1] + sc * (close[i] - kama[i - 1])

    return kama


@njit(cache=True, fastmath=True)
def _fast_atr_1d(high: np.ndarray, low: np.ndarray, close: np.ndarray,
                 period: int) -> np.ndarray:
    """Wilder ATR — canonical (DEDUP#3)."""
    n = len(close)
    if n == 0:
        return np.empty(0, dtype=np.float64)
    period = max(2, period)
    if n < period + 1:
        return np.full(n, 0.001, dtype=np.float64)

    tr = np.empty(n, dtype=np.float64)
    tr[0] = high[0] - low[0]
    for i in range(1, n):
        prev_c = close[i - 1]
        tr1 = high[i] - low[i]
        tr2 = abs(high[i] - prev_c)
        tr3 = abs(low[i] - prev_c)
        tr[i] = max(tr1, max(tr2, tr3))

    alpha = 1.0 / period
    atr = np.empty(n, dtype=np.float64)
    atr[0] = tr[0]
    for i in range(1, n):
        atr[i] = alpha * tr[i] + (1.0 - alpha) * atr[i - 1]
    return atr


_compute_atr_numba = _fast_atr_1d  # alias


@njit(cache=True, fastmath=True)
def _find_swings_numba(high: np.ndarray, low: np.ndarray, order: int
                       ) -> Tuple[np.ndarray, np.ndarray]:
    n = len(high)
    if n < 2 * order + 1:
        return np.empty(0, dtype=np.int64), np.empty(0, dtype=np.int64)

    ph_list = np.empty(n, dtype=np.int64)
    pl_list = np.empty(n, dtype=np.int64)
    ph_cnt = 0
    pl_cnt = 0

    for i in range(order, n - order):
        is_high = True
        for j in range(1, order + 1):
            if high[i] <= high[i - j] or high[i] <= high[i + j]:
                is_high = False
                break
        if is_high:
            ph_list[ph_cnt] = i
            ph_cnt += 1

        is_low = True
        for j in range(1, order + 1):
            if low[i] >= low[i - j] or low[i] >= low[i + j]:
                is_low = False
                break
        if is_low:
            pl_list[pl_cnt] = i
            pl_cnt += 1

    return ph_list[:ph_cnt], pl_list[:pl_cnt]


@njit(cache=True, fastmath=True)
def _detect_equal_levels_numba(arr: np.ndarray, tolerance: float) -> np.ndarray:
    n = len(arr)
    if n < 2:
        return np.zeros(0, dtype=np.float64)
    max_clusters = n
    clusters = np.zeros(max_clusters, dtype=np.float64)
    cluster_counts = np.zeros(max_clusters, dtype=np.int64)
    cluster_count = 0
    for val in arr:
        found = False
        for i in range(cluster_count):
            if abs(val - clusters[i]) / (abs(clusters[i]) + 1e-8) < tolerance:
                found = True
                break
        if not found and cluster_count < max_clusters:
            clusters[cluster_count] = val
            cluster_count += 1
    if cluster_count == 0:
        return np.zeros(0, dtype=np.float64)
    for val in arr:
        for i in range(cluster_count):
            if abs(val - clusters[i]) / (abs(clusters[i]) + 1e-8) < tolerance:
                cluster_counts[i] += 1
                break
    result = np.zeros(cluster_count, dtype=np.float64)
    result_count = 0
    for i in range(cluster_count):
        if cluster_counts[i] >= 2:
            result[result_count] = clusters[i]
            result_count += 1
    return result[:result_count]


@njit(cache=True, fastmath=True)
def _compute_hurst_numba(log_returns: np.ndarray, lags: np.ndarray) -> float:
    n = len(log_returns)
    n_lags = len(lags)
    log_lags = np.zeros(n_lags, dtype=np.float64)
    log_rs = np.zeros(n_lags, dtype=np.float64)
    valid_count = 0

    for li in range(n_lags):
        lag = int(lags[li])
        if lag < 4 or lag > n:
            continue
        max_rs = 128
        rs_values = np.zeros(max_rs, dtype=np.float64)
        rs_count = 0

        for start in range(0, n - lag + 1, lag):
            end = start + lag
            if end > n:
                break
            chunk = log_returns[start:end]
            if len(chunk) < 4:
                continue
            mean_c = np.mean(chunk)
            dev = np.empty(len(chunk), dtype=np.float64)
            cumsum = 0.0
            for j in range(len(chunk)):
                cumsum += chunk[j] - mean_c
                dev[j] = cumsum
            r_val = np.max(dev) - np.min(dev)

            squared = 0.0
            for j in range(len(chunk)):
                diff = chunk[j] - mean_c
                squared += diff * diff
            s_val = np.sqrt(squared / (len(chunk) - 1))

            if s_val > 1e-10 and r_val / s_val > 1e-10 and rs_count < max_rs:
                rs_values[rs_count] = r_val / s_val
                rs_count += 1

        if rs_count > 0:
            mean_rs = 0.0
            for i in range(rs_count):
                mean_rs += rs_values[i]
            mean_rs = mean_rs / rs_count
            log_lags[valid_count] = np.log(float(lag))
            log_rs[valid_count] = np.log(max(mean_rs, 1e-10))
            valid_count += 1

    if valid_count < 2:
        return 0.5

    x_mean = 0.0
    y_mean = 0.0
    for i in range(valid_count):
        x_mean += log_lags[i]
        y_mean += log_rs[i]
    x_mean /= valid_count
    y_mean /= valid_count

    numerator = 0.0
    denominator = 0.0
    for i in range(valid_count):
        x_diff = log_lags[i] - x_mean
        y_diff = log_rs[i] - y_mean
        numerator += x_diff * y_diff
        denominator += x_diff * x_diff
    if denominator < 1e-12:
        return 0.5
    return float(max(0.0, min(1.0, numerator / denominator)))

@njit(cache=True, fastmath=True)
def _fast_adx_di_1d(high: np.ndarray, low: np.ndarray, close: np.ndarray,
                    period: int
                    ) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
    n = len(close)
    if n == 0:
        return (np.empty(0, dtype=np.float64),
                np.empty(0, dtype=np.float64),
                np.empty(0, dtype=np.float64))

    tr = np.empty(n, dtype=np.float64)
    plus_dm = np.empty(n, dtype=np.float64)
    minus_dm = np.empty(n, dtype=np.float64)

    tr[0] = high[0] - low[0]
    plus_dm[0] = 0.0
    minus_dm[0] = 0.0

    for i in range(1, n):
        prev_c = close[i - 1]
        tr1 = high[i] - low[i]
        tr2 = abs(high[i] - prev_c)
        tr3 = abs(low[i] - prev_c)
        tr[i] = max(tr1, max(tr2, tr3))

        up_move = high[i] - high[i - 1]
        dn_move = low[i - 1] - low[i]

        if up_move > dn_move and up_move > 0.0:
            plus_dm[i] = up_move
        else:
            plus_dm[i] = 0.0

        if dn_move > up_move and dn_move > 0.0:
            minus_dm[i] = dn_move
        else:
            minus_dm[i] = 0.0

    period = max(2, period)
    alpha = 1.0 / period

    smooth_tr = np.empty(n, dtype=np.float64)
    smooth_pdm = np.empty(n, dtype=np.float64)
    smooth_mdm = np.empty(n, dtype=np.float64)

    smooth_tr[0] = tr[0]
    smooth_pdm[0] = plus_dm[0]
    smooth_mdm[0] = minus_dm[0]

    for i in range(1, n):
        smooth_tr[i] = alpha * tr[i] + (1.0 - alpha) * smooth_tr[i - 1]
        smooth_pdm[i] = alpha * plus_dm[i] + (1.0 - alpha) * smooth_pdm[i - 1]
        smooth_mdm[i] = alpha * minus_dm[i] + (1.0 - alpha) * smooth_mdm[i - 1]

    pdi = np.zeros(n, dtype=np.float64)
    mdi = np.zeros(n, dtype=np.float64)
    dx = np.zeros(n, dtype=np.float64)

    for i in range(n):
        atr_val = smooth_tr[i]
        if atr_val > 1e-12:
            pdi[i] = 100.0 * smooth_pdm[i] / atr_val
            mdi[i] = 100.0 * smooth_mdm[i] / atr_val
        denom = pdi[i] + mdi[i]
        if denom > 1e-12:
            dx[i] = 100.0 * abs(pdi[i] - mdi[i]) / denom
        else:
            dx[i] = 0.0

    adx = np.zeros(n, dtype=np.float64)
    adx[0] = dx[0]
    for i in range(1, n):
        adx[i] = alpha * dx[i] + (1.0 - alpha) * adx[i - 1]

    return adx, pdi, mdi


@njit(cache=True, fastmath=True)
def _fast_lin_slope_1d(y: np.ndarray) -> float:
    m = len(y)
    if m < 3:
        return 0.0
    sum_x = 0.0
    sum_y = 0.0
    for i in range(m):
        sum_x += i
        sum_y += y[i]
    xm = sum_x / m
    ym = sum_y / m

    numer = 0.0
    denom = 0.0
    for i in range(m):
        xd = i - xm
        yd = y[i] - ym
        numer += xd * yd
        denom += xd * xd
    if denom < 1e-12:
        return 0.0
    return numer / denom


@njit(cache=True, fastmath=True)
def _fast_pivots_1d(high: np.ndarray, low: np.ndarray, lb: int
                    ) -> Tuple[np.ndarray, np.ndarray]:
    n = len(high)
    w = 2 * lb + 1
    if n < w:
        return np.empty(0, dtype=np.int64), np.empty(0, dtype=np.int64)

    ph_list = np.empty(n, dtype=np.int64)
    pl_list = np.empty(n, dtype=np.int64)
    ph_cnt = 0
    pl_cnt = 0

    for i in range(lb, n - lb):
        h_val = high[i]
        is_high = True
        for j in range(1, lb + 1):
            if high[i - j] >= h_val or high[i + j] >= h_val:
                is_high = False
                break
        if is_high:
            ph_list[ph_cnt] = i
            ph_cnt += 1

        l_val = low[i]
        is_low = True
        for j in range(1, lb + 1):
            if low[i - j] <= l_val or low[i + j] <= l_val:
                is_low = False
                break
        if is_low:
            pl_list[pl_cnt] = i
            pl_cnt += 1

    return ph_list[:ph_cnt], pl_list[:pl_cnt]


@njit(cache=True, fastmath=True)
def _fast_rolling_sum_1d(arr: np.ndarray, period: int) -> np.ndarray:
    """Rolling sum in O(n) — replaces pd.Series.rolling(period).sum()."""
    n = len(arr)
    out = np.full(n, np.nan, dtype=np.float64)
    if period < 1 or n < period:
        return out
    s = 0.0
    for i in range(n):
        s += arr[i]
        if i >= period:
            s -= arr[i - period]
        if i >= period - 1:
            out[i] = s
    return out



# ═══════════════════════════════════════════════════════════════════════════
# SECTION 7 — JIT Warmup Machinery
# ═══════════════════════════════════════════════════════════════════════════

_KERNELS_READY: bool = False
_JIT_WARMUP_STARTED: bool = False
_JIT_WARMUP_LOCK = threading.Lock()
_JIT_WARMUP_THREAD: Optional[threading.Thread] = None


def _warmup_numba_kernels() -> None:
    global _KERNELS_READY
    if not NUMBA_AVAILABLE:
        return
    try:
        rng = np.random.default_rng(7)
        n = 96
        base = 100.0 + np.cumsum(rng.normal(0.0, 0.25, n))
        hi = np.ascontiguousarray(base + np.abs(rng.normal(0.05, 0.02, n)), dtype=np.float64)
        lo = np.ascontiguousarray(base - np.abs(rng.normal(0.05, 0.02, n)), dtype=np.float64)
        cl = np.ascontiguousarray(base, dtype=np.float64)
        dirty = cl.copy()
        dirty[7] = np.nan
        dirty[19] = np.inf

        _fast_fillna_1d(dirty)
        _fast_ema_1d(cl, 14)
        _fast_ema_1d(dirty, 14)
        _fast_rma_1d(cl, 14)
        _fast_rma_1d(dirty, 14)
        _fast_sma_1d(cl, 14)
        _calc_rsi_numba(cl, 14)
        _streak_rsi_numba(cl, 14)
        _fast_rsi_1d(cl, 14)
        _fast_atr_1d(hi, lo, cl, 14)
        _compute_atr_numba(hi, lo, cl, 14)
        _fast_adx_di_1d(hi, lo, cl, 14)
        _fast_pivots_1d(hi, lo, 2)
        _find_swings_numba(hi, lo, 2)
        _fast_lin_slope_1d(cl)
        _compute_kama_numba(cl, 10, 2, 30)
        _detect_equal_levels_numba(cl, 0.001)
        _linreg_vals_numba(cl, 10)
        _compute_pct_rank_numba(cl, 10)
        _fast_rolling_sum_1d(cl, 14)
        log_ret = np.log(cl[1:] / cl[:-1])
        lags = np.array([4, 8, 16, 32], dtype=np.int64)
        _compute_hurst_numba(log_ret, lags)
        _KERNELS_READY = True
    except Exception:
        _KERNELS_READY = False


def _jit_kernels_ready() -> bool:
    return bool(_KERNELS_READY)


def warmup_jit(blocking: bool = True) -> bool:
    """
    Ensure the Numba kernels are compiled and ready.
    With blocking=True also waits for an already-running background warm-up.
    """
    global _JIT_WARMUP_STARTED
    if not NUMBA_AVAILABLE:
        return False
    if blocking:
        should_run = False
        with _JIT_WARMUP_LOCK:
            if not _JIT_WARMUP_STARTED:
                _JIT_WARMUP_STARTED = True
                should_run = True
        if should_run:
            _warmup_numba_kernels()
        else:
            with _JIT_WARMUP_LOCK:
                thread = _JIT_WARMUP_THREAD
            if (thread is not None and thread.is_alive()
                    and thread is not threading.current_thread()):
                thread.join()
    else:
        ensure_jit_warmup_started(background=True)
    return bool(_KERNELS_READY)


def ensure_jit_warmup_started(background: bool = True) -> None:
    global _JIT_WARMUP_STARTED, _JIT_WARMUP_THREAD
    if not NUMBA_AVAILABLE:
        return
    with _JIT_WARMUP_LOCK:
        if _JIT_WARMUP_STARTED:
            return
        _JIT_WARMUP_STARTED = True
    if background:
        thread = threading.Thread(
            target=_warmup_numba_kernels,
            name="quant-jit-warmup",
            daemon=True,
        )
        with _JIT_WARMUP_LOCK:
            _JIT_WARMUP_THREAD = thread
        thread.start()
    else:
        _warmup_numba_kernels()

