# SECTION 8 — Hardware Profile Detection
# ═══════════════════════════════════════════════════════════════════════════

_HW_PROFILE_CACHE: Optional[Dict[str, Any]] = None
_HW_PROFILE_LOCK = threading.Lock()

_TIER_DEFAULTS: Dict[str, Tuple[int, float]] = {
    "LOW":  (640,  60.0),
    "MID":  (1280, 60.0),
    "HIGH": (2560, 60.0),
}


def _detect_hardware_tier(cores: int, total_ram_mb: float) -> str:
    if cores <= 2 or (0.0 < total_ram_mb < 3072.0):
        return "LOW"
    if cores <= 8 or (0.0 < total_ram_mb < 16384.0):
        return "MID"
    return "HIGH"


def _hardware_profile() -> Dict[str, Any]:
    global _HW_PROFILE_CACHE
    if _HW_PROFILE_CACHE is not None:
        return _HW_PROFILE_CACHE

    with _HW_PROFILE_LOCK:
        if _HW_PROFILE_CACHE is not None:
            return _HW_PROFILE_CACHE

        cores = 1
        try:
            sched = getattr(os, "sched_getaffinity", None)
            if sched is not None:
                cores = len(sched(0))
            else:
                cores = os.cpu_count() or 1
        except Exception:
            cores = os.cpu_count() or 1
        cores = max(1, int(cores))

        total_ram_mb = 0.0
        try:
            page_size = os.sysconf("SC_PAGE_SIZE")
            page_count = os.sysconf("SC_PHYS_PAGES")
            total_ram_mb = float(page_size) * float(page_count) / (1024.0 * 1024.0)
        except (ValueError, OSError, AttributeError):
            total_ram_mb = 0.0

        tier = _detect_hardware_tier(cores, total_ram_mb)
        env_tier = (os.getenv("PAE_TIER") or "").strip().upper()
        if env_tier in _TIER_DEFAULTS:
            tier = env_tier

        max_window, budget = _TIER_DEFAULTS[tier]

        _log = logging.getLogger("PriceActionEngine")
        env_window = os.getenv("PAE_MAX_WINDOW")
        if env_window:
            try:
                max_window = max(120, int(float(env_window)))
            except (TypeError, ValueError):
                _log.warning("Ignoring malformed PAE_MAX_WINDOW=%r; using %d",
                             env_window, max_window)
        env_budget = os.getenv("PAE_TIME_BUDGET_S")
        if env_budget:
            try:
                budget = max(0.5, min(60.0, float(env_budget)))
            except (TypeError, ValueError):
                _log.warning("Ignoring malformed PAE_TIME_BUDGET_S=%r; using %.2f",
                             env_budget, budget)

        _HW_PROFILE_CACHE = {
            "cores": cores,
            "total_ram_mb": round(total_ram_mb, 1),
            "tier": tier,
            "max_window": int(max_window),
            "time_budget_s": float(budget),
        }
        _log.debug("Hardware profile: %s", _HW_PROFILE_CACHE)
        return _HW_PROFILE_CACHE

def get_hardware_profile() -> Dict[str, Any]:
    """Public access to the cached hardware profile (defensive copy)."""
    return dict(_hardware_profile())

