# SECTION 10 — StrategyWindowManager
# ═══════════════════════════════════════════════════════════════════════════

class StrategyWindowManager:
    """
    Central manager for strategy time windows.
    Computes safe window based on calibrated profile + Hysteresis.
    """
    _instance: Optional['StrategyWindowManager'] = None
    _lock = threading.RLock()

    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self):
        if hasattr(self, '_initialized'):
            return
        self._initialized = True
        self._profiles: Dict[str, Dict[str, Any]] = {}
        self._profile_lock = threading.RLock()
        self._profile_dir = Path("TRADE/window_profiles")
        self._profile_dir.mkdir(parents=True, exist_ok=True)
        self.logger = logger

    def _get_profile_key(self, strategy_name: str, symbol: str, timeframe: str,
                         config_hash: str) -> str:
        return f"{strategy_name}_{symbol}_{timeframe}_{config_hash}"

    def get_selected_window(self, strategy_name: str, symbol: str, timeframe: str,
                            config_hash: str = "default") -> int:
        key = self._get_profile_key(strategy_name, symbol, timeframe, config_hash)
        with self._profile_lock:
            if key in self._profiles:
                return self._profiles[key].get(
                    "selected_window", self._get_default_window(strategy_name))

            profile_path = self._profile_dir / f"{key}.json"
            if profile_path.exists():
                try:
                    with open(profile_path, 'r', encoding='utf-8') as f:
                        data = json.load(f)
                        self._profiles[key] = data
                        return data.get("selected_window",
                                        self._get_default_window(strategy_name))
                except Exception as e:
                    self.logger.warning(f"Failed to load profile {key}: {e}")

            default_win = self._get_default_window(strategy_name)
            self._profiles[key] = {
                "selected_window": default_win,
                "successful_calibrations": 0,
                "last_calibration_time": None,
            }
            return default_win

    def record_calibration_result(
        self, strategy_name: str, symbol: str, timeframe: str,
        tested_window: int, reference_window: int, is_match: bool,
        config_hash: str = "default", strategy_version: str = "1.0",
    ) -> None:
        key = self._get_profile_key(strategy_name, symbol, timeframe, config_hash)
        with self._profile_lock:
            if key not in self._profiles:
                self.get_selected_window(strategy_name, symbol, timeframe, config_hash)

            profile = self._profiles[key]
            current_selected = profile["selected_window"]

            if is_match:
                profile["successful_calibrations"] = profile.get("successful_calibrations", 0) + 1
                if profile["successful_calibrations"] >= 3 and tested_window < current_selected:
                    profile["selected_window"] = tested_window
                    profile["successful_calibrations"] = 0
                    self.logger.info(
                        f"⬇️ Downgraded {strategy_name} window to {tested_window} "
                        f"for {symbol}/{timeframe}"
                    )
            else:
                profile["successful_calibrations"] = 0
                if current_selected < reference_window:
                    profile["selected_window"] = reference_window
                    self.logger.warning(
                        f"⬆️ Upgraded {strategy_name} window to {reference_window} "
                        f"for {symbol}/{timeframe} due to mismatch"
                    )

            profile["last_calibration_time"] = time.time()
            self._save_profile_atomic(key, profile)

    def _save_profile_atomic(self, key: str, profile: Dict[str, Any]) -> None:
        profile_path = self._profile_dir / f"{key}.json"
        temp_path = profile_path.with_suffix(".tmp")
        try:
            with open(temp_path, 'w', encoding='utf-8') as f:
                json.dump(profile, f, indent=2)
                f.flush()
                os.fsync(f.fileno())
            os.replace(temp_path, profile_path)
        except Exception as e:
            self.logger.error(f"Failed to save profile {key}: {e}")

    def _get_default_window(self, strategy_name: str) -> int:
        defaults = {
            "xgboost_signal_generator": 80,
            "mtf_engine": 120,
            "advanced_oscillators": 180,
            "advanced_ma": 150,
            "pivot": 260,
            "divergence_analyzer": 180,
            "volume_analyzer": 300,
            "smart_money_engine": 300,
            "harmonic": 500,
            "quant_methods": 300,
            "price_action_engine": 300,
        }
        return defaults.get(strategy_name, 300)


def get_strategy_window_manager() -> StrategyWindowManager:
    return StrategyWindowManager()

