class StrategyInputSlicer:
    @staticmethod
    def slice_for_strategy(df: pd.DataFrame, strategy_name: str,
                           selected_window: int
                           ) -> Tuple[bool, str, Optional[pd.DataFrame]]:
        reqs = _STRATEGY_HISTORY_REQUIREMENTS.get(strategy_name, {})
        hard_min = reqs.get("hard_min_bars", 50)

        if df is None or df.empty:
            return False, "SKIPPED_NO_DATA", None

        available_bars = len(df)
        if available_bars < hard_min:
            return False, f"SKIPPED_INSUFFICIENT_DATA: {available_bars} < {hard_min}", None

        if available_bars > selected_window:
            sliced_df = df.iloc[-selected_window:].copy()
        else:
            sliced_df = df.copy()

        return True, "OK", sliced_df


