def get_max_fetch_bars_for_timeframe(active_strategies: List[str]) -> int:
    """Maximum fetch_bars among active strategies."""
    if not active_strategies:
        return 600

    max_bars = 200
    for strategy_name in active_strategies:
        req = _STRATEGY_HISTORY_REQUIREMENTS.get(strategy_name, {})
        fetch = req.get("fetch_bars", 600)
        max_bars = max(max_bars, fetch)

    return min(max_bars, 2000)

