# SECTION 12 — SharedIndicatorCache
# ═══════════════════════════════════════════════════════════════════════════

class SharedIndicatorCache:
    """Module-level cache to avoid recomputation of identical indicators
    on identical DataFrames."""
    _instance = None
    _lock = threading.RLock()

    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super(SharedIndicatorCache, cls).__new__(cls)
                    cls._instance._cache = {}
                    cls._instance._max_size = 50
        return cls._instance

    def get(self, df_hash: str, indicator_name: str) -> Optional[np.ndarray]:
        key = f"{df_hash}_{indicator_name}"
        with self._lock:
            return self._cache.get(key)

    def set(self, df_hash: str, indicator_name: str, data: np.ndarray):
        key = f"{df_hash}_{indicator_name}"
        with self._lock:
            if len(self._cache) >= self._max_size:
                first_key = next(iter(self._cache))
                del self._cache[first_key]
            self._cache[key] = data

    def clear(self):
        with self._lock:
            self._cache.clear()


_INDICATOR_CACHE = SharedIndicatorCache()

