# SECTION 13 — get_strategy_history_requirement (LRU cached)
# ═══════════════════════════════════════════════════════════════════════════

@lru_cache(maxsize=128)
def get_strategy_history_requirement(
    strategy_name: str,
    field: str = "reference_window",
    default: int = 200,
) -> int:
    """Retrieve strategy history requirement with LRU cache."""
    try:
        from Strategy_management import STRATEGIES_LIST
        if strategy_name not in STRATEGIES_LIST:
            return max(20, int(default))

        strategy_cls = STRATEGIES_LIST[strategy_name]
        if hasattr(strategy_cls, 'DEFAULT_PARAMS'):
            params = strategy_cls.DEFAULT_PARAMS
            if field == "hard_min_bars" and "min_required_bars" in params:
                return max(20, int(params["min_required_bars"]))
            if field == "reference_window" and "pivot_lookback_periods" in params:
                return max(50, int(params.get("min_required_bars", 260)))
            if field in params:
                return max(20, int(params[field]))
        return max(20, int(default))
    except Exception:
        return max(20, int(default))

