# SECTION 14 — HistoryFetchPlanner
# ═══════════════════════════════════════════════════════════════════════════

class HistoryFetchPlanner:
    """
    Optimize data fetching from connector.
    Computes max fetch_bars needed across active strategies → one fetch.
    """
    def __init__(self, window_manager: Optional[StrategyWindowManager] = None):
        self.window_manager = window_manager or get_strategy_window_manager()

    def calculate_max_fetch_bars(self, active_strategies: List[str],
                                 symbol: str, timeframe: str) -> int:
        try:
            max_bars = 200
            for strategy_name in active_strategies:
                reqs = self._get_strategy_requirements(strategy_name)
                fetch_bars = reqs.get("fetch_bars", 600)
                max_bars = max(max_bars, fetch_bars)
            return min(max_bars, 2000)
        except Exception as e:
            logger.warning(f"[HistoryFetchPlanner] Error calculating max fetch bars: {e}")
            return 600

    def _get_strategy_requirements(self, strategy_name: str) -> Dict[str, int]:
        requirements = {
            "xgboost_signal_generator": {"hard_min_bars": 80, "default_window": 80, "reference_window": 400, "fetch_bars": 500},
            "mtf_engine": {"hard_min_bars": 60, "default_window": 120, "reference_window": 300, "fetch_bars": 600},
            "advanced_oscillators": {"hard_min_bars": 60, "default_window": 150, "reference_window": 400, "fetch_bars": 500},
            "advanced_ma": {"hard_min_bars": 100, "default_window": 200, "reference_window": 500, "fetch_bars": 600},
            "pivot": {"hard_min_bars": 100, "default_window": 260, "reference_window": 500, "fetch_bars": 600},
            "divergence_analyzer": {"hard_min_bars": 180, "default_window": 260, "reference_window": 600, "fetch_bars": 700},
            "volume_analyzer": {"hard_min_bars": 200, "default_window": 500, "reference_window": 1000, "fetch_bars": 1200},
            "smart_money_engine": {"hard_min_bars": 200, "default_window": 300, "reference_window": 600, "fetch_bars": 700},
            "harmonic": {"hard_min_bars": 200, "default_window": 500, "reference_window": 1000, "fetch_bars": 1200},
            "quant_methods": {"hard_min_bars": 200, "default_window": 300, "reference_window": 600, "fetch_bars": 700},
            "price_action_engine": {"hard_min_bars": 120, "default_window": 200, "reference_window": 500, "fetch_bars": 600},
        }
        return requirements.get(strategy_name, {
            "hard_min_bars": 100, "default_window": 300,
            "reference_window": 500, "fetch_bars": 600,
        })

    async def fetch_optimal_data(self, connector: Any, symbol: str, timeframe: str,
                                 active_strategies: List[str]) -> Optional[Any]:
        try:
            max_bars = self.calculate_max_fetch_bars(active_strategies, symbol, timeframe)
            logger.info(
                f"[HistoryFetchPlanner] Fetching {max_bars} bars for {symbol} {timeframe} "
                f"(strategies: {len(active_strategies)})"
            )

            df = await connector.get_historical_data(
                symbol=symbol, timeframe=timeframe, limit=max_bars
            )

            if df is None or (hasattr(df, 'empty') and df.empty):
                logger.warning(f"[HistoryFetchPlanner] No data returned for {symbol} {timeframe}")
                return None

            logger.info(f"[HistoryFetchPlanner] ✅ Fetched {len(df)} bars for {symbol} {timeframe}")
            return df
        except Exception as e:
            logger.error(f"[HistoryFetchPlanner] ❌ Error fetching data for {symbol}: {e}",
                         exc_info=True)
            return None


_HISTORY_FETCH_PLANNER: Optional[HistoryFetchPlanner] = None
_HISTORY_FETCH_PLANNER_LOCK = threading.Lock()


def get_history_fetch_planner() -> HistoryFetchPlanner:
    global _HISTORY_FETCH_PLANNER
    if _HISTORY_FETCH_PLANNER is None:
        with _HISTORY_FETCH_PLANNER_LOCK:
            if _HISTORY_FETCH_PLANNER is None:
                _HISTORY_FETCH_PLANNER = HistoryFetchPlanner()
    return _HISTORY_FETCH_PLANNER

