# SECTION 15 — TimeBudget
# ═══════════════════════════════════════════════════════════════════════════

class TimeBudget:
    """
    Deadline guard per strategy. Checking ``budget.expired`` before any
    heavy phase makes the 60s ceiling mathematically unreachable.

    Usage:
        budget = TimeBudget()
        if budget.expired: → clean exit with whatever was computed
    """
    __slots__ = ("_started", "_limit")

    def __init__(self, seconds: Optional[float] = None) -> None:
        if seconds is None:
            seconds = float(_hardware_profile()["time_budget_s"])
        try:
            limit = float(seconds)
            if not math.isfinite(limit):
                limit = 60.0
        except (TypeError, ValueError):
            limit = 60.0
        self._limit = max(0.5, min(60.0, limit))
        self._started = time.perf_counter()

    @property
    def elapsed(self) -> float:
        return time.perf_counter() - self._started

    @property
    def remaining(self) -> float:
        return max(0.0, self._limit - self.elapsed)

    @property
    def expired(self) -> bool:
        return self.elapsed >= self._limit

    def __enter__(self) -> "TimeBudget":
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> bool:
        return False
        
# ═══════════════════════════════════════════════════════════════════════════
# SECTION 16 — HOLD Quality Helpers & finalize_signal_decision
# ═══════════════════════════════════════════════════════════════════════════

def _infer_hold_quality_from_reason(
    reason: str,
    is_fallback: bool = False,
    error_type: str = "None",
) -> float:
    try:
        r = str(reason or "").lower()
        et = str(error_type or "None").lower()

        if is_fallback or et not in ("none", "", "null"):
            if any(k in r for k in (
                "insufficient data", "insufficient history",
                "insufficient bars", "not enough data",
                "too few bars", "validation failed",
                "missing columns", "too much nan",
                "empty dataframe",
            )):
                return 0.55
            return 0.30

        if not r or r in ("n/a", "none", "unknown"):
            return 0.60

        if any(k in r for k in (
            "no clear", "no setup", "no qualified", "no high-quality",
            "no valid", "no dominant", "no aligned",
            "insufficient confluence", "below", "gate rejected",
            "insufficient agreement", "weak agreement",
            "conflict", "conflicting", "no strong signal",
            "no directional", "no oscillator signals",
            "no aligned high-confidence pattern",
        )):
            return 0.78

        if any(k in r for k in (
            "ranging", "suppressed", "regime", "range bound",
            "sideways", "quiet", "low volatility", "dead",
            "compression", "cooldown",
        )):
            return 0.85

        if any(k in r for k in (
            "insufficient", "not enough", "too few",
            "short history", "warm-up", "cold start",
        )):
            return 0.60

        return 0.72
    except Exception:
        return 0.60


def _sanitize_ohlcv_arrays(
    df: Any,
    max_nan_ratio: float = 0.20,
    min_bars: int = 250,
    min_price_variance: float = 1e-12,
) -> Tuple[Optional[Dict[str, Any]], str, float]:
    """
    GLOBAL FUNCTION — آمادهسازی امن و سریع OHLCV پیش از هر محاسبه.

    خروجی: (arrays | None, reason, data_quality)
      • arrays: dict با open/high/low/close/volume/size — همیشه float64،
        یکبعدی، contiguous و ۱۰۰٪ متناهی (هیچ NaN/Inf به کرنلها نمیرسد).
      • reason: رشتهٔ خالی یعنی موفقیت؛ در غیراینصورت علت رد تحلیلی.
      • data_quality: ۱ − نسبت مقادیر غیرمتناهی خام، قبل از هر ترمیم.

    برخلاف نسخهٔ قبلی فقط ستون close بررسی نمیشود؛ هر چهار ستون قیمت،
    ستونهای تکراری، اعداد منفی/صفر، OHLC ناسازگار و واریانس صفر چک میشوند.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return None, "empty or non-DataFrame input", 0.0

    required = ("open", "high", "low", "close")
    missing = [col for col in required if col not in df.columns]
    if missing:
        return None, f"missing required columns: {missing}", 0.0

    n = int(len(df))
    needed = int(max(20, min_bars))
    if n < needed:
        return None, f"insufficient bars: {n} < {needed}", 0.0

    columns = list(df.columns)
    for col in required:
        if columns.count(col) > 1:
            return None, f"duplicated column: {col}", 0.0

    raw: Dict[str, np.ndarray] = {}
    for col in required:
        try:
            arr = np.ascontiguousarray(df[col].to_numpy(dtype=np.float64), dtype=np.float64)
        except (TypeError, ValueError, OverflowError) as exc:
            return None, f"non-numeric column {col}: {exc}", 0.0
        if arr.ndim != 1 or arr.shape[0] != n:
            return None, f"invalid shape for column {col}: {arr.shape}", 0.0
        raw[col] = arr

    stacked = np.vstack([raw[col] for col in required])
    raw_nan_ratio = float(1.0 - np.isfinite(stacked).mean())
    data_quality = float(min(1.0, max(0.0, 1.0 - raw_nan_ratio)))
    if raw_nan_ratio > float(max_nan_ratio):
        return None, (
            f"too many NaN/Inf: {raw_nan_ratio:.1%} > {float(max_nan_ratio):.1%}"
        ), data_quality

    if "volume" in df.columns and columns.count("volume") == 1:
        try:
            vol = np.ascontiguousarray(df["volume"].to_numpy(dtype=np.float64), dtype=np.float64)
        except (TypeError, ValueError, OverflowError):
            vol = np.ones(n, dtype=np.float64)
        if vol.ndim != 1 or vol.shape[0] != n:
            vol = np.ones(n, dtype=np.float64)
    else:
        vol = np.ones(n, dtype=np.float64)

    def _repair(arr: np.ndarray) -> Optional[np.ndarray]:
        try:
            out = np.ascontiguousarray(_fast_fillna_1d(arr), dtype=np.float64)
        except Exception:
            series = pd.Series(arr).replace([np.inf, -np.inf], np.nan).ffill().bfill()
            out = np.ascontiguousarray(series.to_numpy(dtype=np.float64), dtype=np.float64)
        if out.ndim != 1 or out.shape[0] != n or not np.isfinite(out).all():
            return None
        return out

    clean: Dict[str, Any] = {}
    for col in required:
        fixed = _repair(raw[col])
        if fixed is None:
            return None, f"unrecoverable non-finite values in {col}", data_quality
        clean[col] = fixed

    vol = np.ascontiguousarray(
        np.where(np.isfinite(vol), np.maximum(vol, 0.0), 1.0), dtype=np.float64
    )

    o = clean["open"]
    h = clean["high"]
    l = clean["low"]
    c = clean["close"]

    if not (np.all(o > 0.0) and np.all(h > 0.0) and np.all(l > 0.0) and np.all(c > 0.0)):
        return None, "non-positive prices", data_quality

    bad_hl = int(np.count_nonzero(h < np.maximum(o, c)) + np.count_nonzero(l > np.minimum(o, c)))
    h = np.maximum(h, np.maximum(o, c))
    l = np.minimum(l, np.minimum(o, c))
    l = np.minimum(l, h)
    if bad_hl:
        data_quality *= float(max(0.50, 1.0 - bad_hl / max(1, n)))

    if float(np.var(c)) <= float(min_price_variance):
        return None, "degenerate price series (zero variance)", data_quality

    clean["open"] = np.ascontiguousarray(o, dtype=np.float64)
    clean["high"] = np.ascontiguousarray(h, dtype=np.float64)
    clean["low"] = np.ascontiguousarray(l, dtype=np.float64)
    clean["close"] = np.ascontiguousarray(c, dtype=np.float64)
    clean["volume"] = vol
    clean["size"] = n
    return clean, "", float(min(1.0, max(0.0, data_quality)))

def _compute_reliability_factor(
    records: Any,
    target_confidence: float = 0.80,
    min_samples: int = 30,
    z: float = 1.96,
) -> Tuple[float, Dict[str, Any]]:
    """
    GLOBAL FUNCTION — کالیبراسیون تجربیِ confidence (بدون وابستگی جدید).

    چرا: عدد confidence در نسخهٔ فعلی یک «امتیاز هیوریستیک» است، نه احتمال
    برد. تنها راه تبدیل آن به عدد قابلاعتماد، ضرب کردن در کران پایین Wilson
    (۹۵٪) نرخ برد واقعی سیگنالهای ثبتشده است.

    ورودی:
      • records: لیستی از dict شامل یکی از کلیدهای won / was_correct /
        was_correct_direction / win / is_win / correct بههمراه confidence،
        یا یک dict تجمیعی {"wins": int, "samples": int}.
      • target_confidence: عددی که ادعا میکنیم (پیشفرض ۰.۸۰).
    خروجی: (factor, info) با factor در [0,1].
    """

    def _f(value: Any, default: float) -> float:
        try:
            if value is None:
                return float(default)
            out = float(value)
            return out if math.isfinite(out) else float(default)
        except (TypeError, ValueError, OverflowError):
            return float(default)

    target = float(min(0.98, max(0.50, _f(target_confidence, 0.80))))
    min_n = int(max(1, min_samples))
    zz = float(min(4.0, max(0.0, _f(z, 1.96))))

    wins = 0.0
    total = 0.0
    skipped = 0

    if isinstance(records, dict) and "samples" in records:
        total = max(0.0, _f(records.get("samples"), 0.0))
        wins = float(min(total, max(0.0, _f(records.get("wins"), 0.0))))
    else:
        try:
            iterator = list(records) if records is not None else []
        except (TypeError, ValueError):
            iterator = []
        for rec in iterator[-2000:]:
            if not isinstance(rec, dict):
                skipped += 1
                continue
            conf = rec.get("confidence", None)
            if conf is not None:
                conf_val = _f(conf, -1.0)
                if conf_val >= 0.0 and conf_val < target - 0.02:
                    skipped += 1
                    continue
            won = None
            for key in ("won", "was_correct_direction", "was_correct", "win", "is_win", "correct"):
                if key in rec:
                    won = bool(rec[key])
                    break
            if won is None:
                won = _f(rec.get("pnl", None), 0.0) > 0.0
            total += 1.0
            if won:
                wins += 1.0

    prior_wins = 4.0
    prior_total = 8.0
    w = wins + prior_wins
    n = total + prior_total
    p = w / n
    z2 = zz * zz
    denom = 1.0 + z2 / n
    centre = (p + z2 / (2.0 * n)) / denom
    margin = (zz / denom) * math.sqrt(max(0.0, p * (1.0 - p) / n + z2 / (4.0 * n * n)))
    lower = float(min(1.0, max(0.0, centre - margin)))
    factor = float(min(1.0, max(0.0, lower / target)))
    info: Dict[str, Any] = {
        "wins": int(wins),
        "samples": int(total),
        "skipped": int(skipped),
        "win_rate": float(p),
        "wilson_lower": float(lower),
        "target": float(target),
        "min_samples": int(min_n),
        "cold_start": bool(total < min_n),
        "factor": float(factor),
    }
    return factor, info


def finalize_strategy_output(
    result: Any,
    quality_floor: Optional[float] = None,
) -> Dict[str, Any]:
    """
    GLOBAL FUNCTION — تنها دروازهٔ مجاز خروج استراتژی (Replacement).

    قرارداد خروجی (همیشه dict، کلیدهای ثابت، بدون NaN/Inf):
      • سیگنال جهتدار با confidence >= floor → BUY/SELL همان عدد،
        combine_allowed=True در هم سطح بالا و هم metadata.
      • هر چیز دیگر (HOLD، خطا، fallback، یا confidence < floor) →
        signal="HOLD"، confidence=0.0، hold_quality<=0.35،
        active_count=0، combine_allowed=False.

    نکتهٔ مهم: این تابع در نسخهٔ فعلی شما تعریف شده ولی «هیچجا صدا زده
    نمیشود». analyze_all جدید آن را در تنها نقطهٔ return صدا میزند.
    """

    def _ff(value: Any, default: float) -> float:
        try:
            if value is None:
                return float(default)
            out = float(value)
            return out if math.isfinite(out) else float(default)
        except (TypeError, ValueError, OverflowError):
            return float(default)

    def _canonical(token: Any) -> str:
        text = str(token or "HOLD").upper().strip()
        if "BUY" in text or text in ("LONG", "BULL", "BULLISH"):
            return "BUY"
        if "SELL" in text or text in ("SHORT", "BEAR", "BEARISH"):
            return "SELL"
        return "HOLD"

    def _safe_hold(why: str) -> Dict[str, Any]:
        return {
            "signal": "HOLD",
            "confidence": 0.0,
            "hold_quality": 0.0,
            "score": 50.0,
            "reason": why,
            "strategy_name": "UNKNOWN",
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "price": 0.0,
            "signal_id": None,
            "metadata": {
                "combine_allowed": False,
                "quality_floor": _MIN_DELIVERABLE_CONFIDENCE,
                "reject_reason": why,
            },
            "is_fallback": True,
            "error_type": "QualityGateFailure",
            "is_analytical_hold": False,
            "active_count": 0,
            "combine_allowed": False,
            "quality_floor": _MIN_DELIVERABLE_CONFIDENCE,
            "raw_confidence": 0.0,
        }

    try:
        try:
            bundle_floor = float(_resolve_env_threshold_bundle()["quality_floor"])
        except Exception as bundle_exc:
            bundle_floor = _MIN_DELIVERABLE_CONFIDENCE
            logging.getLogger("StrategyQualityGate").warning(
                "threshold bundle unavailable (%s); using hard floor %.3f",
                bundle_exc, _MIN_DELIVERABLE_CONFIDENCE,
            )
        hard_floor = float(min(0.98, max(_MIN_DELIVERABLE_CONFIDENCE, bundle_floor)))
        floor = float(min(0.98, max(hard_floor, _ff(quality_floor, hard_floor))))

        if isinstance(result, dict):
            raw = dict(result)
        else:
            raw = {
                "signal": "HOLD",
                "confidence": 0.0,
                "reason": "non-dict strategy result coerced to HOLD",
                "error_type": "InvalidResultType",
            }

        raw_signal = str(raw.get("signal", "HOLD") or "HOLD").upper().strip()
        direction = _canonical(raw_signal)
        raw_conf = float(min(1.0, max(0.0, _ff(raw.get("confidence"), 0.0))))
        error_type = str(raw.get("error_type", "None") or "None")
        clean_errors = ("none", "", "null", "no error", "noerror", "no_error")
        is_error = bool(raw.get("is_fallback", False)) or (
            error_type.strip().lower() not in clean_errors
        )

        metadata = raw.get("metadata")
        meta = dict(metadata) if isinstance(metadata, dict) else {}
        reason = str(raw.get("reason", "") or "")

        veto_reason = ""
        if direction == "HOLD":
            veto_reason = "HOLD policy (no directional commitment)"
        elif is_error:
            veto_reason = "error fallback: " + error_type
        elif raw_conf + 1e-12 < floor:
            veto_reason = (
                "quality gate: confidence " + format(raw_conf, ".6f")
                + " < floor " + format(floor, ".6f")
            )

        if veto_reason:
            final_signal = "HOLD"
            final_conf = 0.0
            hq = float(min(1.0, max(0.0, _ff(raw.get("hold_quality"), 0.30))))
            hold_quality = float(min(0.30 if is_error else 0.35, hq))
            active_count = 0
            combine_allowed = False
            is_analytical_hold = not is_error
            score = 50.0
            note = (
                "[QUALITY-GATE] " + veto_reason
                + " | confidence delivered as 0.0 | excluded from module combination"
            )
            reason = (reason + " | " + note) if reason else note
        else:
            final_signal = direction
            final_conf = round(float(min(0.98, raw_conf)), 6)
            hold_quality = None
            active_count = int(max(1, _ff(raw.get("active_count"), 1)))
            combine_allowed = True
            is_analytical_hold = False
            if direction == "BUY":
                score = 50.0 + final_conf * 50.0
            else:
                score = 50.0 - final_conf * 50.0
            score = float(min(100.0, max(0.0, score)))

        meta["combine_allowed"] = bool(combine_allowed)
        meta["quality_floor"] = float(floor)
        meta["raw_confidence"] = float(raw_conf)
        meta["raw_signal"] = str(raw_signal)
        meta["confidence_semantics"] = (
            "confidence is a calibrated quality score in [0,1]; "
            "HOLD always carries confidence=0.0 and combine_allowed=False."
        )
        if veto_reason:
            meta["reject_reason"] = str(veto_reason)
        else:
            meta.pop("reject_reason", None)

        timestamp = raw.get("timestamp")
        if not isinstance(timestamp, str) or not timestamp:
            timestamp = datetime.now(timezone.utc).isoformat()

        out = dict(raw)
        out.update({
            "signal": str(final_signal),
            "confidence": float(final_conf),
            "hold_quality": hold_quality,
            "score": float(score),
            "reason": str(reason) if reason else "no reason recorded",
            "strategy_name": str(raw.get("strategy_name", "UNKNOWN") or "UNKNOWN"),
            "timestamp": str(timestamp),
            "price": float(_ff(raw.get("price"), 0.0)),
            "signal_id": raw.get("signal_id"),
            "metadata": meta,
            "is_fallback": bool(is_error),
            "error_type": str(error_type),
            "is_analytical_hold": bool(is_analytical_hold),
            "active_count": int(active_count),
            "combine_allowed": bool(combine_allowed),
            "quality_floor": float(floor),
            "raw_confidence": float(raw_conf),
        })
        if "bullish" in out or "bearish" in out:
            out["bullish"] = bool(final_signal == "BUY")
            out["bearish"] = bool(final_signal == "SELL")
        return out

    except Exception as exc:
        logging.getLogger("StrategyQualityGate").exception(
            "finalize_strategy_output failed (%s); returning safe HOLD", exc
        )
        return _safe_hold("quality gate internal failure: " + str(exc)[:120])


def finalize_signal_decision(
    signal: Any,
    confidence: Any,
    reasons: Optional[Sequence[str]] = None,
    min_confidence: float = 0.80,
    hold_quality_hint: Optional[float] = None,
) -> Dict[str, Any]:
    """
    GLOBAL FUNCTION — تصمیمگیر مشترک، همتراز با finalize_strategy_output.

    تغییرات: کف سخت ۰.۸۰ (غیرقابل کاهش)، confidence تورمی تولید نمیشود،
    HOLD همیشه ۰.۰ و combine_allowed=False دارد.
    """

    def _ff(value: Any, default: float) -> float:
        try:
            if value is None:
                return float(default)
            out = float(value)
            return out if math.isfinite(out) else float(default)
        except (TypeError, ValueError, OverflowError):
            return float(default)

    reason_parts: List[str] = []
    if reasons:
        for item in reasons:
            if item is not None:
                text = str(item).strip()
                if text:
                    reason_parts.append(text)

    conf = float(min(1.0, max(0.0, _ff(confidence, 0.0))))
    try:
        bundle_floor = float(_resolve_env_threshold_bundle()["quality_floor"])
    except Exception as exc:
        bundle_floor = _MIN_DELIVERABLE_CONFIDENCE
        logging.getLogger("StrategyQualityGate").debug("bundle unavailable: %s", exc)
    threshold = float(min(0.98, max(
        _MIN_DELIVERABLE_CONFIDENCE, bundle_floor, _ff(min_confidence, 0.80)
    )))

    raw = str(signal).strip().upper() if signal is not None else ""
    if "BUY" in raw or raw in ("LONG", "BULL", "BULLISH"):
        direction = "BUY"
    elif "SELL" in raw or raw in ("SHORT", "BEAR", "BEARISH"):
        direction = "SELL"
    elif raw in ("HOLD", "STRONG_HOLD", "NEUTRAL", "FLAT", "NONE", ""):
        direction = "HOLD"
    else:
        direction = "INVALID"

    rejected = ""
    if direction == "INVALID":
        rejected = "invalid signal token '" + raw + "'"
        reason_parts.append("Invalid signal token '" + raw + "' detected. Analytical HOLD.")
        default_quality = 0.30
    elif direction == "HOLD":
        rejected = "explicit HOLD"
        joined = " ".join(reason_parts).lower()
        weak_words = ("insufficient", "error", "invalid", "no clear", "no edge",
                      "deadzone", "quality too low")
        default_quality = 0.30 if any(k in joined for k in weak_words) else 0.35
        if not reason_parts:
            reason_parts.append("Analytical HOLD")
    elif conf + 1e-12 < threshold:
        rejected = ("confidence " + format(conf, ".4f")
                    + " < floor " + format(threshold, ".4f"))
        default_quality = 0.30
        reason_parts.append("Original " + raw + " rejected: " + rejected + ". Analytical HOLD applied.")
    else:
        default_quality = 0.30

    if rejected:
        final_signal = "HOLD"
        final_conf = 0.0
        final_score = 50.0
        quality = float(min(0.35, max(0.0, _ff(hold_quality_hint, default_quality))))
        active_count = 0
        combine_allowed = False
        final_hold = True
    else:
        final_signal = direction
        final_conf = round(conf, 6)
        if direction == "BUY":
            final_score = 50.0 + final_conf * 50.0
        else:
            final_score = 50.0 - final_conf * 50.0
        quality = None
        active_count = 1
        combine_allowed = True
        final_hold = False
        reason_parts.append(raw + " accepted at confidence " + format(final_conf, ".4f"))

    return {
        "signal": str(final_signal),
        "confidence": float(final_conf),
        "score": round(float(min(100.0, max(0.0, final_score))), 4),
        "reason": " | ".join(reason_parts) if reason_parts else "no reason recorded",
        "is_analytical_hold": bool(final_hold),
        "hold_quality": quality,
        "combine_allowed": bool(combine_allowed),
        "quality_floor": float(threshold),
        "active_count": int(active_count),
        "raw_confidence": float(conf),
        "raw_signal": str(raw),
    }

def _finite_float_or(value: Any, default: Optional[float]) -> Optional[float]:
    try:
        if value is None:
            return default
        v = float(value)
        if not np.isfinite(v):
            return default
        return v
    except (TypeError, ValueError):
        return default

def strategy_output_is_combinable(result: Any) -> bool:
    """GLOBAL FUNCTION — دروازهٔ فایل تابع ماژول (کاملاً مستقل).

    فقط سیگنال جهتدار با confidence >= 0.80، بدون fallback/خطا،
    combine_allowed=True و active_count>=1 را میپذیرد. هیچ وابستهای به
    فایل استراتژی ندارد تا بتوان آن را مستقیماً در فایل ماژول کپی کرد.
    """
    def _f(value: Any, default: float) -> float:
        try:
            if value is None:
                return float(default)
            out = float(value)
            return out if math.isfinite(out) else float(default)
        except (TypeError, ValueError, OverflowError):
            return float(default)

    if not isinstance(result, dict):
        return False

    conf = _f(result.get("confidence", 0.0), 0.0)
    if conf <= 0.0:
        return False

    signal = str(result.get("signal", "HOLD") or "HOLD").upper().strip()
    if "BUY" not in signal and "SELL" not in signal:
        return False
    if "HOLD" in signal:
        return False

    if bool(result.get("is_fallback", False)):
        return False

    error_type = str(result.get("error_type", "None") or "None").strip().lower()
    if error_type not in ("none", "", "null", "no error", "noerror", "no_error"):
        return False

    if result.get("combine_allowed") is False:
        return False

    meta = result.get("metadata")
    if isinstance(meta, dict) and meta.get("combine_allowed") is False:
        return False

    if int(_f(result.get("active_count", 1), 0.0)) < 1:
        return False

    floor = 0.80
    raw_floor = os.getenv("MIN_DELIVERABLE_CONFIDENCE")
    if raw_floor is not None and str(raw_floor).strip():
        try:
            value = float(str(raw_floor).strip())
            if math.isfinite(value):
                if value > 1.0:
                    value /= 100.0
                floor = max(floor, value)
        except (TypeError, ValueError, OverflowError):
            floor = 0.80
    if isinstance(meta, dict):
        floor = max(floor, _f(meta.get("quality_floor"), floor))
    floor = min(0.98, max(0.80, _f(result.get("quality_floor"), floor)))
    return bool(conf + 1e-12 >= floor)
    
@dataclass
class PerformanceSnapshot:
    window_size: int
    win_rate: float
    avg_confidence_on_wins: float = 0.0
    avg_confidence_on_losses: float = 0.0
    consecutive_losses: int = 0
    sharpe_proxy: float = 0.0
    last_updated: str = field(
        default_factory=lambda: datetime.now(timezone.utc).isoformat())

    def to_dict(self) -> dict:
        return {
            "window_size": self.window_size,
            "win_rate": self.win_rate,
            "avg_confidence_on_wins": self.avg_confidence_on_wins,
            "avg_confidence_on_losses": self.avg_confidence_on_losses,
            "consecutive_losses": self.consecutive_losses,
            "sharpe_proxy": self.sharpe_proxy,
            "last_updated": self.last_updated,
        }

    @classmethod
    def from_dict(cls, data: dict) -> "PerformanceSnapshot":
        data = data if isinstance(data, dict) else {}
        return cls(
            window_size=int(_finite_float_or(data.get("window_size"), 0) or 0),
            win_rate=float(_finite_float_or(data.get("win_rate"), 0.5) or 0.5),
            avg_confidence_on_wins=float(
                _finite_float_or(data.get("avg_confidence_on_wins"), 0.0) or 0.0),
            avg_confidence_on_losses=float(
                _finite_float_or(data.get("avg_confidence_on_losses"), 0.0) or 0.0),
            consecutive_losses=int(
                _finite_float_or(data.get("consecutive_losses"), 0) or 0),
            sharpe_proxy=float(
                _finite_float_or(data.get("sharpe_proxy"), 0.0) or 0.0),
            last_updated=str(
                data.get("last_updated") or datetime.now(timezone.utc).isoformat()),
        )


def compute_adaptive_multiplier(
    current_multiplier: float,
    snapshot: Optional[PerformanceSnapshot],
    min_samples: int = 200,
    smoothing_alpha: float = 0.15,
    baseline_win_rate: float = 0.50,
    sensitivity: float = 0.6,
    circuit_breaker_losses: int = 5,
    multiplier_min: float = 0.75,
    multiplier_max: float = 1.25,
    logger: Optional[logging.Logger] = logger,
    strategy_name: str = "UNKNOWN",
) -> float:
    log = logger or logging.getLogger("AdaptiveMultiplier")
    phase = f"{strategy_name.upper()}_ADAPTIVE"
    try:
        if snapshot is None:
            return current_multiplier
        if snapshot.window_size < min_samples:
            return current_multiplier
        if snapshot.consecutive_losses >= circuit_breaker_losses:
            log.debug(f"[{phase}] Circuit breaker: {snapshot.consecutive_losses} losses")
            return current_multiplier
        win_rate = float(snapshot.win_rate)
        diff = (win_rate - baseline_win_rate) * 2.0
        target = 1.0 + sensitivity * diff
        new_multiplier = (1.0 - smoothing_alpha) * current_multiplier + smoothing_alpha * target
        new_multiplier = max(multiplier_min, min(multiplier_max, new_multiplier))
        if abs(new_multiplier - current_multiplier) > 0.01:
            log.debug(
                f"[{phase}] Multiplier: {current_multiplier:.3f} -> {new_multiplier:.3f} "
                f"(WR: {win_rate:.1%}, Losses: {snapshot.consecutive_losses})"
            )
        return float(new_multiplier)
    except Exception as e:
        log.error(f"[{phase}] Error: {e}", exc_info=True)
        return current_multiplier

class StrategyBaseMixin:
    """
    Unified base mixin for all strategy classes.
    Guarantees:
      • Safe fallback generation (_fallback_result, _build_fallback).
      • Consistent validation (NO broken super() calls).
      • Performance snapshot hooks.
      • Statistics counters (_bump_stat).
      • Reason-aware HOLD quality (_hold_quality_from_reason).
      • No silent crashes.
    """
    DEFAULT_VALIDATION_CONFIG: ClassVar[Dict[str, Any]] = {
        "min_bars_required": 500,
        "max_nan_ratio": 0.30,
        "min_price_value": 1e-8,
        "min_variance_threshold": 1e-10,
        "required_columns": ['open', 'high', 'low', 'close'],
        "allow_volume_missing": True,
    }
    DEFAULT_SELF_TEST_CONFIG: ClassVar[Dict[str, Any]] = {
        "enable": True,
        "min_tests": 5,
    }

    def __init__(self, *args, **kwargs):
        super().__init__()
        self.name = getattr(self, "name", "BaseStrategy")
        self.category = getattr(self, "category", "base")
        if not hasattr(self, "logger") or self.logger is None:
            self.logger = logger
        self._lock = threading.RLock()
        self._stats: Dict[str, Any] = {
            "total_signals": 0,
            "win_rate": 0.5,
            "avg_confidence": 0.0,
            "last_signal_time": None,
            "consecutive_losses": 0,
            "sharpe_proxy": 0.0,
            "fallback_count": 0,
            "error_count": 0,
            "hold_signals": 0,
        }
        self._learning_buffer: Deque[Dict] = deque(maxlen=1000)
        self._performance_multiplier: float = 1.0
        self._last_snapshot: Optional[PerformanceSnapshot] = None

    # ═══════════════════════════════════════════════════════════════════
    # NEW: statistics counter (was missing on several strategies)
    # ═══════════════════════════════════════════════════════════════════
    def _bump_stat(self, key: str, amount: int = 1) -> None:
        """
        Thread-safe increment of a statistics counter.

        Safe under every condition:
          • `self._stats` missing or not a dict → silent no-op.
          • `self._lock` missing → falls back to unlocked write.
          • Non-int `amount` → coerced via int().
          • Any exception → swallowed (never breaks analyze_all).
        """
        try:
            stats = getattr(self, "_stats", None)
            if not isinstance(stats, dict):
                return
            try:
                inc = int(amount)
            except (TypeError, ValueError):
                inc = 1
            lock = getattr(self, "_lock", None)
            if lock is not None:
                try:
                    with lock:
                        stats[key] = int(stats.get(key, 0)) + inc
                    return
                except Exception:
                    pass
            stats[key] = int(stats.get(key, 0)) + inc
        except Exception:
            pass

    # ═══════════════════════════════════════════════════════════════════
    # NEW: reason-aware HOLD quality (was missing on several strategies)
    # ═══════════════════════════════════════════════════════════════════
    def _hold_quality_from_reason(
        self,
        reason: str,
        is_fallback: bool = False,
        error_type: str = "None",
    ) -> float:
        """Wrapper around the module-level reason-aware hold-quality estimator."""
        try:
            return float(_infer_hold_quality_from_reason(
                reason=str(reason or ""),
                is_fallback=bool(is_fallback),
                error_type=str(error_type or "None"),
            ))
        except Exception:
            return 0.60

    # ═══════════════════════════════════════════════════════════════════
    # NEW: generic fallback result builder (was missing on several strategies)
    # ═══════════════════════════════════════════════════════════════════
    def _fallback_result(
        self,
        reason: str,
        error: Optional[BaseException] = None,
        price: float = 0.0,
        kind: str = "ANALYTICAL",
        metadata: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """
        Generic fallback result builder inherited by every strategy.

        ``kind``:
          * "ANALYTICAL" → considered no-trade decision  (is_fallback=False)
          * "DATA"       → input not yet usable           (is_fallback=False)
          * "ERROR"      → genuine failure                (is_fallback=True)
        """
        kind_norm = str(kind or "ANALYTICAL").upper()
        if error is not None:
            kind_norm = "ERROR"
        if kind_norm not in ("ANALYTICAL", "DATA", "ERROR"):
            kind_norm = "ANALYTICAL"

        error_type = type(error).__name__ if error is not None else "None"
        is_error = kind_norm == "ERROR"

        if is_error:
            hq, score = 0.30, 0.0
            prefix = "ERROR FALLBACK"
        elif kind_norm == "DATA":
            hq, score = 0.55, 50.0
            prefix = "DATA HOLD"
        else:
            try:
                hq = float(np.clip(
                    self._hold_quality_from_reason(reason, False, "None"),
                    0.55, 0.90,
                ))
            except Exception:
                hq = 0.70
            score = 50.0
            prefix = "ANALYTICAL HOLD"

        try:
            price_out = float(price) if price is not None else 0.0
            if not math.isfinite(price_out):
                price_out = 0.0
        except (TypeError, ValueError):
            price_out = 0.0

        meta = dict(metadata or {})
        meta.update({
            "fallback_reason": str(reason),
            "fallback_kind": kind_norm,
            "error_type": error_type,
            "hold_quality": hq,
            "is_analytical_hold": not is_error,
            "confidence_semantics": (
                "HOLD carries confidence=0.0 by policy; hold_quality reflects "
                "the quality of the decision to stand aside."
            ),
        })

        # Counters — safe thanks to the new _bump_stat
        self._bump_stat("fallback_count")
        if is_error:
            self._bump_stat("error_count")
        if not is_error:
            self._bump_stat("hold_signals")

        return {
            "signal": "HOLD",
            "confidence": 0.0,
            "hold_quality": hq,
            "score": float(score),
            "reason": f"[{getattr(self, 'name', 'Strategy')}] {prefix}: {reason}",
            "strategy_name": getattr(self, "name", "Strategy"),
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "price": price_out,
            "metadata": meta,
            "is_fallback": is_error,
            "error_type": error_type,
            "active_count": 0,
            "is_analytical_hold": not is_error,
        }

    # ═══════════════════════════════════════════════════════════════════
    # EXISTING METHODS (unchanged)
    # ═══════════════════════════════════════════════════════════════════
    def _validate_input(
        self,
        df: Optional[pd.DataFrame] = None,
        *,
        high: Optional[np.ndarray] = None,
        low: Optional[np.ndarray] = None,
        close: Optional[np.ndarray] = None,
        open_price: Optional[np.ndarray] = None,
        df_dict: Optional[Dict[str, pd.DataFrame]] = None,
        min_length: Optional[int] = None,
        allow_nan: bool = False,
        allow_empty: bool = False,
        check_volume: bool = True,
        **kwargs,
    ) -> Tuple[bool, str, Any]:
        """Default validation logic for strategy inputs."""
        try:
            if df_dict is not None:
                if not isinstance(df_dict, dict) or not df_dict:
                    return False, "df_dict is empty or invalid", df_dict
                return True, "df_dict provided", df_dict

            if df is not None:
                if not isinstance(df, pd.DataFrame):
                    return False, f"Expected DataFrame, got {type(df).__name__}", None
                if df.empty and not allow_empty:
                    return False, "DataFrame is empty", None

                min_len = min_length if min_length is not None else int(
                    getattr(self, "config", {}).get("min_bars_required", 500)
                )
                if len(df) < min_len:
                    return False, (
                        f"Insufficient data: {len(df)} bars < {min_len} required"
                    ), None

                required_cols = getattr(self, "config", {}).get(
                    "required_columns", ['open', 'high', 'low', 'close']
                )
                missing = [col for col in required_cols if col not in df.columns]
                if missing:
                    return False, f"Missing required columns: {missing}", None

                if not allow_nan:
                    nan_ratio = float(
                        df[required_cols].isna().sum().sum()
                    ) / (len(df) * len(required_cols)) if len(df) > 0 else 1.0
                    max_nan = float(
                        getattr(self, "config", {}).get("max_nan_ratio", 0.30)
                    )
                    if nan_ratio > max_nan:
                        return False, (
                            f"Too many NaN values: {nan_ratio:.1%} > {max_nan:.1%}"
                        ), None

                return True, "Validation passed", df

            if close is not None:
                arr_len = len(close)
                min_len = min_length if min_length is not None else int(
                    getattr(self, "config", {}).get("min_bars_required", 500)
                )
                if arr_len < min_len:
                    return False, (
                        f"Insufficient array length: {arr_len} < {min_len}"
                    ), None
                return True, "Array validation passed", {
                    "close": close, "high": high, "low": low,
                    "open": open_price,
                }

            return False, (
                "No valid input data provided (df, df_dict, or close array required)"
            ), None
        except Exception as e:
            self.logger.debug(f"[{self.name}] Validation error: {e}")
            return False, f"Validation exception: {str(e)[:100]}", None

    def _build_fallback(
        self,
        reason: str,
        error_type: str = "GenericError",
        **kwargs,
    ) -> Dict[str, Any]:
        """Generates a safe, standardized fallback response."""
        safe_reason = str(reason or "Unknown strategy failure")
        safe_error_type = str(error_type or "GenericError")

        self._bump_stat("fallback_count")
        self._bump_stat("hold_signals")
        self._bump_stat("total_signals")

        return {
            "signal": "HOLD",
            "confidence": 0.0,
            "hold_quality": 0.55,
            "score": 50.0,
            "reason": f"[{self.name}] ANALYTICAL HOLD: {safe_reason}",
            "active_count": 0,
            "metadata": {
                "strategy_name": self.name,
                "category": self.category,
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "is_fallback": True,
                "error_type": safe_error_type,
                "hold_quality": 0.55,
                "is_analytical_hold": True,
            },
            "is_fallback": True,
            "error_type": safe_error_type,
            "is_analytical_hold": True,
        }

    def update_performance_snapshot(
        self, snapshot: Optional[PerformanceSnapshot]
    ) -> None:
        try:
            with self._lock:
                self._last_snapshot = snapshot
                if snapshot is not None:
                    self._performance_multiplier = compute_adaptive_multiplier(
                        current_multiplier=self._performance_multiplier,
                        snapshot=snapshot,
                        min_samples=self.config.get("adaptive_min_samples", 200),
                        smoothing_alpha=self.config.get("adaptive_smoothing_alpha", 0.15),
                        baseline_win_rate=self.config.get("adaptive_baseline_win_rate", 0.50),
                        sensitivity=self.config.get("adaptive_sensitivity", 0.6),
                        circuit_breaker_losses=self.config.get("adaptive_circuit_breaker_losses", 5),
                        multiplier_min=self.config.get("adaptive_multiplier_min", 0.75),
                        multiplier_max=self.config.get("adaptive_multiplier_max", 1.25),
                        logger=self.logger,
                        strategy_name=self.name,
                    )
        except Exception as exc:
            self.logger.error(f"[{self.name}_PERF_SNAPSHOT] {exc}", exc_info=True)

    def get_stats(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "strategy_name": self.name,
                "statistics": dict(self._stats),
                "timeframe": getattr(self, "timeframe", "UNKNOWN"),
                "performance_multiplier": self._performance_multiplier,
            }

    def reset_stats(self) -> None:
        with self._lock:
            for key, value in list(self._stats.items()):
                if key == "win_rate":
                    self._stats[key] = 0.5
                elif key == "last_signal_time":
                    self._stats[key] = None
                elif isinstance(value, float):
                    self._stats[key] = 0.0
                else:
                    self._stats[key] = 0
            self._learning_buffer.clear()
        self.logger.info("[%s] statistics reset", self.name)

    def self_test(self, sample_df: Optional[pd.DataFrame] = None) -> Dict[str, Any]:
        """Run deterministic local correctness checks."""
        results: Dict[str, Any] = {}
        try:
            results["base_mixin_works"] = True
            results["all_passed"] = True
            results["total_tests"] = 1
            results["passed_tests"] = 1
        except Exception as exc:
            self.logger.error(f"[{self.name}_SELF_TEST] {exc}", exc_info=True)
            results["all_passed"] = False
            results["error"] = str(exc)
        return results
        
def _run_coro_in_fresh_loop(coro: Any) -> Any:
    """Run a coroutine on a brand-new event loop (helper for worker thread)."""
    return asyncio.run(coro)


def create_test_data(
    bars: int = 300,
    seed: int = 42,
    start_price: float = 100.0,
    volatility: float = 0.5,
    include_volume: bool = True,
) -> pd.DataFrame:
    rng = np.random.default_rng(seed)
    vol = max(1e-8, float(volatility))
    returns = rng.standard_normal(bars) * vol / 100.0
    close = start_price * np.exp(np.cumsum(returns))
    high = close + np.abs(rng.standard_normal(bars) * vol / 100.0 * close)
    low = close - np.abs(rng.standard_normal(bars) * vol / 100.0 * close)
    open_price = close + rng.standard_normal(bars) * vol / 200.0 * close
    high = np.maximum(high, np.maximum(open_price, close))
    low = np.minimum(low, np.minimum(open_price, close))

    if include_volume:
        volume = 1000.0 + np.abs(rng.standard_normal(bars) * 200.0)
    else:
        volume = np.ones(bars)

    dates = pd.date_range(end=datetime.now(timezone.utc), periods=bars, freq='1h')
    return pd.DataFrame({
        'open': open_price, 'high': high, 'low': low,
        'close': close, 'volume': volume,
    }, index=dates)


def extract_ohlcv_arrays(
    df: Optional[pd.DataFrame],
    *,
    require_volume: bool = False,
) -> Optional[Dict[str, Any]]:
    """
    Fast extraction of contiguous float64 arrays from an OHLCV DataFrame —
    cheapest safe bridge to Numba kernels.
    """
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return None
    try:
        missing = [c for c in ("open", "high", "low", "close") if c not in df.columns]
        if missing or (require_volume and "volume" not in df.columns):
            return None
        out: Dict[str, Any] = {}
        for col in ("open", "high", "low", "close"):
            out[col] = np.ascontiguousarray(df[col].to_numpy(dtype=np.float64))
        if "volume" in df.columns:
            out["volume"] = np.ascontiguousarray(df["volume"].to_numpy(dtype=np.float64))
        else:
            out["volume"] = np.ones(len(df), dtype=np.float64)
        out["size"] = len(df)
        return out
    except (ValueError, TypeError, KeyError):
        return None

# ═══════════════════════════════════════════════════════════════════════════
# SECTION 20 — UnifiedConfidenceManager
# ═══════════════════════════════════════════════════════════════════════════

class UnifiedConfidenceManager:
    _instance = None
    _lock = threading.Lock()

    def __new__(cls):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
                    cls._instance._initialized = False
        return cls._instance

    def __init__(self):
        if getattr(self, '_initialized', False):
            return
        self._initialized = True
        self._logger = logger
        self._stats_lock = threading.Lock()
        self._stats = {
            "total_calls": 0,
            "adjustments_applied": 0,
            "adjustments_by_strategy": {},
            "final_confidences": [],
        }
        self._min_confidence_floor = 0.25
        self._max_confidence_cap = 0.95
        self._default_confidence = 0.45
        self._adaptive_thresholds = {
            "low_quality_data": 0.30,
            "single_timeframe": 0.35,
            "low_agreement": 0.40,
            "normal": 0.45,
            "high_quality": 0.55,
        }

    def calculate_confidence(
        self,
        base_confidence: float = 0.50,
        *,
        strategy_name: str = "UNKNOWN",
        regime: Optional[str] = None,
        data_quality: Optional[float] = None,
        agreement: Optional[float] = None,
        active_count: Optional[int] = None,
        total_count: Optional[int] = None,
        mtf_confirmed: bool = False,
        volume_confirmed: bool = False,
        pattern_quality: float = 0.0,
        **kwargs,
    ) -> float:
        phase = f"UNIFIED_CONF_{strategy_name}"
        try:
            base_conf = self._sanitize_confidence(base_confidence)
            dq = self._sanitize_confidence(data_quality, default=0.80)
            ag = self._sanitize_confidence(agreement, default=0.50)

            confidence = base_conf
            if dq < 0.50:
                confidence *= (0.70 + dq * 0.30)
            if ag < 0.30:
                confidence *= (0.60 + ag * 0.40)
            elif ag > 0.70:
                confidence *= (0.90 + ag * 0.10)

            if active_count is not None and total_count is not None:
                ratio = active_count / max(total_count, 1)
                if ratio < 0.30:
                    confidence *= (0.70 + ratio * 0.30)
                elif ratio > 0.70:
                    confidence *= (0.90 + ratio * 0.10)

            if mtf_confirmed:
                confidence *= 1.10
            if volume_confirmed:
                confidence *= 1.05
            if pattern_quality > 0.0:
                confidence *= (0.90 + pattern_quality * 0.10)

            confidence = max(self._min_confidence_floor,
                             min(self._max_confidence_cap, confidence))
            with self._stats_lock:
                self._stats["total_calls"] += 1
                self._stats["final_confidences"].append(confidence)
                if len(self._stats["final_confidences"]) > 1000:
                    self._stats["final_confidences"] = \
                        self._stats["final_confidences"][-500:]
            return float(confidence)
        except Exception as e:
            self._logger.error(f"[{phase}] Error: {e}", exc_info=True)
            return self._default_confidence

    def _sanitize_confidence(self, value: Any, default: float = 0.50) -> float:
        try:
            if value is None:
                return default
            v = float(value)
            if np.isnan(v) or np.isinf(v):
                return default
            return max(0.0, min(1.0, v))
        except (TypeError, ValueError):
            return default

    def get_statistics(self) -> Dict[str, Any]:
        with self._stats_lock:
            snapshot = dict(self._stats)
            confidences = list(snapshot["final_confidences"])
        return {
            "total_calls": int(snapshot["total_calls"]),
            "adjustments_applied": int(snapshot["adjustments_applied"]),
            "adjustments_by_strategy": dict(snapshot["adjustments_by_strategy"]),
            "avg_confidence": float(np.mean(confidences)) if confidences else 0.0,
            "min_confidence": float(np.min(confidences)) if confidences else 0.0,
            "max_confidence": float(np.max(confidences)) if confidences else 0.0,
            "sample_count": len(confidences),
        }

    def reset_statistics(self) -> None:
        with self._stats_lock:
            self._stats = {
                "total_calls": 0,
                "adjustments_applied": 0,
                "adjustments_by_strategy": {},
                "final_confidences": [],
            }

    def set_adaptive_thresholds(self, thresholds: Dict[str, float]) -> None:
        if not isinstance(thresholds, dict):
            return
        for key, value in thresholds.items():
            if key in self._adaptive_thresholds:
                try:
                    v = float(value)
                except (TypeError, ValueError):
                    continue
                if math.isfinite(v):
                    self._adaptive_thresholds[key] = max(0.10, min(0.90, v))


_unified_conf_manager = None
_unified_conf_manager_lock = threading.Lock()


def get_unified_confidence_manager() -> UnifiedConfidenceManager:
    global _unified_conf_manager
    if _unified_conf_manager is None:
        with _unified_conf_manager_lock:
            if _unified_conf_manager is None:
                _unified_conf_manager = UnifiedConfidenceManager()
    return _unified_conf_manager


def calculate_unified_confidence(
    base_confidence: float,
    regime_alignment: float = 1.0,
    data_quality: float = 1.0,
    agreement: float = 1.0,
    active_count: int = 0,
    total_count: int = 1,
    pattern_boost: float = 0.0,
    confluence_bonus: float = 0.0,
    quality_boost: float = 0.0,
    mtf_boost: float = 0.0,
    regime_bonus: float = 0.0,
    strength: float = 0.0,
    volume_boost: float = 0.0,
    divergence_boost: float = 0.0,
    mtf_confirmed: bool = False,
    regime: Optional[str] = None,
    strategy_name: Optional[str] = None,
    logger: Optional[logging.Logger] = logger,
) -> float:
    """
    Replacement — deflated, bounded, honest confidence blender.

    The old version ADDED up to ~0.83 of bonuses on top of the base score and
    multiplied by up to 2.0x, manufacturing 0.95 claims out of 0.5 evidence.
    This version:
      * bonuses are bounded additive factors (total boost <= +12%)
      * penalties are bounded (total <= -35%)
      * the result can never exceed base + 0.15
      * hard cap 0.98
    Signature is unchanged → all existing call sites remain compatible.
    """
    phase = "UNIFIED_CONFIDENCE_V4"
    log = logger or logging.getLogger("UnifiedConfidence")

    def _safe_f(v, d):
        try:
            if v is None:
                return d
            f = float(v)
            return f if np.isfinite(f) else d
        except (TypeError, ValueError):
            return d

    try:
        base = float(np.clip(_safe_f(base_confidence, 0.0), 0.0, 1.0))
        regime_alignment = float(np.clip(_safe_f(regime_alignment, 1.0), 0.0, 1.5))
        data_quality = float(np.clip(_safe_f(data_quality, 1.0), 0.0, 1.0))
        agreement = float(np.clip(_safe_f(agreement, 1.0), 0.0, 1.0))
        active_count = max(0, int(active_count or 0))
        total_count = max(1, int(total_count or 1))

        score = base

        # ── bounded positive boost (cap: +12% total) ──
        boost = 0.0
        boost += min(0.06, max(0.0, _safe_f(regime_bonus, 0.0)))
        boost += min(0.04, max(0.0, _safe_f(pattern_boost, 0.0)))
        boost += min(0.05, max(0.0, _safe_f(confluence_bonus, 0.0)))
        boost += min(0.04, max(0.0, _safe_f(quality_boost, 0.0)))
        boost += min(0.06, max(0.0, _safe_f(mtf_boost, 0.0)))
        boost += min(0.04, max(0.0, _safe_f(strength, 0.0)))
        boost += min(0.04, max(0.0, _safe_f(volume_boost, 0.0)))
        boost += min(0.04, max(0.0, _safe_f(divergence_boost, 0.0)))
        if bool(mtf_confirmed):
            boost += 0.05
        if active_count >= 3 and total_count >= 5:
            boost += 0.03
        score *= (1.0 + min(0.12, boost))

        # ── bounded regime alignment (was up to 2.0x) ──
        if regime_alignment > 0.0:
            score *= float(np.clip(regime_alignment, 0.5, 1.5))

        # ── bounded negative factors (cap: -35% total) ──
        penalty = 0.0
        if data_quality < 0.5:
            penalty += 0.15 * (1.0 - data_quality / 0.5)
        if agreement < 0.3:
            penalty += 0.15 * (1.0 - agreement / 0.3)
        if active_count == 0:
            penalty += 0.10
        if regime and ("RANGE" in str(regime).upper() or "SIDEWAYS" in str(regime).upper()):
            penalty += 0.10
        score *= (1.0 - min(0.35, penalty))

        # ── evidence cap: never claim more than base + 0.15 ──
        score = min(score, base + 0.15)
        return float(np.clip(score, 0.0, 0.98))

    except Exception as e:
        log.error(f"[{phase}] Error in unified confidence: {e}", exc_info=True)
        return float(np.clip(_safe_f(base_confidence, 0.0), 0.0, 0.98))

def calibrate_strategy_confidence(
    records: Any,
    stats: Dict[str, Any],
    raw_confidence: float,
    floor: float = 0.80,
    min_samples: int = 30,
    circuit_breaker_losses: int = 5,
    z: float = 1.96,
    reliability_enabled: bool = True,
    circuit_breaker_enabled: bool = True,
) -> Tuple[float, Dict[str, Any]]:
    """
    NEW — empirical confidence calibration (Wilson lower bound on realized wins).

    Returns (deliverable_confidence, info) where info["status"] is one of:
      * "disabled"         → reliability disabled by config → raw returned
      * "circuit_breaker"  → >= N consecutive losses        → 0.0
      * "cold_start"       → fewer than min_samples closed  → min(raw, floor-0.01)
      * "unproven"         → Wilson lower < floor           → 0.0
      * "calibrated"       → min(raw, wilson_lower + 0.05)

    records: list of dicts (learning buffer) — each with "was_correct" or
             won/was_correct_direction/win/is_win/correct or "pnl".
    stats:   strategy stats dict with "_wins", "_closed", "consecutive_losses".
    """

    def _f(value: Any, default: float) -> float:
        try:
            if value is None:
                return float(default)
            out = float(value)
            return out if math.isfinite(out) else float(default)
        except (TypeError, ValueError, OverflowError):
            return float(default)

    floor = float(min(0.98, max(0.50, _f(floor, 0.80))))
    raw = float(min(0.98, max(0.0, _f(raw_confidence, 0.0))))
    stats = stats if isinstance(stats, dict) else {}

    if not reliability_enabled:
        return raw, {
            "status": "disabled", "proven": None, "wins": 0, "samples": 0,
            "reason": "reliability calibration disabled by config",
        }

    if circuit_breaker_enabled:
        consecutive = int(_f(stats.get("consecutive_losses"), 0.0))
        if consecutive >= max(1, int(circuit_breaker_losses)):
            return 0.0, {
                "status": "circuit_breaker", "proven": None,
                "wins": int(_f(stats.get("_wins"), 0.0)),
                "samples": int(_f(stats.get("_closed"), 0.0)),
                "consecutive_losses": consecutive,
                "reason": (f"circuit breaker tripped: {consecutive} consecutive losses; "
                           f"trading paused until a winning trade resets the counter"),
            }

    try:
        source = list(records) if records is not None else []
    except (TypeError, ValueError):
        source = []

    recent_wins = 0
    recent_total = 0
    for rec in source[-2000:]:
        if not isinstance(rec, dict):
            continue
        if "was_correct" in rec:
            ok = bool(rec["was_correct"])
        elif any(k in rec for k in ("won", "was_correct_direction", "win", "is_win", "correct")):
            ok = bool(rec.get("won", rec.get("was_correct_direction",
                          rec.get("win", rec.get("is_win", rec.get("correct"))))))
        else:
            ok = _f(rec.get("pnl"), 0.0) > 0.0
        recent_total += 1
        if ok:
            recent_wins += 1

    wins, total, scope = recent_wins, recent_total, "recent_window"
    min_n = int(max(1, min_samples))
    if total < min_n:
        all_wins = int(_f(stats.get("_wins"), 0.0))
        all_total = int(_f(stats.get("_closed"), 0.0))
        if all_total >= min_n:
            wins, total, scope = all_wins, all_total, "all_time"
        else:
            capped = float(min(raw, floor - 0.01))
            return capped, {
                "status": "cold_start", "proven": None,
                "wins": int(recent_wins + all_wins),
                "samples": int(recent_total + all_total),
                "min_samples": min_n,
                "reason": (f"cold start: {int(recent_total + all_total)}/{min_n} closed outcomes; "
                           f"confidence capped below the gate until the track record is proven"),
            }

    factor, info = _compute_reliability_factor(
        {"wins": int(wins), "samples": int(total)},
        target_confidence=floor,
        min_samples=min_n,
        z=float(z),
    )
    proven = float(info.get("wilson_lower", 0.0))
    if proven + 1e-12 < floor:
        return 0.0, {
            "status": "unproven", "proven": proven,
            "wins": int(wins), "samples": int(total), "scope": scope,
            "reason": (f"proven accuracy {proven:.1%} (Wilson 95% lower, "
                       f"{int(total)} samples, {scope}) is below the {floor:.0%} gate"),
        }
    calibrated = float(min(raw, proven + 0.05, 0.98))
    return calibrated, {
        "status": "calibrated", "proven": proven,
        "wins": int(wins), "samples": int(total), "scope": scope,
        "wilson_lower": proven,
        "reason": (f"calibrated to proven accuracy {proven:.1%} "
                   f"({int(total)} samples, {scope})"),
    }
    
_SHARED_TECH_ANALYZER: Optional[TechnicalAnalyzer] = None
_SHARED_TA_LOCK = threading.Lock()


def get_shared_technical_analyzer() -> TechnicalAnalyzer:
    global _SHARED_TECH_ANALYZER
    if _SHARED_TECH_ANALYZER is None:
        with _SHARED_TA_LOCK:
            if _SHARED_TECH_ANALYZER is None:
                _SHARED_TECH_ANALYZER = TechnicalAnalyzer()
    return _SHARED_TECH_ANALYZER



