# SECTION 23 — safe_db_operation
# ═══════════════════════════════════════════════════════════════════════════

def safe_db_operation(
    db_path: str,
    query: str,
    params: Tuple[Any, ...] = (),
    operation_type: str = "EXECUTE",
    max_retries: int = 3,
    retry_delay: float = 0.5,
    logger: Optional[logging.Logger] = logger,
) -> Optional[Any]:
    if logger is None:
        logger = logger

    op = str(operation_type).upper().strip()

    try:
        if db_path and os.path.dirname(db_path):
            os.makedirs(os.path.dirname(db_path), exist_ok=True)
    except Exception:
        pass

    for attempt in range(max_retries):
        conn: Optional[sqlite3.Connection] = None
        cursor: Optional[sqlite3.Cursor] = None
        try:
            conn = sqlite3.connect(db_path, timeout=10.0)
            cursor = conn.cursor()

            if op == "EXECUTE":
                cursor.execute(query, params)
                conn.commit()
                result = {
                    "rowcount": int(cursor.rowcount),
                    "lastrowid": int(cursor.lastrowid) if cursor.lastrowid is not None else None,
                    "ok": True,
                }
                return result

            if op == "FETCHONE":
                cursor.execute(query, params)
                return cursor.fetchone()

            if op == "FETCHALL":
                cursor.execute(query, params)
                rows = cursor.fetchall()
                return list(rows) if rows is not None else []

            raise ValueError(f"Unknown operation_type: {operation_type}")

        except sqlite3.OperationalError as e:
            logger.warning(
                f"[SafeDB] OperationalError attempt {attempt + 1}/{max_retries}: {e}")
            if attempt == max_retries - 1:
                logger.error(
                    f"[SafeDB] Failed after {max_retries} attempts: {e}", exc_info=True)
                return None
            time.sleep(retry_delay * (2 ** attempt))

        except sqlite3.IntegrityError as e:
            logger.warning(f"[SafeDB] IntegrityError (no retry): {e}")
            return None

        except ValueError as e:
            logger.error(f"[SafeDB] Invalid operation: {e}", exc_info=True)
            return None

        except Exception as e:
            logger.error(f"[SafeDB] Unexpected error: {e}", exc_info=True)
            return None

        finally:
            if cursor is not None:
                try:
                    cursor.close()
                except Exception:
                    pass
            if conn is not None:
                try:
                    conn.close()
                except Exception:
                    pass

    return None

@njit(cache=True)
def _osc_rolling_mad_1d(arr: np.ndarray, period: int) -> np.ndarray:
    n = arr.shape[0]
    out = np.empty(n, dtype=np.float64)
    if n == 0:
        return out
    if period <= 1:
        for i in range(n):
            out[i] = 0.0
        return out
    for i in range(min(period - 1, n)):
        out[i] = np.nan
    inv_p = 1.0 / float(period)
    for i in range(period - 1, n):
        start = i - period + 1
        s = 0.0
        for j in range(start, i + 1):
            s += arr[j]
        mean = s * inv_p
        mad = 0.0
        for j in range(start, i + 1):
            mad += abs(arr[j] - mean)
        out[i] = mad * inv_p
    return out


@njit(cache=True)
def _osc_rolling_max_min_1d(
    high: np.ndarray, low: np.ndarray, period: int
) -> Tuple[np.ndarray, np.ndarray]:
    n = high.shape[0]
    hh = np.empty(n, dtype=np.float64)
    ll = np.empty(n, dtype=np.float64)
    if n == 0:
        return hh, ll
    if period <= 1:
        for i in range(n):
            hh[i] = high[i]
            ll[i] = low[i]
        return hh, ll
    cur_h = high[0]
    cur_l = low[0]
    for i in range(min(period - 1, n)):
        if high[i] > cur_h:
            cur_h = high[i]
        if low[i] < cur_l:
            cur_l = low[i]
        hh[i] = cur_h
        ll[i] = cur_l
    for i in range(period - 1, n):
        start = i - period + 1
        h_max = high[start]
        l_min = low[start]
        for j in range(start + 1, i + 1):
            hj = high[j]
            lj = low[j]
            if hj > h_max:
                h_max = hj
            if lj < l_min:
                l_min = lj
        hh[i] = h_max
        ll[i] = l_min
    return hh, ll


@njit(cache=True)
def _fast_stochastic_1d(
    high: np.ndarray, low: np.ndarray, close: np.ndarray, period: int, smooth: int
) -> Tuple[np.ndarray, np.ndarray]:
    n = close.shape[0]
    k_raw = np.empty(n, dtype=np.float64)
    if n == 0:
        return k_raw, np.empty(0, dtype=np.float64)
    p = max(2, period)
    s = max(1, smooth)
    for i in range(n):
        start = 0 if i < p - 1 else i - p + 1
        hh = high[start]
        ll = low[start]
        for j in range(start + 1, i + 1):
            if high[j] > hh:
                hh = high[j]
            if low[j] < ll:
                ll = low[j]
        rng = hh - ll
        if rng > 1e-12:
            val = 100.0 * (close[i] - ll) / rng
            if val < 0.0:
                val = 0.0
            elif val > 100.0:
                val = 100.0
            k_raw[i] = val
        else:
            k_raw[i] = 50.0

    k_sm = np.empty(n, dtype=np.float64)
    for i in range(n):
        start = 0 if i < s - 1 else i - s + 1
        cnt = i - start + 1
        acc = 0.0
        for j in range(start, i + 1):
            acc += k_raw[j]
        k_sm[i] = acc / float(cnt)

    d_sm = np.empty(n, dtype=np.float64)
    for i in range(n):
        start = 0 if i < s - 1 else i - s + 1
        cnt = i - start + 1
        acc = 0.0
        for j in range(start, i + 1):
            acc += k_sm[j]
        d_sm[i] = acc / float(cnt)

    return k_sm, d_sm


@njit(cache=True)
def _fast_williams_r_1d(
    high: np.ndarray, low: np.ndarray, close: np.ndarray, period: int
) -> np.ndarray:
    n = close.shape[0]
    wr = np.empty(n, dtype=np.float64)
    if n == 0:
        return wr
    p = max(2, period)
    for i in range(n):
        start = 0 if i < p - 1 else i - p + 1
        hh = high[start]
        ll = low[start]
        for j in range(start + 1, i + 1):
            if high[j] > hh:
                hh = high[j]
            if low[j] < ll:
                ll = low[j]
        rng = hh - ll
        if rng > 1e-12:
            val = -100.0 * (hh - close[i]) / rng
            if val < -100.0:
                val = -100.0
            elif val > 0.0:
                val = 0.0
            wr[i] = val
        else:
            wr[i] = -50.0
    return wr


@njit(cache=True)
def _fast_cci_1d(
    high: np.ndarray, low: np.ndarray, close: np.ndarray, period: int
) -> np.ndarray:
    n = close.shape[0]
    cci = np.empty(n, dtype=np.float64)
    if n == 0:
        return cci
    p = max(2, period)
    tp = np.empty(n, dtype=np.float64)
    for i in range(n):
        tp[i] = (high[i] + low[i] + close[i]) / 3.0
    for i in range(n):
        start = 0 if i < p - 1 else i - p + 1
        cnt = i - start + 1
        if cnt < 2:
            cci[i] = 0.0
            continue
        acc = 0.0
        for j in range(start, i + 1):
            acc += tp[j]
        mean = acc / float(cnt)
        mad = 0.0
        for j in range(start, i + 1):
            mad += abs(tp[j] - mean)
        mad /= float(cnt)
        denom = 0.015 * mad
        if denom > 1e-12:
            val = (tp[i] - mean) / denom
            if val < -500.0:
                val = -500.0
            elif val > 500.0:
                val = 500.0
            cci[i] = val
        else:
            cci[i] = 0.0
    return cci
