def _osc_sigmoid(z: float) -> float:
    """Numerically stable logistic. Never raises, never returns NaN."""
    try:
        zv = float(z)
    except (TypeError, ValueError):
        return 0.5
    if not math.isfinite(zv):
        return 0.5 if math.isnan(zv) else (1.0 if zv > 0 else 0.0)
    if zv >= 0.0:
        ez = math.exp(-zv)
        return 1.0 / (1.0 + ez)
    ez = math.exp(zv)
    return ez / (1.0 + ez)


def _osc_finite(value: Any, default: float = 0.0) -> float:
    """float() with NaN/Inf/None/str protection."""
    try:
        if value is None:
            return float(default)
        v = float(value)
    except (TypeError, ValueError):
        return float(default)
    if not math.isfinite(v):
        return float(default)
    return v


