#=====================================
#Strategies: 📍 Pivot Points


# ── SECTION A: Module-level constants ─────────────────────────────────────────
_PVT_HARD_FLOOR: float = 0.80
_PVT_CONF_CEILING: float = 0.95
_PVT_STRONG_CONF: float = 0.88
_PVT_MAX_JUMP: float = 0.08
_PVT_EPS: float = 1e-12


# ── SECTION B: Numeric helpers ────────────────────────────────────────────────
def _pvt_f(value: Any, default: float = 0.0) -> float:
    """float() مقاوم: None/str/NaN/Inf → default. هرگز استثنا نمی‌دهد."""
    try:
        if value is None:
            return float(default)
        if isinstance(value, bool):
            return float(default)
        out = float(value)
    except (TypeError, ValueError, OverflowError):
        return float(default)
    if not math.isfinite(out):
        return float(default)
    return out


def _pvt_clamp(value: Any, low: float, high: float) -> float:
    """کلمپ امن؛ اگر high < low باشد swap می‌کند."""
    lo = _pvt_f(low, 0.0)
    hi = _pvt_f(high, lo)
    if hi < lo:
        lo, hi = hi, lo
    v = _pvt_f(value, lo)
    return float(min(hi, max(lo, v)))


def _pvt_finite_or(value: Any, default: Optional[float]) -> Optional[float]:
    """در صورت عدم‌تناهی → default."""
    try:
        if value is None:
            return default
        v = float(value)
        if not np.isfinite(v):
            return default
        return v
    except (TypeError, ValueError, OverflowError):
        return default


def _pvt_direction(token: Any) -> str:
    """BUY/SELL/HOLD از هر توکن سیگنال (شامل STRONG_/WEAK_)."""
    text = str(token or "HOLD").upper().strip()
    if "BUY" in text or text in ("LONG", "BULL", "BULLISH"):
        return "BUY"
    if "SELL" in text or text in ("SHORT", "BEAR", "BEARISH"):
        return "SELL"
    return "HOLD"


def _pvt_env_float(name: str, default: float) -> float:
    """خواندن env عددی؛ مقدار > 1 به‌عنوان درصد تعبیر می‌شود (80 → 0.80)."""
    import os
    base = _pvt_f(default, 0.0)
    try:
        raw = os.getenv(str(name))
        if raw is None or not str(raw).strip():
            return base
        value = float(str(raw).strip())
        if not math.isfinite(value):
            return base
        if value > 1.0:
            value /= 100.0
        return float(value)
    except (TypeError, ValueError, OverflowError):
        return base


def _pvt_threshold_bundle() -> Dict[str, float]:
    """باندل آستانه‌ها با تضمین‌های ریاضی (کف ۰.۸۰ غیرقابل کاهش)."""
    import os
    env_threshold = _pvt_clamp(_pvt_env_float("CONFIDENCE_THRESHOLD", 0.80), 0.50, 0.92)
    for key in (
        "CENTRAL_CONFIDENCE_THRESHOLD",
        "NDS_CONFIDENCE_THRESHOLD",
        "MIN_CONFIDENCE_THRESHOLD",
    ):
        raw = os.getenv(key)
        if raw is None or not str(raw).strip():
            continue
        candidate = _pvt_env_float(key, env_threshold)
        if candidate > 0.0:
            env_threshold = _pvt_clamp(candidate, 0.50, 0.92)
        break

    floor_override = _pvt_env_float("MIN_DELIVERABLE_CONFIDENCE", _PVT_HARD_FLOOR)
    quality_floor = _pvt_clamp(
        max(_PVT_HARD_FLOOR, floor_override, env_threshold),
        _PVT_HARD_FLOOR, 0.92,
    )
    strong = _pvt_clamp(
        max(_pvt_env_float("NDS_STRONG_CONFIDENCE", _PVT_STRONG_CONF), quality_floor + 0.06),
        quality_floor + 0.02, 0.96,
    )
    ceiling = _pvt_clamp(
        max(_pvt_env_float("NDS_CONFIDENCE_CEILING", _PVT_CONF_CEILING), strong + 0.02),
        strong + 0.01, 0.98,
    )
    return {
        "env_threshold": float(env_threshold),
        "quality_floor": float(quality_floor),
        "strong": float(strong),
        "ceiling": float(ceiling),
        "dynamic_bias": 0.0,
    }


def _pvt_floor(*, quality_floor: Optional[float] = None, extra: float = 0.0) -> float:
    """کف تحویل: هرگز زیر ۰.۸۰، هرگز بالای ۰.۹۵."""
    bundle_floor = _pvt_f(_pvt_threshold_bundle().get("quality_floor"), _PVT_HARD_FLOOR)
    floor = max(_PVT_HARD_FLOOR, bundle_floor, _pvt_f(quality_floor, _PVT_HARD_FLOOR))
    floor += max(0.0, _pvt_f(extra, 0.0))
    return _pvt_clamp(floor, _PVT_HARD_FLOOR, _PVT_CONF_CEILING)


# ── SECTION C: Hardware profile + min-bars resolution ─────────────────────────
_PVT_HW_CACHE: Optional[Dict[str, Any]] = None
_PVT_HW_LOCK = threading.Lock()

_PVT_TIER_DEFAULTS: Dict[str, Tuple[int, float]] = {
    "LOW": (640, 60.0),
    "MID": (1280, 60.0),
    "HIGH": (2560, 60.0),
}


def _pvt_hw_tier(cores: int, total_ram_mb: float) -> str:
    if cores <= 2 or (0.0 < total_ram_mb < 3072.0):
        return "LOW"
    if cores <= 8 or (0.0 < total_ram_mb < 16384.0):
        return "MID"
    return "HIGH"


def _pvt_hw_profile() -> Dict[str, Any]:
    """پروفایل سخت‌افزار با کش thread-safe."""
    global _PVT_HW_CACHE
    if _PVT_HW_CACHE is not None:
        return _PVT_HW_CACHE
    with _PVT_HW_LOCK:
        if _PVT_HW_CACHE is not None:
            return _PVT_HW_CACHE
        import os
        try:
            sched = getattr(os, "sched_getaffinity", None)
            cores = len(sched(0)) if sched is not None else (os.cpu_count() or 1)
        except Exception:
            cores = os.cpu_count() or 1
        cores = max(1, int(cores))

        total_ram_mb = 0.0
        try:
            page_size = os.sysconf("SC_PAGE_SIZE")
            page_count = os.sysconf("SC_PHYS_PAGES")
            total_ram_mb = float(page_size) * float(page_count) / (1024.0 * 1024.0)
        except (ValueError, OSError, AttributeError):
            total_ram_mb = 0.0

        tier = _pvt_hw_tier(cores, total_ram_mb)
        env_tier = (os.getenv("PAE_TIER") or "").strip().upper()
        if env_tier in _PVT_TIER_DEFAULTS:
            tier = env_tier

        max_window, budget = _PVT_TIER_DEFAULTS[tier]

        raw_window = os.getenv("PAE_MAX_WINDOW")
        if raw_window:
            try:
                max_window = max(120, int(float(raw_window)))
            except (TypeError, ValueError):
                pass
        raw_budget = os.getenv("PAE_TIME_BUDGET_S")
        if raw_budget:
            try:
                budget = max(0.5, min(60.0, float(raw_budget)))
            except (TypeError, ValueError):
                pass

        _PVT_HW_CACHE = {
            "cores": cores,
            "total_ram_mb": round(total_ram_mb, 1),
            "tier": tier,
            "max_window": int(max_window),
            "time_budget_s": float(budget),
        }
        return _PVT_HW_CACHE


def pvt_hardware_profile() -> Dict[str, Any]:
    return dict(_pvt_hw_profile())


_PVT_MIN_BARS: int = 500


def _pvt_min_bars_for(strategy_name: str, strategy_specific_default: int = 0) -> int:
    """MIN_BARS_REQUIRED_<STRATEGY> → MIN_BARS_REQUIRED → default کلاس → کف ۲۰."""
    import os
    try:
        safe_name = "".join(
            ch for ch in str(strategy_name).upper() if ch.isalnum() or ch == "_"
        )
        specific = os.getenv(f"MIN_BARS_REQUIRED_{safe_name}")
        if specific is not None:
            try:
                return max(20, int(float(specific)))
            except (TypeError, ValueError):
                pass
        global_val = os.getenv("MIN_BARS_REQUIRED")
        if global_val is not None:
            try:
                val = int(float(global_val))
                if val > 0:
                    return max(20, val)
            except (TypeError, ValueError):
                pass
        if strategy_specific_default > 0:
            return max(20, int(strategy_specific_default))
        return _PVT_MIN_BARS
    except Exception:
        return _PVT_MIN_BARS


# ── SECTION D: Numba kernels (reuses existing njit/prange) ────────────────────
# Integration: njit/prange/PVT_NUMBA_AVAILABLE already available from your file's
# numba import block. We only need to ensure they exist as a safety net.

if "njit" not in globals() or "prange" not in globals():
    try:
        from numba import njit, prange
        PVT_NUMBA_AVAILABLE = True
    except ImportError:
        PVT_NUMBA_AVAILABLE = False

        def njit(*args, **kwargs):
            def _decorator(func):
                return func
            if len(args) == 1 and callable(args[0]) and not kwargs:
                return args[0]
            return _decorator

        def prange(*args):
            return range(*args)
else:
    PVT_NUMBA_AVAILABLE = bool(globals().get("NUMBA_AVAILABLE", False))


@njit(cache=True)
def _pvt_fillna(arr: np.ndarray) -> np.ndarray:
    """forward-fill سپس back-fill مقادیر غیرمتناهی، O(n)."""
    n = arr.shape[0]
    out = np.empty(n, dtype=np.float64)
    if n == 0:
        return out
    last = 0.0
    seen = False
    first_idx = -1
    first_val = 0.0
    for i in range(n):
        v = arr[i]
        if (v == v) and (-1e308 < v < 1e308):
            out[i] = v
            last = v
            if not seen:
                seen = True
                first_idx = i
                first_val = v
        else:
            out[i] = last if seen else 0.0
    if seen and first_idx > 0:
        for i in range(first_idx):
            out[i] = first_val
    return out


@njit(cache=True)
def _pvt_ema(arr: np.ndarray, span: int) -> np.ndarray:
    n = arr.shape[0]
    out = np.zeros(n, dtype=np.float64)
    if n == 0:
        return out
    span = max(2, span)
    alpha = 2.0 / (span + 1.0)
    seed = 0.0
    start = 0
    for i in range(n):
        v = arr[i]
        if (v == v) and (-1e308 < v < 1e308):
            seed = v
            start = i
            break
    out[start] = seed
    for i in range(start + 1, n):
        val = arr[i]
        if (val != val) or not (-1e308 < val < 1e308):
            out[i] = out[i - 1]
        else:
            out[i] = alpha * val + (1.0 - alpha) * out[i - 1]
    for i in range(start):
        out[i] = seed
    return out


@njit(cache=True)
def _pvt_rma(arr: np.ndarray, period: int) -> np.ndarray:
    n = arr.shape[0]
    out = np.zeros(n, dtype=np.float64)
    if n == 0:
        return out
    alpha = 1.0 / max(2, period)
    seed = 0.0
    start = 0
    for i in range(n):
        v = arr[i]
        if (v == v) and (-1e308 < v < 1e308):
            seed = v
            start = i
            break
    out[start] = seed
    for i in range(start + 1, n):
        val = arr[i]
        if (val != val) or not (-1e308 < val < 1e308):
            out[i] = out[i - 1]
        else:
            out[i] = alpha * val + (1.0 - alpha) * out[i - 1]
    for i in range(start):
        out[i] = seed
    return out


@njit(cache=True)
def _pvt_sma(arr: np.ndarray, period: int) -> np.ndarray:
    n = arr.shape[0]
    out = np.zeros(n, dtype=np.float64)
    if n == 0:
        return out
    period = max(1, period)
    csum = 0.0
    for i in range(n):
        v = arr[i]
        if (v != v) or not (-1e308 < v < 1e308):
            v = 0.0
        csum += v
        if i >= period:
            old = arr[i - period]
            if (old != old) or not (-1e308 < old < 1e308):
                old = 0.0
            csum -= old
            out[i] = csum / period
        else:
            out[i] = csum / (i + 1)
    return out


@njit(cache=True, fastmath=True)
def _pvt_atr(high: np.ndarray, low: np.ndarray, close: np.ndarray,
             period: int) -> np.ndarray:
    """Wilder ATR — alpha=1/period."""
    n = close.shape[0]
    if n == 0:
        return np.empty(0, dtype=np.float64)
    period = max(2, period)
    tr = np.empty(n, dtype=np.float64)
    tr[0] = high[0] - low[0]
    for i in range(1, n):
        prev_c = close[i - 1]
        tr1 = high[i] - low[i]
        tr2 = abs(high[i] - prev_c)
        tr3 = abs(low[i] - prev_c)
        tr[i] = max(tr1, max(tr2, tr3))
    alpha = 1.0 / period
    atr = np.empty(n, dtype=np.float64)
    atr[0] = tr[0]
    for i in range(1, n):
        atr[i] = alpha * tr[i] + (1.0 - alpha) * atr[i - 1]
    return atr


@njit(cache=True, fastmath=True)
def _pvt_rsi(prices: np.ndarray, period: int) -> np.ndarray:
    """Wilder RSI — canonical scalar implementation."""
    n = prices.shape[0]
    if n == 0:
        return np.empty(0, dtype=np.float64)
    if n < 3:
        return np.full(n, 50.0, dtype=np.float64)
    period = max(2, period)
    delta = np.empty(n, dtype=np.float64)
    delta[0] = 0.0
    for i in range(1, n):
        delta[i] = prices[i] - prices[i - 1]
    rsi = np.full(n, 50.0, dtype=np.float64)
    if n < period + 1:
        return rsi
    sum_g = 0.0
    sum_l = 0.0
    for i in range(period):
        d = delta[i]
        if d > 0.0:
            sum_g += d
        else:
            sum_l -= d
    avg_g = sum_g / period
    avg_l = sum_l / period
    if avg_l < 1e-12:
        rsi[period - 1] = 100.0 if avg_g > 1e-12 else 50.0
    else:
        rsi[period - 1] = 100.0 - (100.0 / (1.0 + avg_g / avg_l))
    alpha = 1.0 / period
    for i in range(period, n):
        d = delta[i]
        g = d if d > 0.0 else 0.0
        l = -d if d < 0.0 else 0.0
        avg_g = (1.0 - alpha) * avg_g + alpha * g
        avg_l = (1.0 - alpha) * avg_l + alpha * l
        if avg_l < 1e-12:
            rsi[i] = 100.0 if avg_g > 1e-12 else 50.0
        else:
            rsi[i] = 100.0 - (100.0 / (1.0 + avg_g / avg_l))
    return rsi


_pvt_rsi_alias = _pvt_rsi


@njit(cache=True, fastmath=True)
def _pvt_adx_di(high: np.ndarray, low: np.ndarray, close: np.ndarray,
                period: int) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
    """(ADX, +DI, -DI) با هموارسازی Wilder."""
    n = close.shape[0]
    if n == 0:
        z = np.empty(0, dtype=np.float64)
        return z, z, z
    tr = np.empty(n, dtype=np.float64)
    plus_dm = np.empty(n, dtype=np.float64)
    minus_dm = np.empty(n, dtype=np.float64)
    tr[0] = high[0] - low[0]
    plus_dm[0] = 0.0
    minus_dm[0] = 0.0
    for i in range(1, n):
        prev_c = close[i - 1]
        tr1 = high[i] - low[i]
        tr2 = abs(high[i] - prev_c)
        tr3 = abs(low[i] - prev_c)
        tr[i] = max(tr1, max(tr2, tr3))
        up_move = high[i] - high[i - 1]
        dn_move = low[i - 1] - low[i]
        plus_dm[i] = up_move if (up_move > dn_move and up_move > 0.0) else 0.0
        minus_dm[i] = dn_move if (dn_move > up_move and dn_move > 0.0) else 0.0

    period = max(2, period)
    alpha = 1.0 / period
    smooth_tr = np.empty(n, dtype=np.float64)
    smooth_pdm = np.empty(n, dtype=np.float64)
    smooth_mdm = np.empty(n, dtype=np.float64)
    smooth_tr[0] = tr[0]
    smooth_pdm[0] = plus_dm[0]
    smooth_mdm[0] = minus_dm[0]
    for i in range(1, n):
        smooth_tr[i] = alpha * tr[i] + (1.0 - alpha) * smooth_tr[i - 1]
        smooth_pdm[i] = alpha * plus_dm[i] + (1.0 - alpha) * smooth_pdm[i - 1]
        smooth_mdm[i] = alpha * minus_dm[i] + (1.0 - alpha) * smooth_mdm[i - 1]

    pdi = np.zeros(n, dtype=np.float64)
    mdi = np.zeros(n, dtype=np.float64)
    dx = np.zeros(n, dtype=np.float64)
    for i in range(n):
        atr_val = smooth_tr[i]
        if atr_val > 1e-12:
            pdi[i] = 100.0 * smooth_pdm[i] / atr_val
            mdi[i] = 100.0 * smooth_mdm[i] / atr_val
        denom = pdi[i] + mdi[i]
        dx[i] = 100.0 * abs(pdi[i] - mdi[i]) / denom if denom > 1e-12 else 0.0
    adx = np.zeros(n, dtype=np.float64)
    adx[0] = dx[0]
    for i in range(1, n):
        adx[i] = alpha * dx[i] + (1.0 - alpha) * adx[i - 1]
    return adx, pdi, mdi


# ── SECTION E: Enums and dataclasses ──────────────────────────────────────────
class PvtMarketRegime(Enum):
    STRONG_TREND = "STRONG_TREND"
    TRENDING = "TRENDING"
    WEAK_TREND_OR_TRANSITION = "WEAK_TREND_OR_TRANSITION"
    RANGING = "RANGING"
    UNKNOWN = "UNKNOWN"


@dataclass
class PvtMarketState:
    regime: PvtMarketRegime
    trend_strength: float
    volatility: float
    adx: float
    trend_direction: float
    momentum: float


class PvtSetupKind(Enum):
    BREAKOUT = "BREAKOUT"
    REJECTION = "REJECTION"
    BOUNCE = "BOUNCE"
    SWEEP = "SWEEP"


@dataclass(frozen=True)
class PvtZone:
    """ناحیهٔ قیمتی واقعی (نه یک خط تک)."""
    name: str
    low: float
    high: float
    reference: float
    touches: int = 0
    strength: float = 0.0
    age_bars: int = 0
    timeframe: str = "BASE"

    @property
    def width(self) -> float:
        return max(0.0, float(self.high) - float(self.low))

    def contains(self, price: float, tolerance: float = 0.0) -> bool:
        p = _pvt_f(price, 0.0)
        tol = max(0.0, _pvt_f(tolerance, 0.0))
        return (float(self.low) - tol) <= p <= (float(self.high) + tol)

    def distance(self, price: float) -> float:
        p = _pvt_f(price, 0.0)
        if p < float(self.low):
            return float(self.low) - p
        if p > float(self.high):
            return p - float(self.high)
        return 0.0


