# ── SECTION F: OHLCV sanitizer ────────────────────────────────────────────────
def pvt_sanitize_ohlcv(
    df: Any,
    *,
    min_bars: int = 60,
    max_nan_ratio: float = 0.30,
    min_price_variance: float = 1e-12,
) -> Tuple[Optional[Dict[str, Any]], str]:
    """
    آماده‌سازی امن OHLCV.
    خروجی: (arrays | None, reason)
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return None, "empty or non-DataFrame input"

    required = ("open", "high", "low", "close")
    missing = [c for c in required if c not in df.columns]
    if missing:
        return None, f"missing required columns: {missing}"

    columns = list(df.columns)
    for col in required:
        if columns.count(col) > 1:
            return None, f"duplicated column: {col}"

    n = int(len(df))
    needed = max(20, int(min_bars))
    if n < needed:
        return None, f"insufficient bars: {n} < {needed}"

    raw: Dict[str, np.ndarray] = {}
    for col in required:
        try:
            arr = np.ascontiguousarray(df[col].to_numpy(dtype=np.float64), dtype=np.float64)
        except (TypeError, ValueError, OverflowError) as exc:
            return None, f"non-numeric column {col}: {exc}"
        if arr.ndim != 1 or arr.shape[0] != n:
            return None, f"invalid shape for {col}: {arr.shape}"
        raw[col] = arr

    stacked = np.vstack([raw[c] for c in required])
    nan_ratio = float(1.0 - np.isfinite(stacked).mean())
    if nan_ratio > float(max_nan_ratio):
        return None, f"too many NaN/Inf: {nan_ratio:.1%} > {float(max_nan_ratio):.1%}"
    quality = float(min(1.0, max(0.0, 1.0 - nan_ratio)))

    if "volume" in df.columns and columns.count("volume") == 1:
        try:
            vol = np.ascontiguousarray(df["volume"].to_numpy(dtype=np.float64), dtype=np.float64)
            if vol.ndim != 1 or vol.shape[0] != n:
                vol = np.ones(n, dtype=np.float64)
        except (TypeError, ValueError, OverflowError):
            vol = np.ones(n, dtype=np.float64)
    else:
        vol = np.ones(n, dtype=np.float64)

    def _repair(arr: np.ndarray) -> Optional[np.ndarray]:
        try:
            out = np.ascontiguousarray(_pvt_fillna(arr), dtype=np.float64)
        except Exception:
            out = pd.Series(arr).replace([np.inf, -np.inf], np.nan).ffill().bfill()
            out = np.ascontiguousarray(out.to_numpy(dtype=np.float64), dtype=np.float64)
        if out.ndim != 1 or out.shape[0] != n or not np.isfinite(out).all():
            return None
        return out

    clean: Dict[str, np.ndarray] = {}
    for col in required:
        fixed = _repair(raw[col])
        if fixed is None:
            return None, f"unrecoverable non-finite values in {col}"
        clean[col] = fixed

    o = clean["open"]
    h = clean["high"]
    l = clean["low"]
    c = clean["close"]
    if not (np.all(o > 0.0) and np.all(h > 0.0) and np.all(l > 0.0) and np.all(c > 0.0)):
        return None, "non-positive prices"

    bad_hl = int(np.count_nonzero(h < np.maximum(o, c)) + np.count_nonzero(l > np.minimum(o, c)))
    h = np.maximum(h, np.maximum(o, c))
    l = np.minimum(l, np.minimum(o, c))
    l = np.minimum(l, h)
    if bad_hl:
        quality *= float(max(0.50, 1.0 - bad_hl / max(1, n)))

    if float(np.var(c)) <= float(min_price_variance):
        return None, "degenerate price series (zero variance)"

    return {
        "open": np.ascontiguousarray(o, dtype=np.float64),
        "high": np.ascontiguousarray(h, dtype=np.float64),
        "low": np.ascontiguousarray(l, dtype=np.float64),
        "close": np.ascontiguousarray(c, dtype=np.float64),
        "volume": np.ascontiguousarray(
            np.where(np.isfinite(vol), np.maximum(vol, 0.0), 0.0), dtype=np.float64
        ),
        "size": n,
        "quality": float(min(1.0, max(0.0, quality))),
    }, ""


# ── SECTION G: Performance snapshot + adaptive multiplier ─────────────────────
@dataclass
class PvtPerformanceSnapshot:
    window_size: int
    win_rate: float
    avg_confidence_on_wins: float = 0.0
    avg_confidence_on_losses: float = 0.0
    consecutive_losses: int = 0
    sharpe_proxy: float = 0.0
    last_updated: str = field(
        default_factory=lambda: datetime.now(timezone.utc).isoformat()
    )

    def to_dict(self) -> Dict[str, Any]:
        return {
            "window_size": int(self.window_size),
            "win_rate": float(self.win_rate),
            "avg_confidence_on_wins": float(self.avg_confidence_on_wins),
            "avg_confidence_on_losses": float(self.avg_confidence_on_losses),
            "consecutive_losses": int(self.consecutive_losses),
            "sharpe_proxy": float(self.sharpe_proxy),
            "last_updated": str(self.last_updated),
        }

    @classmethod
    def from_dict(cls, data: Dict[str, Any]) -> "PvtPerformanceSnapshot":
        d = data if isinstance(data, dict) else {}
        return cls(
            window_size=int(_pvt_f(d.get("window_size"), 0.0)),
            win_rate=_pvt_clamp(d.get("win_rate"), 0.0, 1.0) if d.get("win_rate") is not None else 0.5,
            avg_confidence_on_wins=_pvt_clamp(d.get("avg_confidence_on_wins"), 0.0, 1.0),
            avg_confidence_on_losses=_pvt_clamp(d.get("avg_confidence_on_losses"), 0.0, 1.0),
            consecutive_losses=max(0, int(_pvt_f(d.get("consecutive_losses"), 0.0))),
            sharpe_proxy=_pvt_f(d.get("sharpe_proxy"), 0.0),
            last_updated=str(d.get("last_updated") or datetime.now(timezone.utc).isoformat()),
        )


def pvt_adaptive_multiplier(
    current_multiplier: float,
    snapshot: Optional[PvtPerformanceSnapshot],
    min_samples: int = 200,
    smoothing_alpha: float = 0.15,
    baseline_win_rate: float = 0.50,
    sensitivity: float = 0.6,
    circuit_breaker_losses: int = 5,
    multiplier_min: float = 0.75,
    multiplier_max: float = 1.25,
    logger: Optional[Any] = None,
    strategy_name: str = "UNKNOWN",
) -> float:
    """ضریب عملکرد تطبیقی با سقف/کف سخت (هرگز بالاتر از 1.0 برای تقویت اعتماد)."""
    current = _pvt_clamp(current_multiplier, multiplier_min, multiplier_max)
    lo = _pvt_f(multiplier_min, 0.75)
    hi = max(lo, _pvt_f(multiplier_max, 1.25))
    alpha = _pvt_clamp(smoothing_alpha, 0.01, 1.0)
    try:
        if snapshot is None:
            return float(min(hi, max(lo, 0.5 * current + 0.5)))
        if int(_pvt_f(snapshot.window_size, 0.0)) < max(1, int(min_samples)):
            return float(min(hi, max(lo, 0.7 * current + 0.3)))
        if int(_pvt_f(snapshot.consecutive_losses, 0.0)) >= max(1, int(circuit_breaker_losses)):
            return float(min(hi, max(lo, 0.5 * current + 0.5)))
        win_rate = _pvt_clamp(snapshot.win_rate, 0.0, 1.0)
        diff = (win_rate - _pvt_f(baseline_win_rate, 0.5)) * 2.0
        target = 1.0 + _pvt_f(sensitivity, 0.6) * diff
        target = float(min(hi, max(lo, target)))
        new_multiplier = (1.0 - alpha) * current + alpha * target
        return float(min(hi, max(lo, new_multiplier)))
    except Exception as exc:
        if logger is not None:
            logger.error("[%s_ADAPTIVE] %s", strategy_name, exc, exc_info=True)
        return float(min(hi, max(lo, current)))


# ── SECTION H: Reliability / calibration ──────────────────────────────────────
def _pvt_wilson(wins: float, total: float, z: float = 1.96) -> float:
    """کران پایین ۹۵٪ Wilson برای نرخ برد."""
    n = max(0.0, _pvt_f(total, 0.0))
    w = min(n, max(0.0, _pvt_f(wins, 0.0)))
    if n <= 0.0:
        return 0.0
    zz = _pvt_clamp(z, 0.0, 4.0)
    p = w / n
    z2 = zz * zz
    denom = 1.0 + z2 / n
    centre = (p + z2 / (2.0 * n)) / denom
    margin = (zz / denom) * math.sqrt(max(0.0, p * (1.0 - p) / n + z2 / (4.0 * n * n)))
    return float(min(1.0, max(0.0, centre - margin)))


def pvt_reliability_factor(
    records: Any,
    target_confidence: float = 0.80,
    min_samples: int = 30,
    z: float = 1.96,
) -> Tuple[float, Dict[str, Any]]:
    """ضریب کالیبراسیون تجربی (کران پایین Wilson / هدف)."""
    target = _pvt_clamp(target_confidence, 0.50, 0.98)
    min_n = max(1, int(min_samples))
    wins = 0.0
    total = 0.0
    skipped = 0

    if isinstance(records, dict) and "samples" in records:
        total = max(0.0, _pvt_f(records.get("samples"), 0.0))
        wins = min(total, max(0.0, _pvt_f(records.get("wins"), 0.0)))
    else:
        try:
            iterator = list(records) if records is not None else []
        except (TypeError, ValueError):
            iterator = []
        for rec in iterator[-2000:]:
            if not isinstance(rec, dict):
                skipped += 1
                continue
            conf = rec.get("confidence", None)
            if conf is not None:
                conf_val = _pvt_f(conf, -1.0)
                if 0.0 <= conf_val < target - 0.02:
                    skipped += 1
                    continue
            won: Optional[bool] = None
            for key in ("won", "was_correct_direction", "was_correct", "win", "is_win", "correct"):
                if key in rec:
                    won = bool(rec[key])
                    break
            if won is None:
                won = _pvt_f(rec.get("pnl"), 0.0) > 0.0
            total += 1.0
            if won:
                wins += 1.0

    w = wins + 4.0
    n = total + 8.0
    lower = _pvt_wilson(w, n, z=z)
    factor = float(min(1.0, max(0.0, lower / max(target, _PVT_EPS))))
    info: Dict[str, Any] = {
        "wins": int(wins),
        "samples": int(total),
        "skipped": int(skipped),
        "win_rate": float(w / n),
        "wilson_lower": float(lower),
        "target": float(target),
        "min_samples": int(min_n),
        "cold_start": bool(total < min_n),
        "factor": float(factor),
    }
    return factor, info


def pvt_calibrate_confidence(
    records: Any,
    stats: Dict[str, Any],
    raw_confidence: float,
    floor: float = 0.80,
    min_samples: int = 30,
    circuit_breaker_losses: int = 5,
    z: float = 1.96,
    reliability_enabled: bool = True,
    circuit_breaker_enabled: bool = True,
) -> Tuple[float, Dict[str, Any]]:
    """کالیبراسیون اعتماد بر پایهٔ نرخ برد واقعی (کاهشی-محور)."""
    floor_local = _pvt_clamp(floor, _PVT_HARD_FLOOR, 0.98)
    raw = _pvt_clamp(raw_confidence, 0.0, 0.98)
    st = stats if isinstance(stats, dict) else {}

    if not reliability_enabled:
        return raw, {"status": "disabled", "proven": None, "wins": 0, "samples": 0,
                     "reason": "reliability calibration disabled"}

    if circuit_breaker_enabled:
        consecutive = int(_pvt_f(st.get("consecutive_losses"), 0.0))
        if consecutive >= max(1, int(circuit_breaker_losses)):
            return 0.0, {
                "status": "circuit_breaker", "proven": None,
                "wins": int(_pvt_f(st.get("_wins"), 0.0)),
                "samples": int(_pvt_f(st.get("_closed"), 0.0)),
                "consecutive_losses": consecutive,
                "reason": (
                    f"circuit breaker: {consecutive} consecutive losses; "
                    f"trading paused until a winning trade resets the counter"
                ),
            }

    try:
        source = list(records) if records is not None else []
    except (TypeError, ValueError):
        source = []

    recent_wins = 0
    recent_total = 0
    for rec in source[-2000:]:
        if not isinstance(rec, dict):
            continue
        if "was_correct" in rec:
            ok = bool(rec["was_correct"])
        elif any(k in rec for k in ("won", "was_correct_direction", "win", "is_win", "correct")):
            ok = bool(rec.get("won", rec.get("was_correct_direction",
                        rec.get("win", rec.get("is_win", rec.get("correct"))))))
        else:
            ok = _pvt_f(rec.get("pnl"), 0.0) > 0.0
        recent_total += 1
        if ok:
            recent_wins += 1

    min_n = max(1, int(min_samples))
    wins, total, scope = recent_wins, recent_total, "recent_window"
    if total < min_n:
        all_wins = int(_pvt_f(st.get("_wins"), 0.0))
        all_total = int(_pvt_f(st.get("_closed"), 0.0))
        if all_total >= min_n:
            wins, total, scope = all_wins, all_total, "all_time"
        else:
            capped = float(min(raw, floor_local - 0.01))
            return capped, {
                "status": "cold_start", "proven": None,
                "wins": int(recent_wins + all_wins),
                "samples": int(recent_total + all_total),
                "min_samples": min_n,
                "reason": (
                    f"cold start: {int(recent_total + all_total)}/{min_n} closed outcomes; "
                    f"confidence capped below the gate until the track record is proven"
                ),
            }

    factor, info = pvt_reliability_factor(
        {"wins": int(wins), "samples": int(total)},
        target_confidence=floor_local, min_samples=min_n, z=z,
    )
    proven = _pvt_f(info.get("wilson_lower"), 0.0)
    if proven + _PVT_EPS < floor_local:
        return 0.0, {
            "status": "unproven", "proven": proven,
            "wins": int(wins), "samples": int(total), "scope": scope,
            "reason": (
                f"proven accuracy {proven:.1%} (Wilson 95% lower, {int(total)} samples, "
                f"{scope}) is below the {floor_local:.0%} gate"
            ),
        }
    calibrated = float(min(raw, proven + 0.05, 0.98))
    return calibrated, {
        "status": "calibrated", "proven": proven,
        "wins": int(wins), "samples": int(total), "scope": scope,
        "wilson_lower": proven, "factor": _pvt_f(info.get("factor"), 0.0),
        "reason": f"calibrated to proven accuracy {proven:.1%} ({int(total)} samples, {scope})",
    }


# ── SECTION I: Evidence → confidence mapping ──────────────────────────────────
def pvt_roc_auc(y_true: Any, y_score: Any) -> float:
    """AUC با روش Mann–Whitney (بدون sklearn، O(n log n)، مقاوم به tie)."""
    y = np.asarray(y_true, dtype=np.float64).ravel()
    s = np.asarray(y_score, dtype=np.float64).ravel()
    if y.size != s.size or y.size < 2:
        return 0.5
    mask = np.isfinite(y) & np.isfinite(s)
    y, s = y[mask], s[mask]
    n_pos = int(np.count_nonzero(y > 0.5))
    n_neg = int(y.size - n_pos)
    if n_pos == 0 or n_neg == 0:
        return 0.5
    order = np.argsort(s, kind="mergesort")
    s_sorted = s[order]
    ranks = np.empty(s.size, dtype=np.float64)
    i = 0
    while i < s.size:
        j = i
        while j + 1 < s.size and s_sorted[j + 1] == s_sorted[i]:
            j += 1
        avg_rank = 0.5 * (i + j) + 1.0
        ranks[order[i:j + 1]] = avg_rank
        i = j + 1
    sum_pos_ranks = float(ranks[y > 0.5].sum())
    auc = (sum_pos_ranks - n_pos * (n_pos + 1) / 2.0) / (n_pos * n_neg)
    return float(min(1.0, max(0.0, auc)))


def _pvt_fit_logistic(evidence: Any, labels: Any) -> Tuple[Optional[float], Optional[float], Dict[str, Any]]:
    """رگرسیون لجستیک یک‌بعدی با Newton-Raphson + ridge."""
    info: Dict[str, Any] = {"status": "cold_start", "samples": 0, "positives": 0, "auc": 0.5}
    try:
        e = np.asarray(evidence, dtype=np.float64).ravel()
        y = np.asarray(labels, dtype=np.float64).ravel()
        if e.size != y.size or e.size < 80:
            info["reason"] = "fewer than 80 closed trades"
            return None, None, info
        mask = np.isfinite(e) & np.isfinite(y)
        e, y = e[mask], y[mask]
        n_pos = int(np.count_nonzero(y > 0.5))
        n_neg = int(y.size - n_pos)
        info.update({"samples": int(y.size), "positives": n_pos})
        if n_pos < 30 or n_neg < 30:
            info["reason"] = "need at least 30 wins and 30 losses to calibrate"
            return None, None, info
        mu = float(np.mean(e))
        sd = float(np.std(e))
        if sd <= 1e-9:
            info["reason"] = "degenerate evidence (zero variance)"
            return None, None, info
        x = (e - mu) / sd
        auc = pvt_roc_auc(y, x)
        info["auc"] = float(auc)
        if auc < 0.53:
            info["status"] = "uninformative"
            info["reason"] = f"AUC {auc:.3f} < 0.53: evidence has no predictive value"
            return None, None, info

        ridge = 1.0
        slope_cap = 8.0
        a = 0.0
        b = 0.0
        for _ in range(60):
            z = a + b * x
            z = np.clip(z, -30.0, 30.0)
            p = 1.0 / (1.0 + np.exp(-z))
            w = np.maximum(p * (1.0 - p), 1e-8)
            grad_a = float(np.sum(y - p)) - 1e-9 * a
            grad_b = float(np.sum((y - p) * x)) - ridge * b
            h_aa = float(np.sum(w)) + 1e-9
            h_ab = float(np.sum(w * x))
            h_bb = float(np.sum(w * x * x)) + ridge
            det = h_aa * h_bb - h_ab * h_ab
            if abs(det) < 1e-12:
                break
            da = (h_bb * grad_a - h_ab * grad_b) / det
            db = (-h_ab * grad_a + h_aa * grad_b) / det
            a += float(np.clip(da, -2.0, 2.0))
            b = float(np.clip(b + np.clip(db, -2.0, 2.0), 0.0, slope_cap))
            if abs(da) < 1e-8 and abs(db) < 1e-8:
                break
        if b <= 0.0:
            info["status"] = "uninformative"
            info["reason"] = f"non-positive slope (b={b:.4f})"
            return None, None, info
        try:
            z_final = np.clip(a + b * x, -30.0, 30.0)
            p_final = 1.0 / (1.0 + np.exp(-z_final))
            brier = float(np.mean((p_final - y) ** 2))
            base_rate = float(np.clip(np.mean(y), 1e-6, 1 - 1e-6))
            brier_baseline = float(np.mean((base_rate - y) ** 2))
        except Exception:
            brier, brier_baseline = 0.25, 0.25
        if brier > brier_baseline:
            info["status"] = "uninformative"
            info["reason"] = (f"Brier {brier:.4f} worse than base-rate baseline "
                              f"{brier_baseline:.4f}")
            return None, None, info
        info.update({
            "status": "calibrated",
            "brier": float(brier),
            "brier_baseline": float(brier_baseline),
            "ridge": float(ridge),
            "slope_cap": float(slope_cap),
            "intercept": float(a),
            "slope": float(b),
            "evidence_mean": mu,
            "evidence_std": sd,
            "reason": f"logistic fit on {int(y.size)} trades (AUC {auc:.3f})",
        })
        return float(a), float(b), info
    except Exception as exc:
        info["reason"] = f"fit failed: {type(exc).__name__}: {exc}"
        return None, None, info


def pvt_confidence_from_evidence(
    evidence_score: float,
    *,
    model_intercept: Optional[float] = None,
    model_slope: Optional[float] = None,
    evidence_mean: float = 0.0,
    evidence_std: float = 1.0,
    probability_floor: float = _PVT_HARD_FLOOR,
    ceiling: float = _PVT_CONF_CEILING,
    prior_rate: float = 0.50,
) -> Tuple[float, str]:
    """شواهد → اعتماد قابل‌تحویل. mode ∈ {"calibrated", "prior"}."""
    score = _pvt_f(evidence_score, 0.0)
    floor = _pvt_clamp(probability_floor, _PVT_HARD_FLOOR, 0.98)
    cap = _pvt_clamp(ceiling, floor, 0.99)
    if model_intercept is not None and model_slope is not None:
        sd = max(1e-9, _pvt_f(evidence_std, 1.0))
        z = (score - _pvt_f(evidence_mean, 0.0)) / sd
        logit = _pvt_f(model_intercept, 0.0) + _pvt_f(model_slope, 0.0) * z
        logit = float(np.clip(logit, -30.0, 30.0))
        prob = 1.0 / (1.0 + math.exp(-logit))
        return float(min(cap, max(0.0, prob))), "calibrated"
    prior = min(cap, max(0.0, min(_pvt_f(prior_rate, 0.50), floor - 0.10)))
    return float(prior), "prior"


# ── SECTION J: HOLD quality + level cache ─────────────────────────────────────
def _pvt_hold_quality(
    reason: str,
    is_fallback: bool = False,
    error_type: str = "None",
) -> float:
    """کیفیت «درست بودن تصمیم به عدم‌معامله» — همیشه < 0.40 برای خطا."""
    try:
        r = str(reason or "").lower()
        et = str(error_type or "None").lower()
        if is_fallback or et not in ("none", "", "null", "noerror", "no_error", "no error"):
            if any(k in r for k in (
                "insufficient data", "insufficient history", "insufficient bars",
                "not enough data", "too few bars", "validation failed",
                "missing columns", "too much nan", "empty dataframe",
            )):
                return 0.38
            return 0.25
        if not r or r in ("n/a", "none", "unknown"):
            return 0.30
        if any(k in r for k in (
            "no clear", "no setup", "no qualified", "no high-quality", "no valid",
            "no dominant", "no aligned", "insufficient confluence", "below",
            "gate rejected", "insufficient agreement", "weak agreement",
            "conflict", "conflicting", "no strong signal", "no directional",
        )):
            return 0.34
        if any(k in r for k in (
            "ranging", "suppressed", "regime", "range bound", "sideways",
            "quiet", "low volatility", "dead", "compression", "cooldown",
        )):
            return 0.36
        if any(k in r for k in ("insufficient", "not enough", "too few",
                                "short history", "warm-up", "cold start")):
            return 0.32
        return 0.30
    except Exception:
        return 0.30


class _PvtLevelCache:
    """کش thread-safe با TTL برای سطوح پیوت نهایی‌شده (ضد رپیینت)."""
    __slots__ = ("_store", "_lock", "_ttl", "_max")

    def __init__(self, max_size: int = 256, ttl_seconds: float = 900.0) -> None:
        from collections import OrderedDict
        self._store: "OrderedDict[str, Tuple[float, Any]]" = OrderedDict()
        self._lock = threading.Lock()
        self._ttl = max(1.0, float(ttl_seconds))
        self._max = max(8, int(max_size))

    def get(self, key: str) -> Any:
        if not key:
            return None
        now = time.monotonic()
        with self._lock:
            item = self._store.get(key)
            if item is None:
                return None
            stamp, value = item
            if now - stamp > self._ttl:
                self._store.pop(key, None)
                return None
            self._store.move_to_end(key)
            return value

    def put(self, key: str, value: Any) -> None:
        if not key:
            return
        with self._lock:
            self._store[key] = (time.monotonic(), value)
            self._store.move_to_end(key)
            while len(self._store) > self._max:
                self._store.popitem(last=False)

    def clear(self) -> None:
        with self._lock:
            self._store.clear()


_PVT_LEVEL_CACHE = _PvtLevelCache(max_size=256, ttl_seconds=900.0)


# ── SECTION K: pvt_technical_analyzer (delegates to your existing TA) ────────
_PVT_TECH_ANALYZER: Optional[Any] = None
_PVT_TA_LOCK = threading.Lock()


def pvt_technical_analyzer() -> Any:
    """
    Return the shared TechnicalAnalyzer instance (uses your existing implementation).
    Falls back to creating a new instance if the shared getter is unavailable.
    """
    shared_getter = globals().get("get_shared_technical_analyzer")
    if callable(shared_getter):
        return shared_getter()

    global _PVT_TECH_ANALYZER
    if _PVT_TECH_ANALYZER is None:
        with _PVT_TA_LOCK:
            if _PVT_TECH_ANALYZER is None:
                analyzer_cls = globals().get("TechnicalAnalyzer")
                if analyzer_cls is None:
                    raise RuntimeError(
                        "pvt_technical_analyzer: neither get_shared_technical_analyzer() "
                        "nor TechnicalAnalyzer is available in this module."
                    )
                _PVT_TECH_ANALYZER = analyzer_cls()
    return _PVT_TECH_ANALYZER


# ── SECTION L: _PvtStrategyBase (inherits from your StrategyBaseMixin) ──────
class _PvtStrategyBase(StrategyBaseMixin):
    """
    حداقلی — از StrategyBaseMixin موجود شما ارث می‌برد.
    متدهای _bump_stat / _hold_quality_from_reason / _build_fallback را بازنویسی
    می‌کند تا اعداد HOLD دقیقاً سازگار با قرارداد ۰.۸۰-gate باشند.
    """

    name: str = "BaseStrategy"
    category: str = "base"
    logger: Any = None

    def _bump_stat(self, key: str, amount: int = 1) -> None:
        """افزایش thread-safe شمارندهٔ آماری؛ هرگز استثنا نمی‌دهد."""
        try:
            stats = getattr(self, "_stats", None)
            if not isinstance(stats, dict):
                return
            inc = int(_pvt_f(amount, 1.0)) if amount is not None else 1
            lock = getattr(self, "_lock", None)
            if isinstance(lock, type(threading.RLock())):
                with lock:
                    stats[key] = int(stats.get(key, 0)) + inc
                return
            if lock is not None:
                try:
                    with lock:
                        stats[key] = int(stats.get(key, 0)) + inc
                    return
                except Exception:
                    pass
            stats[key] = int(stats.get(key, 0)) + inc
        except Exception:
            return

    def _hold_quality_from_reason(self, reason: str, is_fallback: bool = False,
                                  error_type: str = "None") -> float:
        return float(_pvt_hold_quality(
            reason=str(reason or ""), is_fallback=bool(is_fallback),
            error_type=str(error_type or "None"),
        ))

    def _build_fallback(self, reason: str, error_type: str = "GenericError",
                        **kwargs) -> Dict[str, Any]:
        """HOLD ایمن با confidence=0.0 و hold_quality < 0.40."""
        hq = self._hold_quality_from_reason(reason, True, error_type)
        self._bump_stat("fallback_count")
        self._bump_stat("hold_signals")
        self._bump_stat("total_signals")
        return {
            "signal": "HOLD",
            "confidence": 0.0,
            "hold_quality": float(min(0.39, max(0.0, hq))),
            "score": 50.0,
            "reason": f"[{getattr(self, 'name', 'Strategy')}] HOLD: {reason}",
            "strategy_name": getattr(self, "name", "Strategy"),
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "price": float(_pvt_f(kwargs.get("price"), 0.0)),
            "metadata": {
                "strategy_name": getattr(self, "name", "Strategy"),
                "is_fallback": True,
                "error_type": str(error_type or "GenericError"),
                "combine_allowed": False,
            },
            "is_fallback": True,
            "error_type": str(error_type or "GenericError"),
            "is_analytical_hold": False,
            "active_count": 0,
            "combine_allowed": False,
        }

