#Strategies: 📈 Moving Averages          
# ═══════════════════════════════════════════════════════════════════════════

try:
    from numta import *
    NUMTA_AVAILABLE = True
except ImportError:
    NUMTA_AVAILABLE = False

try:
    from pythonpine import *
    PYTHONPINE_AVAILABLE = True
except ImportError:
    PYTHONPINE_AVAILABLE = False

class AdvancedMovingAverages(StrategyBaseMixin):
    """Moving-average strategy with a fail-closed, heuristic-score gate.

    ``confidence`` is a setup score, not an estimated probability of profit.
    Directional delivery additionally requires matching, closed, out-of-sample
    shadow outcomes.  The caller is responsible for collecting those outcomes
    using the actual downstream execution and risk policy.
    """

    VERSION: ClassVar[str] = "6.0.0-SHADOW-GATE"

    DEFAULT_PARAMS: ClassVar[Dict[str, Any]] = {
        "hma_period": 20,
        "zlema_period": 20,
        "tema_period": 15,
        "alma_period": 21,
        "alma_sigma": 6.0,
        "alma_offset": 0.85,
        "mcginley_period": 14,
        "jma_period": 20,
        "jma_fast_period": 2,
        "jma_slow_period": 30,
        "lsma_period": 25,
        "t3_period": 15,
        "t3_v_factor": 0.7,
        "chandelier_period": 22,
        "chandelier_mult": 3.0,
        "atr_period": 14,
        "min_atr_distance": 0.15,
        "max_entry_extension_atr": 2.20,
        "ma_distance_target_atr": 0.85,
        "slope_period": 5,
        "slope_min_abs": 0.02,
        "min_history_bars": 120,
        "max_compute_bars": 5000,
        "use_fast_tail_window": True,
        "tail_warmup_multiplier": 12,
        "min_directional_confidence": 0.70,
        "entry_quality_threshold": 0.74,
        "min_agreement_ratio": 0.72,
        "min_active_count": 3,
        "min_confirming_groups": 3,
        "min_group_agreement": 0.72,
        "min_data_quality": 0.95,
        "max_volatility_rank": 0.95,
        "adx_period": 14,
        "adx_weak_threshold": 16.0,
        "adx_trend_threshold": 22.0,
        "adx_strong_threshold": 32.0,
        "fast_trend_ema_period": 21,
        "slow_trend_ema_period": 55,
        "trend_slope_lookback": 10,
        "momentum_period": 10,
        "volatility_lookback": 80,
        "confidence_weights": {
            "confluence": 0.30,
            "independent_groups": 0.20,
            "trend_strength": 0.18,
            "directional_movement": 0.12,
            "momentum": 0.10,
            "entry_geometry": 0.10,
        },
        "require_calibrated_edge": True,
        "calibration_min_samples": 40,
        "calibrated_min_win_probability": 0.70,
        "calibration_z_score": 1.96,
        "calibration_source": "shadow_oos",
        "execution_policy_id": "",
        "max_pending_signals": 1000,
        "max_outcome_history": 5000,
        "adaptive_min_samples": 200,
        "adaptive_smoothing_alpha": 0.15,
        "adaptive_baseline_win_rate": 0.55,
        "adaptive_sensitivity": 0.65,
        "adaptive_circuit_breaker_losses": 5,
        "adaptive_multiplier_min": 0.75,
        "adaptive_multiplier_max": 1.25,
        "flush_buffer_size": 10,
    }

    def __init__(
        self,
        config: Optional[Dict] = None,
        timeframe: str = "1H",
        logger: Optional[logging.Logger] = logger,
    ):
        super().__init__()
        self.name = "AdvancedMovingAverages"
        self.category = "trend"
        self.timeframe = str(timeframe or "1H").strip().upper()
        self.logger = logger or logging.getLogger(self.name)
        incoming = dict(config) if isinstance(config, dict) else {}
        self.config = copy.deepcopy(self.DEFAULT_PARAMS)
        for key, value in incoming.items():
            if key == "confidence_weights" and isinstance(value, dict):
                merged = dict(self.config["confidence_weights"])
                merged.update(value)
                self.config[key] = merged
            else:
                self.config[key] = value
        validation = incoming.get("validation", {})
        self._validation_config = dict(self.DEFAULT_VALIDATION_CONFIG)
        if isinstance(validation, dict):
            self._validation_config.update(validation)
        self._explicit_min_bars = (
            validation.get("min_bars_required")
            if isinstance(validation, dict) and "min_bars_required" in validation
            else None
        )
        self._self_test_config = dict(self.DEFAULT_SELF_TEST_CONFIG)
        self_test_config = incoming.get("self_test", {})
        if isinstance(self_test_config, dict):
            self._self_test_config.update(self_test_config)
        self.tech_analyzer = get_shared_technical_analyzer()
        self._lock = threading.RLock()
        self._flush_lock = threading.Lock()
        self._performance_multiplier = 1.0
        self._last_snapshot: Optional[PerformanceSnapshot] = None
        self._stats = self._new_stats()
        self._learning_buffer: List[Dict[str, Any]] = []
        self._trade_outcomes: List[Dict[str, Any]] = []
        self._pending_signals: Dict[str, Dict[str, Any]] = {}
        self._evidence_gaps: set[str] = set()
        self._calibration: Dict[str, Dict[str, int]] = {}
        self._sanitize_params()
        self.min_bars = self._required_bars()
        self.logger.info(
            "[%s] version=%s timeframe=%s min_bars=%d; "
            "confidence is a heuristic score; shadow evidence is required",
            self.name, self.VERSION, self.timeframe, self.min_bars,
        )

    @staticmethod
    def _new_stats() -> Dict[str, Any]:
        return {
            "total_signals": 0,
            "total_outcomes": 0,
            "win_rate": 0.0,
            "avg_confidence": 0.0,
            "last_signal_time": None,
            "consecutive_losses": 0,
            "sharpe_proxy": 0.0,
            "execution_times": [],
            "fallback_count": 0,
            "error_count": 0,
            "rejected_signals": 0,
        }

    def _p(self, key: str, default: Any = None) -> Any:
        return self.config.get(key, self.DEFAULT_PARAMS.get(key, default))

    @staticmethod
    def _clip01(value: Any) -> float:
        try:
            number = float(value)
        except (TypeError, ValueError, OverflowError):
            return 0.0
        if not math.isfinite(number):
            return 0.0
        return float(min(1.0, max(0.0, number)))

    @staticmethod
    def _sign(value: Any) -> int:
        try:
            number = float(value)
        except (TypeError, ValueError, OverflowError):
            return 0
        if not math.isfinite(number):
            return 0
        return 1 if number > 0.0 else -1 if number < 0.0 else 0

    @staticmethod
    def _safe_float(value: Any, default: float = 0.0) -> float:
        try:
            number = float(value)
        except (TypeError, ValueError, OverflowError):
            return float(default)
        return float(number) if math.isfinite(number) else float(default)

    @staticmethod
    def _safe_int(value: Any, default: int = 0,
                  minimum: Optional[int] = None) -> int:
        try:
            number = int(float(value))
        except (TypeError, ValueError, OverflowError):
            number = int(default)
        if minimum is not None:
            number = max(int(minimum), number)
        return int(number)

    @staticmethod
    def _utc_datetime(value: Any) -> Optional[datetime]:
        if value is None or isinstance(value, (bool, int, float, np.number)):
            return None
        try:
            stamp = pd.Timestamp(value)
            if pd.isna(stamp) or stamp.tzinfo is None:
                return None
            return stamp.tz_convert("UTC").to_pydatetime()
        except (TypeError, ValueError, OverflowError):
            return None

    def _required_bars(self) -> int:
        period_keys = (
            "hma_period", "zlema_period", "tema_period", "alma_period",
            "mcginley_period", "jma_period", "lsma_period", "t3_period",
            "chandelier_period",
        )
        max_ma = max(
            self._safe_int(self._p(key), self.DEFAULT_PARAMS[key], 2)
            for key in period_keys
        )
        slow = self._safe_int(self._p("slow_trend_ema_period"), 55, 2)
        slope = self._safe_int(self._p("trend_slope_lookback"), 10, 1)
        vol = self._safe_int(self._p("volatility_lookback"), 80, 2)
        adx = self._safe_int(self._p("adx_period"), 14, 2)
        atr = self._safe_int(self._p("atr_period"), 14, 2)
        momentum = self._safe_int(self._p("momentum_period"), 10, 2)
        ma_slope = self._safe_int(self._p("slope_period"), 5, 2)
        hma = self._safe_int(self._p("hma_period"), 20, 4)
        history = self._safe_int(self._p("min_history_bars"), 120, 20)
        explicit = self._safe_int(self._explicit_min_bars, 0, 0)
        return int(max(history, explicit, max_ma * 3, slow + slope + 5,
                       vol + 5, adx * 3, atr * 3, momentum + 2,
                       max_ma + ma_slope + 2,
                       hma + math.isqrt(hma) + ma_slope + 2))

    def _effective_compute_bars(self, required_bars: Optional[int] = None) -> int:
        required = self._safe_int(required_bars, self._required_bars(), 20)
        return max(required, self._safe_int(self._p("max_compute_bars"), 5000, 256))

    def _sanitize_params(self) -> None:
        periods = (
            "hma_period", "zlema_period", "tema_period", "alma_period",
            "mcginley_period", "jma_period", "jma_fast_period", "jma_slow_period",
            "lsma_period", "t3_period", "chandelier_period", "atr_period",
            "adx_period", "fast_trend_ema_period", "slow_trend_ema_period",
            "trend_slope_lookback", "momentum_period", "volatility_lookback",
            "min_history_bars", "min_confirming_groups", "slope_period",
            "min_active_count", "max_compute_bars", "max_pending_signals",
            "max_outcome_history", "flush_buffer_size", "tail_warmup_multiplier",
            "adaptive_min_samples", "adaptive_circuit_breaker_losses",
        )
        for key in periods:
            default = int(self.DEFAULT_PARAMS[key])
            lower = 1 if key in (
                "min_confirming_groups", "min_active_count", "flush_buffer_size",
                "adaptive_circuit_breaker_losses",
            ) else 2
            self.config[key] = self._safe_int(self.config.get(key), default, lower)
        self.config["calibration_min_samples"] = self._safe_int(
            self.config.get("calibration_min_samples"), 40, 40
        )
        bounded = (
            "min_directional_confidence", "entry_quality_threshold",
            "min_group_agreement", "min_agreement_ratio", "min_data_quality",
            "max_volatility_rank", "calibrated_min_win_probability",
            "adaptive_smoothing_alpha", "adaptive_baseline_win_rate",
            "adaptive_sensitivity", "alma_offset", "t3_v_factor",
        )
        for key in bounded:
            default = float(self.DEFAULT_PARAMS[key])
            self.config[key] = self._clip01(self._safe_float(self.config.get(key), default))
        self.config["calibrated_min_win_probability"] = max(
            0.70, self.config["calibrated_min_win_probability"]
        )
        for key in ("adaptive_multiplier_min", "adaptive_multiplier_max"):
            default = float(self.DEFAULT_PARAMS[key])
            self.config[key] = max(0.01, min(2.0, self._safe_float(self.config.get(key), default)))
        if self.config["adaptive_multiplier_max"] < self.config["adaptive_multiplier_min"]:
            self.config["adaptive_multiplier_min"], self.config["adaptive_multiplier_max"] = (
                self.config["adaptive_multiplier_max"], self.config["adaptive_multiplier_min"]
            )
        floors = {
            "min_atr_distance": 0.0,
            "max_entry_extension_atr": 0.10,
            "slope_min_abs": 0.0,
            "alma_sigma": 1e-6,
            "chandelier_mult": 0.10,
            "adx_weak_threshold": 0.0,
            "adx_trend_threshold": 0.0,
            "adx_strong_threshold": 0.0,
            "ma_distance_target_atr": 0.0,
        }
        for key, floor in floors.items():
            default = float(self.DEFAULT_PARAMS[key])
            self.config[key] = max(floor, self._safe_float(self.config.get(key), default))
        self.config["calibration_z_score"] = max(
            1.96, min(4.0, self._safe_float(self.config.get("calibration_z_score"), 1.96))
        )
        self.config["jma_slow_period"] = max(
            self.config["jma_slow_period"], self.config["jma_fast_period"] + 1
        )
        self.config["slow_trend_ema_period"] = max(
            self.config["slow_trend_ema_period"], self.config["fast_trend_ema_period"] + 1
        )
        self.config["max_entry_extension_atr"] = max(
            self.config["max_entry_extension_atr"], self.config["min_atr_distance"] + 0.10
        )
        weights = self.config.get("confidence_weights")
        defaults = self.DEFAULT_PARAMS["confidence_weights"]
        if not isinstance(weights, dict):
            weights = {}
        clean = {
            key: max(0.0, self._safe_float(weights.get(key), float(default)))
            for key, default in defaults.items()
        }
        self.config["confidence_weights"] = clean if sum(clean.values()) > 0.0 else dict(defaults)
        self.config["require_calibrated_edge"] = True
        self.config["calibration_source"] = "shadow_oos"
        self.config["execution_policy_id"] = str(
            self.config.get("execution_policy_id", "") or ""
        ).strip()

    def _validate_input(self, df=None, **kwargs):
        if kwargs.get("min_length") is None:
            kwargs["min_length"] = self._required_bars()
        return super()._validate_input(df=df, **kwargs)

    def update_performance_snapshot(self, snapshot: Optional[PerformanceSnapshot]) -> None:
        try:
            with self._lock:
                self._last_snapshot = snapshot
                if snapshot is None:
                    return
                candidate = compute_adaptive_multiplier(
                    current_multiplier=self._performance_multiplier,
                    snapshot=snapshot,
                    min_samples=int(self._p("adaptive_min_samples")),
                    smoothing_alpha=float(self._p("adaptive_smoothing_alpha")),
                    baseline_win_rate=float(self._p("adaptive_baseline_win_rate")),
                    sensitivity=float(self._p("adaptive_sensitivity")),
                    circuit_breaker_losses=int(self._p("adaptive_circuit_breaker_losses")),
                    multiplier_min=float(self._p("adaptive_multiplier_min")),
                    multiplier_max=float(self._p("adaptive_multiplier_max")),
                    logger=self.logger,
                    strategy_name=self.name,
                )
                if math.isfinite(self._safe_float(candidate, math.nan)):
                    self._performance_multiplier = float(candidate)
        except Exception as exc:
            self.logger.error("[%s] performance snapshot update failed: %s", self.name, exc, exc_info=True)

    def _repair_nonfinite_1d(self, arr: np.ndarray, fallback: float = 0.0) -> np.ndarray:
        values = np.asarray(arr, dtype=np.float64).reshape(-1).copy()
        last = self._safe_float(fallback, 0.0)
        for index in range(values.size):
            if math.isfinite(float(values[index])):
                last = float(values[index])
            else:
                values[index] = last
        return np.ascontiguousarray(values, dtype=np.float64)

    def _ema(self, values: np.ndarray, period: int) -> np.ndarray:
        return self.tech_analyzer.calculate_ema(values, max(2, int(period)))

    def _rma(self, values: np.ndarray, period: int) -> np.ndarray:
        return self.tech_analyzer.calculate_rma(values, max(2, int(period)))

    def _wma(self, arr: np.ndarray, period: int) -> np.ndarray:
        return self.tech_analyzer.calculate_wma(arr, max(1, int(period)))

    def _rolling_sum(self, arr: np.ndarray, period: int) -> np.ndarray:
        return self.tech_analyzer.calculate_rolling_sum(arr, max(1, int(period)))

    def _rolling_extreme(self, arr: np.ndarray, period: int, mode: str) -> np.ndarray:
        if str(mode).lower() == "max":
            return self.tech_analyzer.calculate_rolling_max(arr, max(1, int(period)))
        return self.tech_analyzer.calculate_rolling_min(arr, max(1, int(period)))

    def _calc_linear_slope(self, series: np.ndarray, period: int) -> float:
        values = np.asarray(series, dtype=np.float64).reshape(-1)
        length = max(2, int(period))
        if values.size < length or not np.isfinite(values[-length:]).all():
            return math.nan
        y = values[-length:]
        x = np.arange(length, dtype=np.float64)
        x -= x.mean()
        denominator = float(np.dot(x, x))
        if denominator <= 0.0:
            return math.nan
        return float(np.dot(x, y - y.mean()) / denominator)

    def _atr_series(self, high: np.ndarray, low: np.ndarray, close: np.ndarray,
                    period: int) -> np.ndarray:
        return self.tech_analyzer.calculate_atr(high, low, close, max(2, int(period)))

    def _calc_atr_vectorized(self, high: np.ndarray, low: np.ndarray,
                             close: np.ndarray, period: int) -> float:
        return self.tech_analyzer.calculate_atr_value(high, low, close, max(2, int(period)))

    def _weighted_ma(self, arr: np.ndarray, weights: np.ndarray) -> np.ndarray:
        values = np.asarray(arr, dtype=np.float64).reshape(-1)
        weights_array = np.asarray(weights, dtype=np.float64).reshape(-1)
        out = np.full(values.size, np.nan, dtype=np.float64)
        period = weights_array.size
        if period < 1 or values.size < period or not np.isfinite(weights_array).all():
            return out
        weight_sum = float(weights_array.sum())
        if not math.isfinite(weight_sum) or abs(weight_sum) <= 1e-15:
            return out
        finite = np.isfinite(values)
        result = np.correlate(np.where(finite, values, 0.0), weights_array / weight_sum, mode="valid")
        if not finite.all():
            count = np.correlate(finite.astype(np.float64), np.ones(period), mode="valid")
            result[count < period] = np.nan
        out[period - 1:] = result
        return out

    def _extract_ohlc_arrays(self, df: pd.DataFrame) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray]:
        empty = np.empty(0, dtype=np.float64)
        if not isinstance(df, pd.DataFrame) or df.empty:
            return empty, empty, empty, empty
        arrays = []
        try:
            for name in ("open", "high", "low", "close"):
                if name not in df.columns or list(df.columns).count(name) != 1:
                    return empty, empty, empty, empty
                values = df[name].to_numpy(dtype=np.float64, copy=False)
                if values.ndim != 1:
                    return empty, empty, empty, empty
                arrays.append(np.ascontiguousarray(values, dtype=np.float64))
        except (TypeError, ValueError, OverflowError):
            return empty, empty, empty, empty
        return arrays[0], arrays[1], arrays[2], arrays[3]

    def _prepare_frame_for_analysis(
        self, df: pd.DataFrame
    ) -> Tuple[bool, str, Optional[pd.DataFrame], float, Dict[str, Any]]:
        required_bars = self._required_bars()
        metadata: Dict[str, Any] = {
            "required_bars": required_bars,
            "original_bars": 0,
            "bars_used": 0,
            "tail_window_applied": False,
            "finite_ratio_before_repair": 0.0,
            "prices_repaired": False,
            "last_bar_time_utc": None,
            "chronology_checked": False,
        }
        if not isinstance(df, pd.DataFrame) or df.empty:
            return False, "Input is empty or not a DataFrame", None, 0.0, metadata
        metadata["original_bars"] = int(len(df))
        if len(df) < required_bars:
            return False, f"Insufficient history: {len(df)} < {required_bars}", None, 0.0, metadata
        required = ("open", "high", "low", "close")
        columns = list(df.columns)
        missing = [name for name in required if columns.count(name) == 0]
        duplicated = [name for name in required if columns.count(name) > 1]
        if missing or duplicated:
            return False, f"Missing OHLC={missing}; duplicated OHLC={duplicated}", None, 0.0, metadata
        if columns.count("time") > 1:
            return False, "Duplicated time column", None, 0.0, metadata
        if not df.index.is_unique or not df.index.is_monotonic_increasing:
            return False, "Index must be unique and increasing", None, 0.0, metadata
        work_source = df
        compute_bars = self._effective_compute_bars(required_bars)
        if self._p("use_fast_tail_window", True) is True and len(df) > compute_bars:
            work_source = df.iloc[-compute_bars:]
            metadata["tail_window_applied"] = True
        metadata["bars_used"] = int(len(work_source))
        raw_time = None
        if isinstance(work_source.index, pd.DatetimeIndex):
            raw_time = work_source.index
        elif "time" in work_source.columns:
            try:
                time_column = work_source["time"]
                if pd.api.types.is_numeric_dtype(time_column.dtype):
                    raw_time = pd.DatetimeIndex(pd.to_datetime(time_column, unit="s", utc=True, errors="coerce"))
                else:
                    raw_time = pd.DatetimeIndex(pd.to_datetime(time_column, errors="coerce"))
            except (TypeError, ValueError, OverflowError) as exc:
                return False, f"Invalid time column: {exc}", None, 0.0, metadata
        if raw_time is not None:
            if raw_time.hasnans or not raw_time.is_unique or not raw_time.is_monotonic_increasing:
                return False, "Timestamps must be finite, unique and increasing", None, 0.0, metadata
            metadata["chronology_checked"] = True
            if raw_time.tz is not None:
                metadata["last_bar_time_utc"] = raw_time[-1].tz_convert("UTC").isoformat()
        arrays: Dict[str, np.ndarray] = {}
        try:
            for name in required:
                values = work_source[name].to_numpy(dtype=np.float64, copy=True)
                if values.ndim != 1 or values.size != len(work_source):
                    return False, f"Invalid shape for {name}", None, 0.0, metadata
                arrays[name] = np.ascontiguousarray(values, dtype=np.float64)
        except (TypeError, ValueError, OverflowError) as exc:
            return False, f"Non-numeric OHLC: {exc}", None, 0.0, metadata
        matrix = np.column_stack([arrays[name] for name in required])
        finite = np.isfinite(matrix)
        metadata["finite_ratio_before_repair"] = float(finite.mean())
        if not finite.all():
            return False, "Non-finite OHLC; prices are not repaired", None, 0.0, metadata
        if np.any(matrix <= 0.0):
            return False, "Non-positive OHLC price", None, 0.0, metadata
        open_arr, high, low, close = (arrays[name] for name in required)
        invalid = (high < np.maximum(open_arr, close)) | (low > np.minimum(open_arr, close)) | (high < low)
        if invalid.any():
            return False, f"Invalid OHLC structure on {int(invalid.sum())} bars", None, 0.0, metadata
        variance_threshold = max(
            0.0, self._safe_float(self._validation_config.get("min_variance_threshold"), 1e-10)
        )
        if float(np.std(close)) <= variance_threshold:
            return False, "Degenerate close series", None, 0.0, metadata
        frame = pd.DataFrame({name: arrays[name] for name in required}, index=work_source.index)
        if "volume" in columns and columns.count("volume") == 1:
            try:
                volume = work_source["volume"].to_numpy(dtype=np.float64, copy=True)
                if volume.ndim == 1 and volume.size == len(frame) and np.isfinite(volume).all() and np.all(volume >= 0.0):
                    frame["volume"] = np.ascontiguousarray(volume, dtype=np.float64)
            except (TypeError, ValueError, OverflowError) as exc:
                metadata["volume_ignored_reason"] = str(exc)
        frame.attrs.update(work_source.attrs)
        return True, f"Valid ({len(frame)} bars)", frame, float(close[-1]), metadata

    def _calculate_data_quality_vectorized(self, df: pd.DataFrame) -> float:
        open_arr, high, low, close = self._extract_ohlc_arrays(df)
        if close.size == 0:
            return 0.0
        finite = np.isfinite(open_arr) & np.isfinite(high) & np.isfinite(low) & np.isfinite(close)
        valid = finite & (open_arr > 0.0) & (high > 0.0) & (low > 0.0) & (close > 0.0)
        valid &= (high >= np.maximum(open_arr, close)) & (low <= np.minimum(open_arr, close)) & (high >= low)
        return float(valid.mean())

    def _market_context(self, df: pd.DataFrame) -> Dict[str, Any]:
        _, high, low, close = self._extract_ohlc_arrays(df)
        n = close.size
        if n < self._required_bars() or high.size != n or low.size != n:
            raise ValueError("Insufficient or inconsistent arrays for market context")
        atr = np.asarray(_fast_atr_1d(high, low, close, int(self._p("atr_period"))), dtype=np.float64)
        adx, plus_di, minus_di = _fast_adx_di_1d(high, low, close, int(self._p("adx_period")))
        adx = np.asarray(adx, dtype=np.float64)
        plus_di = np.asarray(plus_di, dtype=np.float64)
        minus_di = np.asarray(minus_di, dtype=np.float64)
        fast = np.asarray(self._ema(close, int(self._p("fast_trend_ema_period"))), dtype=np.float64)
        slow = np.asarray(self._ema(close, int(self._p("slow_trend_ema_period"))), dtype=np.float64)
        for name, array in (("ATR", atr), ("ADX", adx), ("+DI", plus_di), ("-DI", minus_di),
                            ("fast EMA", fast), ("slow EMA", slow)):
            if array.ndim != 1 or array.size != n or not math.isfinite(float(array[-1])):
                raise ValueError(f"Invalid {name} result")
        atr_value = float(atr[-1])
        if atr_value <= 0.0:
            raise ValueError("ATR is not positive")
        adx_value = float(adx[-1])
        plus_value = float(plus_di[-1])
        minus_value = float(minus_di[-1])
        if not (0.0 <= adx_value <= 100.0 and 0.0 <= plus_value <= 100.0 and 0.0 <= minus_value <= 100.0):
            raise ValueError("ADX or directional movement outside [0, 100]")
        fast_value, slow_value = float(fast[-1]), float(slow[-1])
        if fast_value <= 0.0 or slow_value <= 0.0:
            raise ValueError("Invalid trend EMA value")
        ema_dir = self._sign(fast_value - slow_value)
        di_dir = self._sign(plus_value - minus_value)
        trend_dir = ema_dir if ema_dir == di_dir else 0
        look = min(int(self._p("trend_slope_lookback")), n - 1)
        momentum_period = min(int(self._p("momentum_period")), n - 1)
        if not math.isfinite(float(slow[-1 - look])):
            raise ValueError("Invalid historical slow EMA")
        slow_slope = (slow_value - float(slow[-1 - look])) / (atr_value * math.sqrt(look))
        momentum = (float(close[-1]) - float(close[-1 - momentum_period])) / (atr_value * math.sqrt(momentum_period))
        recent_atr = atr[-min(n, max(5, int(self._p("volatility_lookback")))):]
        if not np.isfinite(recent_atr).all():
            raise ValueError("Invalid ATR history")
        volatility_rank = float((np.count_nonzero(recent_atr < atr_value) +
                                 0.5 * np.count_nonzero(recent_atr == atr_value)) / recent_atr.size)
        return {
            "atr": atr_value,
            "atr_pct": atr_value / float(close[-1]),
            "adx": adx_value,
            "plus_di": plus_value,
            "minus_di": minus_value,
            "di_strength": abs(plus_value - minus_value) / max(plus_value + minus_value, 1e-12),
            "fast_ema": fast_value,
            "slow_ema": slow_value,
            "ema_direction": int(ema_dir),
            "di_direction": int(di_dir),
            "trend_direction": int(trend_dir),
            "slow_slope_norm": float(slow_slope),
            "momentum_norm": float(momentum),
            "volatility_rank": self._clip01(volatility_rank),
            "close": float(close[-1]),
        }

    def _regime_from_context(self, context: Dict[str, Any]) -> str:
        adx = self._safe_float(context.get("adx"), 0.0)
        direction = self._safe_int(context.get("trend_direction"), 0)
        if direction == 0:
            return "WEAK_TREND_OR_TRANSITION" if adx >= float(self._p("adx_weak_threshold")) else "RANGING"
        if adx >= float(self._p("adx_strong_threshold")):
            return "STRONG_TREND"
        if adx >= float(self._p("adx_trend_threshold")):
            return "TRENDING"
        if adx >= float(self._p("adx_weak_threshold")):
            return "WEAK_TREND_OR_TRANSITION"
        return "RANGING"

    def _detect_regime_vectorized(self, df: pd.DataFrame) -> str:
        try:
            return self._regime_from_context(self._market_context(df))
        except Exception as exc:
            self.logger.warning("[%s] regime detection failed: %s", self.name, exc, exc_info=True)
            return "UNKNOWN"

    def _detect_regime(self, df: pd.DataFrame) -> str:
        return self._detect_regime_vectorized(df)

    def _evaluate_ma_vectorized(
        self, close: np.ndarray, ma_values: np.ndarray, atr_value: float, name: str
    ) -> Tuple[str, float, str, float]:
        close_array = np.asarray(close, dtype=np.float64)
        ma = np.asarray(ma_values, dtype=np.float64)
        period = int(self._p("slope_period"))
        if close_array.ndim != 1 or ma.ndim != 1:
            return "HOLD", 0.0, f"{name}: error: indicator must be one-dimensional", 0.0
        if close_array.size < max(3, period) or ma.size != close_array.size:
            return "HOLD", 0.0, f"{name}: error: invalid indicator length", 0.0
        if not np.isfinite(ma[-period:]).all() or not math.isfinite(float(close_array[-1])):
            return "HOLD", 0.0, f"{name}: error: invalid indicator values", 0.0
        current_price = float(close_array[-1])
        current_ma = float(ma[-1])
        atr = self._safe_float(atr_value, 0.0)
        if current_price <= 0.0 or current_ma <= 0.0 or atr <= 0.0:
            return "HOLD", 0.0, f"{name}: error: invalid price or ATR", 0.0
        slope = self._calc_linear_slope(ma, period) / atr
        distance = (current_price - current_ma) / atr
        if not (math.isfinite(slope) and math.isfinite(distance)):
            return "HOLD", 0.0, f"{name}: error: non-finite slope or distance", current_ma
        if abs(distance) < float(self._p("min_atr_distance")):
            return "HOLD", 0.0, f"{name}: price too close to MA", current_ma
        if abs(distance) > float(self._p("max_entry_extension_atr")):
            return "HOLD", 0.0, f"{name}: price overextended", current_ma
        if abs(slope) < float(self._p("slope_min_abs")):
            return "HOLD", 0.0, f"{name}: slope too weak", current_ma
        side = "BUY" if distance > 0.0 and slope > 0.0 else "SELL" if distance < 0.0 and slope < 0.0 else "HOLD"
        if side == "HOLD":
            return "HOLD", 0.0, f"{name}: price/slope disagreement", current_ma
        score = min(0.93, 0.70 + min(abs(slope) * 0.50, 0.10) + min(abs(distance) * 0.05, 0.13))
        return side, float(score), f"{name}: {side} dist={distance:.3f}ATR slope={slope:.4f}", current_ma

    def _calculate_ma_delegate(self, close: np.ndarray, atr_value: float, name: str,
                               calculator: Callable[[], Any]) -> Tuple[str, float, str, float]:
        try:
            values = calculator()
            return self._evaluate_ma_vectorized(close, values, atr_value, name)
        except Exception as exc:
            self.logger.warning("[%s] %s calculation failed: %s", self.name, name, exc, exc_info=True)
            return "HOLD", 0.0, f"{name}: error: {type(exc).__name__}", 0.0

    def _calc_hma_vectorized(self, close, high, low, atr_value):
        return self._calculate_ma_delegate(close, atr_value, "HMA", lambda: self.tech_analyzer.calculate_hma(close, int(self._p("hma_period"))))

    def _calc_jma_vectorized(self, close, high, low, atr_value):
        return self._calculate_ma_delegate(close, atr_value, "JMA", lambda: self.tech_analyzer.calculate_jma(
            close, period=int(self._p("jma_period")), fast=int(self._p("jma_fast_period")), slow=int(self._p("jma_slow_period"))))

    def _calc_zlema_vectorized(self, close, high, low, atr_value):
        return self._calculate_ma_delegate(close, atr_value, "ZLEMA", lambda: self.tech_analyzer.calculate_zlema(close, int(self._p("zlema_period"))))

    def _calc_tema_vectorized(self, close, high, low, atr_value):
        return self._calculate_ma_delegate(close, atr_value, "TEMA", lambda: self.tech_analyzer.calculate_tema(close, int(self._p("tema_period"))))

    def _calc_alma_vectorized(self, close, high, low, atr_value):
        return self._calculate_ma_delegate(close, atr_value, "ALMA", lambda: self.tech_analyzer.calculate_alma(
            close, int(self._p("alma_period")), float(self._p("alma_sigma")), float(self._p("alma_offset"))))

    def _calc_mcginley_vectorized(self, close, high, low, atr_value):
        return self._calculate_ma_delegate(close, atr_value, "McGinley", lambda: self.tech_analyzer.calculate_mcginley(close, int(self._p("mcginley_period"))))

    def _calc_lsma_vectorized(self, close, high, low, atr_value):
        return self._calculate_ma_delegate(close, atr_value, "LSMA", lambda: self.tech_analyzer.calculate_lsma(close, int(self._p("lsma_period"))))

    def _calc_t3_vectorized(self, close, high, low, atr_value):
        return self._calculate_ma_delegate(close, atr_value, "T3", lambda: self.tech_analyzer.calculate_t3(close, int(self._p("t3_period")), float(self._p("t3_v_factor"))))

    def _calc_chandelier_vectorized(self, close, high, low, atr_value):
        try:
            long_stop, short_stop, direction = self.tech_analyzer.calculate_chandelier_stops(
                high, low, close, int(self._p("chandelier_period")), float(self._p("chandelier_mult"))
            )
            arrays = [np.asarray(item) for item in (long_stop, short_stop, direction)]
            if not all(item.ndim == 1 and item.size == len(close) for item in arrays):
                raise ValueError("invalid chandelier array length")
            long_value, short_value, last_direction = (float(item[-1]) for item in arrays)
            price = float(close[-1])
            atr = self._safe_float(atr_value, 0.0)
            if not all(math.isfinite(x) for x in (long_value, short_value, last_direction, price, atr)) or atr <= 0.0:
                raise ValueError("non-finite chandelier result")
            if last_direction == 0.0 and long_value == 0.0 and short_value == 0.0:
                raise ValueError("chandelier returned fallback zeros")
            if last_direction > 0.0 and price > long_value:
                distance = (price - long_value) / atr
                return "BUY", float(min(0.90, 0.70 + min(distance * 0.05, 0.20))), "Chandelier: BUY", long_value
            if last_direction < 0.0 and price < short_value:
                distance = (short_value - price) / atr
                return "SELL", float(min(0.90, 0.70 + min(distance * 0.05, 0.20))), "Chandelier: SELL", short_value
            return "HOLD", 0.0, "Chandelier: neutral", float((long_value + short_value) * 0.5)
        except Exception as exc:
            self.logger.warning("[%s] Chandelier failed: %s", self.name, exc, exc_info=True)
            return "HOLD", 0.0, f"Chandelier: error: {type(exc).__name__}", 0.0

    def _calculate_indicators_vectorized(self, df: pd.DataFrame) -> dict:
        _, high, low, close = self._extract_ohlc_arrays(df)
        context = self._market_context(df)
        atr = float(context["atr"])
        configs = (
            ("HMA", "fast", self._calc_hma_vectorized),
            ("ZLEMA", "fast", self._calc_zlema_vectorized),
            ("TEMA", "fast", self._calc_tema_vectorized),
            ("ALMA", "fast", self._calc_alma_vectorized),
            ("McGinley", "adaptive", self._calc_mcginley_vectorized),
            ("JMA", "adaptive", self._calc_jma_vectorized),
            ("T3", "adaptive", self._calc_t3_vectorized),
            ("LSMA", "structural", self._calc_lsma_vectorized),
            ("Chandelier", "trailing", self._calc_chandelier_vectorized),
        )
        details: Dict[str, Dict[str, Any]] = {}
        errors = []
        for name, group, function in configs:
            side, confidence, reason, value = function(close, high, low, atr)
            side = str(side).upper().strip()
            if side not in ("BUY", "SELL", "HOLD"):
                side = "HOLD"
                reason = f"{name}: error: invalid signal"
            if ": error:" in str(reason).lower():
                errors.append(name)
            numeric_value = self._safe_float(value, math.nan)
            details[name] = {
                "group": group,
                "signal": side,
                "confidence": self._clip01(confidence) if side != "HOLD" else 0.0,
                "reason": str(reason),
                "value": numeric_value if math.isfinite(numeric_value) else None,
            }
        group_summary = {}
        raw_buy = raw_sell = buy_groups = sell_groups = 0
        buy_strength = sell_strength = 0.0
        for group in ("fast", "adaptive", "structural", "trailing"):
            members = [(name, info) for name, info in details.items() if info["group"] == group]
            buy_names = [name for name, info in members if info["signal"] == "BUY"]
            sell_names = [name for name, info in members if info["signal"] == "SELL"]
            raw_buy += len(buy_names)
            raw_sell += len(sell_names)
            signed = [info["confidence"] if info["signal"] == "BUY" else -info["confidence"]
                      for _, info in members if info["signal"] != "HOLD"]
            net = float(np.mean(signed)) if signed else 0.0
            group_side = "BUY" if net > 0.0 else "SELL" if net < 0.0 else "HOLD"
            if net > 0.0:
                buy_groups += 1
                buy_strength += net
            elif net < 0.0:
                sell_groups += 1
                sell_strength -= net
            group_summary[group] = {
                "direction": group_side,
                "strength": abs(net),
                "members": buy_names + sell_names,
                "buy_members": buy_names,
                "sell_members": sell_names,
                "member_count": len(signed),
            }
        total_strength = buy_strength + sell_strength
        active = raw_buy + raw_sell
        return {
            "details": details,
            "summary": {name: item["value"] for name, item in details.items() if item["value"] is not None},
            "context": context,
            "group_summary": group_summary,
            "raw_buy_count": raw_buy,
            "raw_sell_count": raw_sell,
            "buy_count": raw_buy,
            "sell_count": raw_sell,
            "active_count": active,
            "independent_active_groups": buy_groups + sell_groups,
            "buy_group_count": buy_groups,
            "sell_group_count": sell_groups,
            "buy_strength": float(buy_strength),
            "sell_strength": float(sell_strength),
            "agreement_ratio": max(buy_strength, sell_strength) / total_strength if total_strength > 0.0 else 0.0,
            "dominance_ratio": abs(buy_strength - sell_strength) / total_strength if total_strength > 0.0 else 0.0,
            "agreement_raw": max(raw_buy, raw_sell) / active if active else 0.0,
            "metadata": {"indicator_errors": errors, "groups_are_statistically_independent": False},
        }

    def _calculate_indicators(self, df: pd.DataFrame) -> dict:
        return self._calculate_indicators_vectorized(df)

    def _quality_floor(self) -> float:
        bundle = _resolve_env_threshold_bundle()
        if not isinstance(bundle, dict) or "quality_floor" not in bundle:
            raise ValueError("quality threshold bundle is unavailable")
        value = self._safe_float(bundle["quality_floor"], math.nan)
        if not math.isfinite(value) or not 0.0 <= value <= 1.0:
            raise ValueError("quality threshold is invalid")
        return float(max(0.80, value))

    def _config_fingerprint(self, floor: float) -> str:
        params = {key: self.config.get(key) for key in self.DEFAULT_PARAMS}
        payload = {
            "strategy_version": self.VERSION,
            "timeframe": self.timeframe,
            "quality_floor": float(floor),
            "parameters": params,
            "explicit_min_bars": self._explicit_min_bars,
            "variance_threshold": self._validation_config.get("min_variance_threshold"),
        }
        encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"),
                             default=str, allow_nan=False).encode("utf-8")
        return hashlib.sha256(encoded).hexdigest()

    @staticmethod
    def _calibration_key(regime: str, direction: str) -> str:
        return f"{str(regime).upper()}::{str(direction).upper()}"

    def _wilson_lower_bound(self, wins: int, total: int, z: float) -> float:
        wins = self._safe_int(wins, 0, 0)
        total = self._safe_int(total, 0, 0)
        z = self._safe_float(z, 1.96)
        if total <= 0 or wins > total or z <= 0.0:
            return 0.0
        proportion = wins / total
        z_squared = z * z
        denominator = 1.0 + z_squared / total
        centre = proportion + z_squared / (2.0 * total)
        margin = z * math.sqrt(proportion * (1.0 - proportion) / total + z_squared / (4.0 * total * total))
        return float(max(0.0, min(1.0, (centre - margin) / denominator)))

    def _cohort_key(self, context: Dict[str, Any], regime: str, direction: str) -> str:
        parts = [context.get("symbol"), context.get("timeframe", self.timeframe),
                 context.get("execution_policy_id"), context.get("config_fingerprint"),
                 str(regime).upper(), str(direction).upper()]
        return hashlib.sha256(json.dumps(parts, separators=(",", ":"), default=str).encode("utf-8")).hexdigest()

    def _get_calibration_estimate(self, regime: str, direction: str,
                                  *, context: Optional[Dict[str, Any]] = None) -> dict:
        empty = {
            "key": self._calibration_key(regime, direction),
            "wins": 0,
            "losses": 0,
            "samples": 0,
            "observed_win_rate": None,
            "wilson_lower_bound": None,
            "source": "shadow_oos",
            "status": "unavailable",
        }
        if not isinstance(context, dict):
            return empty
        with self._lock:
            coverage_gap = self._cohort_key(context, regime, direction) in self._evidence_gaps
        if coverage_gap:
            empty["status"] = "coverage_incomplete"
            return empty
        as_of = self._utc_datetime(context.get("as_of"))
        if as_of is None:
            return empty
        with self._lock:
            records = list(self._trade_outcomes)
            pending_records = list(self._pending_signals.values())
        events: Dict[str, Tuple[datetime, Optional[datetime], Optional[bool]]] = {}
        for record in records + pending_records:
            if not isinstance(record, dict):
                continue
            signal_id = record.get("signal_id")
            if not isinstance(signal_id, str) or not signal_id or signal_id in events:
                continue
            if record.get("symbol") != context.get("symbol") or record.get("timeframe") != self.timeframe:
                continue
            if record.get("execution_policy_id") != context.get("execution_policy_id"):
                continue
            if record.get("config_fingerprint") != context.get("config_fingerprint"):
                continue
            if record.get("regime") != str(regime).upper() or record.get("direction") != str(direction).upper():
                continue
            if self._safe_float(record.get("setup_quality"), 0.0) < self._safe_float(context.get("quality_floor"), 1.0):
                continue
            decision_time = self._utc_datetime(record.get("decision_time"))
            if decision_time is None or decision_time >= as_of:
                continue
            closed_at = self._utc_datetime(record.get("closed_at"))
            label = record.get("was_correct")
            qualified = (record.get("source") == "shadow_oos" and record.get("out_of_sample") is True
                         and record.get("is_closed") is True and type(label) is bool
                         and closed_at is not None and closed_at > decision_time)
            if qualified and closed_at <= as_of:
                events[signal_id] = (decision_time, closed_at, label)
            else:
                events[signal_id] = (decision_time, None, None)
        wins = losses = skipped_overlaps = trailing_losses = 0
        previous_close: Optional[datetime] = None
        incomplete = False
        for decision_time, closed_at, label in sorted(events.values(), key=lambda row: row[0]):
            if previous_close is not None and decision_time < previous_close:
                skipped_overlaps += 1
                continue
            if closed_at is None or label is None:
                incomplete = True
                break
            if label:
                wins += 1
                trailing_losses = 0
            else:
                losses += 1
                trailing_losses += 1
            previous_close = closed_at
        total = wins + losses
        minimum = int(self._p("calibration_min_samples"))
        lower = self._wilson_lower_bound(wins, total, float(self._p("calibration_z_score"))) if total else None
        required = float(self._p("calibrated_min_win_probability"))
        loss_limit = int(self._p("adaptive_circuit_breaker_losses"))
        if trailing_losses >= loss_limit:
            status = "shadow_circuit_breaker"
        elif total < minimum:
            status = "cold_start"
        elif lower is None or lower < required:
            status = "edge_unproven"
        else:
            status = "evidence_available"
        return {
            "key": self._calibration_key(regime, direction),
            "wins": wins,
            "losses": losses,
            "samples": total,
            "observed_win_rate": wins / total if total else None,
            "wilson_lower_bound": lower,
            "source": "shadow_oos",
            "minimum_samples": minimum,
            "minimum_wilson_lower_bound": required,
            "z_score": float(self._p("calibration_z_score")),
            "shadow_consecutive_losses": trailing_losses,
            "shadow_circuit_breaker_limit": loss_limit,
            "skipped_overlapping_candidates": skipped_overlaps,
            "incomplete_earlier_candidate": incomplete,
            "status": status,
            "note": "Non-overlap reduces, but does not remove, dependence. Wilson coverage and OOS provenance are not independently verified; score is not a probability.",
        }

    def _hold_quality_for_rejection(self, reason: str, setup_quality: float = 0.0) -> float:
        text = str(reason or "").lower()
        if "error" in text or "invalid" in text:
            return 0.25
        return 0.30

    def _reject_signal(self, indicators: dict, reason: str, quality: float,
                       **extra) -> Tuple[str, float, str, dict]:
        meta = {
            "accepted": False,
            "setup_quality": self._clip01(quality),
            "hold_quality": self._hold_quality_for_rejection(reason, quality),
            **extra,
        }
        if isinstance(indicators, dict):
            indicators["decision"] = meta
        return "HOLD", self._clip01(quality), str(reason), meta

    def _generate_signal_vectorized(
        self, indicators: dict, regime: str, df: pd.DataFrame
    ) -> Tuple[str, float, str, dict]:
        if not isinstance(indicators, dict):
            return self._reject_signal({}, "Invalid indicators", 0.0)
        context = indicators.get("context")
        if not isinstance(context, dict) or not context:
            return self._reject_signal(indicators, "No valid market context", 0.0)
        indicator_meta = indicators.get("metadata")
        if isinstance(indicator_meta, dict) and indicator_meta.get("indicator_errors"):
            return self._reject_signal(indicators, "Indicator calculation error", 0.0,
                                       indicator_errors=list(indicator_meta["indicator_errors"]))
        buy = self._safe_float(indicators.get("buy_strength"), 0.0)
        sell = self._safe_float(indicators.get("sell_strength"), 0.0)
        agreement = self._safe_float(indicators.get("agreement_ratio"), 0.0)
        active = self._safe_int(indicators.get("active_count"), 0, 0)
        buy_groups = self._safe_int(indicators.get("buy_group_count"), 0, 0)
        sell_groups = self._safe_int(indicators.get("sell_group_count"), 0, 0)
        groups = self._safe_int(indicators.get("independent_active_groups"), 0, 0)
        if buy < 0.0 or sell < 0.0 or buy + sell <= 0.0:
            return self._reject_signal(indicators, "No active MA group", 0.0)
        if math.isclose(buy, sell, rel_tol=1e-12, abs_tol=1e-12):
            return self._reject_signal(indicators, "Tied BUY and SELL strength", 0.0)
        if active < int(self._p("min_active_count")):
            return self._reject_signal(indicators, "Active MA count too low", 0.0, active_count=active)
        direction = 1 if buy > sell else -1
        side = "BUY" if direction > 0 else "SELL"
        confirming = buy_groups if direction > 0 else sell_groups
        if str(regime).upper() not in ("TRENDING", "STRONG_TREND"):
            return self._reject_signal(indicators, f"Regime rejected: {regime}", 0.0, direction=side)
        adx = self._safe_float(context.get("adx"), 0.0)
        trend_direction = self._safe_int(context.get("trend_direction"), 0)
        di_strength = self._clip01(context.get("di_strength"))
        momentum = self._safe_float(context.get("momentum_norm"), 0.0)
        slope = self._safe_float(context.get("slow_slope_norm"), 0.0)
        vol_rank = self._safe_float(context.get("volatility_rank"), 1.0)
        atr = self._safe_float(context.get("atr"), 0.0)
        ema = self._safe_float(context.get("fast_ema"), 0.0)
        price = self._safe_float(context.get("close"), 0.0)
        if atr <= 0.0 or ema <= 0.0 or price <= 0.0:
            return self._reject_signal(indicators, "Invalid market context values", 0.0)
        if trend_direction != direction or adx < float(self._p("adx_trend_threshold")):
            return self._reject_signal(indicators, "EMA/DI/ADX does not confirm consensus", 0.0, direction=side)
        minimum_groups = int(self._p("min_confirming_groups"))
        if confirming < minimum_groups:
            return self._reject_signal(indicators, "Too few confirming groups", 0.0,
                                       direction=side, confirming_groups=confirming, active_groups=groups)
        agreement_floor = max(float(self._p("min_group_agreement")), float(self._p("min_agreement_ratio")))
        if not 0.0 <= agreement <= 1.0 or agreement < agreement_floor:
            return self._reject_signal(indicators, "Group agreement too low or invalid", 0.0, agreement_ratio=agreement)
        if not 0.0 <= vol_rank <= float(self._p("max_volatility_rank")):
            return self._reject_signal(indicators, "Volatility rank rejected", 0.0, volatility_rank=vol_rank)
        adx_floor = float(self._p("adx_trend_threshold"))
        adx_ceiling = max(float(self._p("adx_strong_threshold")), adx_floor + 1.0)
        trend_strength = self._clip01((adx - adx_floor) / (adx_ceiling - adx_floor))
        slope_score = self._clip01(abs(slope) / 0.35) if self._sign(slope) == direction else 0.0
        momentum_score = self._clip01(abs(momentum) / 1.25) if self._sign(momentum) == direction else 0.0
        trend_score = 0.70 * trend_strength + 0.30 * slope_score
        if trend_score < 0.50:
            return self._reject_signal(indicators, "Trend strength too weak", trend_score)
        extension = abs(price - ema) / atr
        maximum_extension = float(self._p("max_entry_extension_atr"))
        minimum_distance = float(self._p("min_atr_distance"))
        if extension > maximum_extension:
            return self._reject_signal(indicators, "Entry overextended", 0.0, extension_atr=extension)
        if (direction > 0 and price <= ema) or (direction < 0 and price >= ema):
            return self._reject_signal(indicators, "Price on wrong side of fast EMA", 0.0)
        geometry = self._clip01(1.0 - max(extension - minimum_distance, 0.0) /
                                max(maximum_extension - minimum_distance, 1e-12))
        components = {
            "confluence": self._clip01(agreement),
            "independent_groups": self._clip01(confirming / max(minimum_groups, 1)),
            "trend_strength": self._clip01(trend_score),
            "directional_movement": self._clip01(di_strength / 0.45),
            "momentum": momentum_score,
            "entry_geometry": geometry,
        }
        weights = self._p("confidence_weights")
        total_weight = sum(float(weights[key]) for key in components)
        if not math.isfinite(total_weight) or total_weight <= 0.0:
            return self._reject_signal(indicators, "Invalid score weights", 0.0)
        quality = self._clip01(sum(components[key] * float(weights[key]) for key in components) / total_weight)
        threshold = max(self._quality_floor(), float(self._p("min_directional_confidence")),
                        float(self._p("entry_quality_threshold")))
        meta = {
            "direction": side,
            "confirming_groups": confirming,
            "active_groups": groups,
            "agreement_ratio": agreement,
            "components": components,
            "quality_threshold": threshold,
            "groups_are_statistically_independent": False,
        }
        if quality < threshold:
            return self._reject_signal(indicators, f"Setup score {quality:.4f} below {threshold:.4f}", quality, **meta)
        meta.update({"accepted": True, "setup_quality": quality, "candidate_only": True})
        indicators["decision"] = meta
        return side, quality, f"{side} candidate; heuristic score={quality:.4f}", meta

    def _generate_signal(self, indicators: dict, regime: str, df: pd.DataFrame):
        return self._generate_signal_vectorized(indicators, regime, df)

    def _get_regime_alignment(self, regime: str, signal: str) -> float:
        r, s = str(regime or "").upper(), str(signal or "").upper()
        if r in ("TRENDING", "STRONG_TREND") and s in ("BUY", "SELL"):
            return 1.0
        return 1.0 if r == "RANGING" and s == "HOLD" else 0.0

    def _candidate_context(self, df: pd.DataFrame, prep: Dict[str, Any],
                           kwargs: Dict[str, Any], floor: float) -> Tuple[Optional[Dict[str, Any]], str]:
        attrs = df.attrs if isinstance(df.attrs, dict) else {}
        symbol_value = kwargs.get("symbol", attrs.get("symbol"))
        policy_value = kwargs.get("execution_policy_id", self._p("execution_policy_id", ""))
        if not isinstance(symbol_value, str) or not symbol_value.strip():
            return None, "Missing symbol; pass symbol or set DataFrame.attrs['symbol']"
        if not isinstance(policy_value, str) or not policy_value.strip():
            return None, "Missing execution_policy_id for the downstream order policy"
        decision = self._utc_datetime(kwargs.get("as_of"))
        if decision is None:
            return None, "Missing timezone-aware as_of decision timestamp"
        last_time = self._utc_datetime(prep.get("last_bar_time_utc"))
        if last_time is not None and decision < last_time:
            return None, "as_of precedes the last bar timestamp"
        bar_value = kwargs.get("bar_id")
        if bar_value is None:
            bar_value = prep.get("last_bar_time_utc")
        if bar_value is None or not str(bar_value).strip():
            return None, "Missing bar identity; supply bar_id or a timezone-aware candle timestamp"
        fingerprint = self._config_fingerprint(floor)
        digest = hashlib.sha256()
        for name in ("open", "high", "low", "close"):
            digest.update(np.ascontiguousarray(df[name].to_numpy(dtype=np.float64)).tobytes())
        return {
            "symbol": symbol_value.strip().upper(),
            "timeframe": self.timeframe,
            "execution_policy_id": policy_value.strip(),
            "as_of": decision.isoformat(),
            "bar_id": str(bar_value).strip(),
            "config_fingerprint": fingerprint,
            "quality_floor": float(floor),
            "input_fingerprint": digest.hexdigest(),
        }, ""

    def _register_candidate(self, context: Dict[str, Any], regime: str,
                            direction: str, score: float) -> Tuple[Optional[str], Optional[Dict[str, Any]], str]:
        identity = {
            "strategy": self.name,
            "version": self.VERSION,
            "symbol": context["symbol"],
            "timeframe": self.timeframe,
            "policy": context["execution_policy_id"],
            "config": context["config_fingerprint"],
            "bar_id": context["bar_id"],
        }
        encoded = json.dumps(identity, sort_keys=True, separators=(",", ":")).encode("utf-8")
        signal_id = f"{self.name}:{hashlib.sha256(encoded).hexdigest()[:32]}"
        with self._lock:
            if any(item.get("signal_id") == signal_id for item in self._trade_outcomes):
                return None, None, "Candidate already resolved; duplicate bar rejected"
            existing = self._pending_signals.get(signal_id)
            if existing is not None:
                if (existing.get("direction") != direction or existing.get("regime") != regime or
                        existing.get("input_fingerprint") != context["input_fingerprint"] or
                        not math.isclose(self._safe_float(existing.get("setup_quality"), -1.0), score,
                                         rel_tol=1e-12, abs_tol=1e-12)):
                    return None, None, "Candidate changed for the same bar; duplicate rejected"
                return signal_id, dict(existing), ""
            pending = {
                "signal_id": signal_id,
                "symbol": context["symbol"],
                "timeframe": self.timeframe,
                "execution_policy_id": context["execution_policy_id"],
                "config_fingerprint": context["config_fingerprint"],
                "input_fingerprint": context["input_fingerprint"],
                "bar_id": context["bar_id"],
                "decision_time": context["as_of"],
                "quality_floor": float(context["quality_floor"]),
                "regime": str(regime).upper(),
                "direction": str(direction).upper(),
                "setup_quality": float(score),
            }
            self._pending_signals[signal_id] = pending
            limit = int(self._p("max_pending_signals"))
            while len(self._pending_signals) > limit:
                oldest = next(iter(self._pending_signals))
                removed = self._pending_signals.pop(oldest)
                if isinstance(removed, dict) and not removed.get("legacy_unqualified"):
                    self._evidence_gaps.add(self._cohort_key(removed, removed.get("regime", ""), removed.get("direction", "")))
                self.logger.warning("[%s] evicted unresolved shadow candidate %s; its cohort is blocked", self.name, oldest)
            return signal_id, dict(pending), ""

    def _remember_pending_signal(self, signal_id: str, regime: str,
                                 direction: str, setup_quality: float) -> None:
        if not isinstance(signal_id, str) or not signal_id:
            return
        with self._lock:
            if signal_id in self._pending_signals:
                return
            self._pending_signals[signal_id] = {
                "signal_id": signal_id,
                "regime": str(regime).upper(),
                "direction": str(direction).upper(),
                "setup_quality": self._clip01(setup_quality),
                "legacy_unqualified": True,
            }
            limit = int(self._p("max_pending_signals"))
            while len(self._pending_signals) > limit:
                removed = self._pending_signals.pop(next(iter(self._pending_signals)))
                if isinstance(removed, dict) and not removed.get("legacy_unqualified"):
                    self._evidence_gaps.add(self._cohort_key(removed, removed.get("regime", ""), removed.get("direction", "")))

    def _build_result(
        self, *, signal: str, setup_quality: float, hold_quality: Optional[float],
        reason: str, price: float, regime: str, indicators: dict,
        is_analytical_hold: bool, start_time: float, note: str = "",
        decision_meta: Optional[dict] = None,
    ) -> dict:
        decision = dict(decision_meta) if isinstance(decision_meta, dict) else {}
        indicators = indicators if isinstance(indicators, dict) else {}
        requested = str(signal or "HOLD").upper().strip()
        raw_score = self._clip01(setup_quality)
        floor = self._quality_floor()
        calibration = decision.get("calibration")
        eligible = (
            requested in ("BUY", "SELL") and raw_score >= floor and
            isinstance(calibration, dict) and calibration.get("status") == "evidence_available" and
            isinstance(decision.get("shadow_signal_id"), str) and
            self._safe_int(indicators.get("active_count"), 0, 0) > 0
        )
        if eligible:
            with self._lock:
                pending = self._pending_signals.get(decision["shadow_signal_id"])
                if not isinstance(pending, dict) or pending.get("delivered") is True:
                    eligible = False
                    reason = "Directional candidate already delivered or no longer pending"
                    note = "duplicate_delivery_rejected"
                else:
                    pending["delivered"] = True
        final_signal = requested if eligible else "HOLD"
        confidence = raw_score if eligible else 0.0
        score = 50.0 + confidence * 50.0 if final_signal == "BUY" else 50.0 - confidence * 50.0 if final_signal == "SELL" else 50.0
        hq = None if eligible else min(0.35, self._clip01(hold_quality if hold_quality is not None else 0.30))
        signal_id = decision.get("shadow_signal_id") if eligible else None
        elapsed = max(0.0, (time.perf_counter() - start_time) * 1000.0)
        now = datetime.now(timezone.utc).isoformat()
        with self._lock:
            if eligible:
                old_count = self._safe_int(self._stats.get("total_signals"), 0, 0)
                old_average = self._safe_float(self._stats.get("avg_confidence"), 0.0)
                self._stats["total_signals"] = old_count + 1
                self._stats["avg_confidence"] = (old_average * old_count + confidence) / (old_count + 1)
            else:
                self._stats["rejected_signals"] = self._safe_int(self._stats.get("rejected_signals"), 0, 0) + 1
            self._stats["last_signal_time"] = now
            times = self._stats.setdefault("execution_times", [])
            times.append(elapsed)
            if len(times) > 500:
                del times[:-500]
        active = self._safe_int(indicators.get("active_count"), 0, 0) if eligible else 0
        metadata = {
            "regime": str(regime),
            "setup_quality": raw_score,
            "hold_quality": hq,
            "confidence_semantics": "Heuristic setup score, not a probability of profit or a calibrated per-trade win probability.",
            "confidence_type": "heuristic_setup_score",
            "combine_allowed": bool(eligible),
            "quality_floor": floor,
            "signal_id": signal_id,
            "shadow_signal_id": decision.get("shadow_signal_id"),
            "active_count": active,
            "buy_count": self._safe_int(indicators.get("buy_count"), 0, 0),
            "sell_count": self._safe_int(indicators.get("sell_count"), 0, 0),
            "buy_group_count": self._safe_int(indicators.get("buy_group_count"), 0, 0),
            "sell_group_count": self._safe_int(indicators.get("sell_group_count"), 0, 0),
            "independent_active_groups": self._safe_int(indicators.get("independent_active_groups"), 0, 0),
            "groups_are_statistically_independent": False,
            "agreement_ratio": self._clip01(indicators.get("agreement_ratio")),
            "dominance_ratio": self._clip01(indicators.get("dominance_ratio")),
            "agreement_raw": self._clip01(indicators.get("agreement_raw")),
            "group_summary": indicators.get("group_summary", {}),
            "indicators_summary": indicators.get("summary", {}),
            "context": indicators.get("context", {}),
            "decision": decision,
            "analysis_metadata": indicators.get("metadata", {}),
            "execution_time_ms": elapsed,
            "execution_note": str(note),
            "performance_multiplier": float(self._performance_multiplier),
            "performance_multiplier_affects_gate": False,
            "is_analytical_hold": not eligible,
            "version": self.VERSION,
        }
        return {
            "signal": final_signal,
            "confidence": float(confidence),
            "confidence_type": "heuristic_setup_score",
            "hold_quality": hq,
            "score": float(score),
            "reason": str(reason or "no reason recorded"),
            "strategy_name": self.name,
            "timestamp": now,
            "price": self._safe_float(price, 0.0),
            "signal_id": signal_id,
            "is_fallback": False,
            "error_type": "None",
            "metadata": metadata,
            "is_analytical_hold": not eligible,
            "active_count": active,
            "combine_allowed": bool(eligible),
            "quality_floor": floor,
            "raw_confidence": raw_score,
        }

    def _fallback_result(self, reason: str, error: Optional[Exception] = None,
                         price: float = 0.0, metadata: Optional[Dict[str, Any]] = None) -> dict:
        is_error = error is not None
        error_type = type(error).__name__ if is_error else "None"
        with self._lock:
            self._stats["fallback_count"] = self._safe_int(self._stats.get("fallback_count"), 0, 0) + 1
            if is_error:
                self._stats["error_count"] = self._safe_int(self._stats.get("error_count"), 0, 0) + 1
        meta = dict(metadata) if isinstance(metadata, dict) else {}
        meta.update({
            "regime": "UNKNOWN",
            "fallback_reason": str(reason),
            "version": self.VERSION,
            "combine_allowed": False,
            "confidence_semantics": "No directional confidence.",
            "error_type": error_type,
        })
        return {
            "signal": "HOLD", "confidence": 0.0, "confidence_type": "heuristic_setup_score",
            "hold_quality": 0.25 if is_error else 0.30,
            "score": 50.0, "reason": str(reason), "strategy_name": self.name,
            "timestamp": datetime.now(timezone.utc).isoformat(), "price": self._safe_float(price, 0.0),
            "signal_id": None, "metadata": meta, "is_fallback": is_error,
            "error_type": error_type, "is_analytical_hold": not is_error,
            "active_count": 0, "combine_allowed": False, "quality_floor": 0.80,
            "raw_confidence": 0.0,
        }

    def analyze_all(self, df: pd.DataFrame, regime: Optional[str] = None,
                    dna: Optional[dict] = None, **kwargs) -> dict:
        started = time.perf_counter()
        price = 0.0
        prep: Dict[str, Any] = {}
        with self._lock:
            try:
                if dna:
                    self.apply_dna_parameters(dna)
                valid, validation_reason, frame, price, prep = self._prepare_frame_for_analysis(df)
                if not valid or frame is None:
                    return self._fallback_result(f"Validation failed: {validation_reason}", price=price, metadata=prep)
                data_quality = self._calculate_data_quality_vectorized(frame)
                indicators = self._calculate_indicators_vectorized(frame)
                indicators.setdefault("metadata", {}).update(prep)
                indicators["metadata"]["data_quality"] = data_quality
                resolved_regime = (str(regime).upper().strip() if regime is not None
                                   else self._regime_from_context(indicators["context"]))
                if data_quality < float(self._p("min_data_quality")):
                    return self._build_result(signal="HOLD", setup_quality=0.0, hold_quality=0.30,
                                              reason="Data quality below configured minimum", price=price,
                                              regime=resolved_regime, indicators=indicators,
                                              is_analytical_hold=True, start_time=started, note="data_quality")
                side, quality, reason, meta = self._generate_signal_vectorized(indicators, resolved_regime, frame)
                meta = dict(meta)
                if side == "HOLD":
                    return self._build_result(signal="HOLD", setup_quality=quality, hold_quality=0.30,
                                              reason=reason, price=price, regime=resolved_regime,
                                              indicators=indicators, is_analytical_hold=True,
                                              start_time=started, note="heuristic_rejection", decision_meta=meta)
                floor = self._quality_floor()
                context, context_error = self._candidate_context(frame, prep, kwargs, floor)
                meta["shadow_candidate"] = {"direction": side, "setup_quality": quality}
                if context is None:
                    meta["calibration"] = {"status": "missing_context", "reason": context_error}
                    return self._build_result(signal="HOLD", setup_quality=quality, hold_quality=0.30,
                                              reason=context_error, price=price, regime=resolved_regime,
                                              indicators=indicators, is_analytical_hold=True,
                                              start_time=started, note="missing_evidence_context", decision_meta=meta)
                signal_id, pending, registration_error = self._register_candidate(context, resolved_regime, side, quality)
                if signal_id is None or pending is None:
                    meta["calibration"] = {"status": "duplicate_or_changed", "reason": registration_error}
                    return self._build_result(signal="HOLD", setup_quality=quality, hold_quality=0.30,
                                              reason=registration_error, price=price, regime=resolved_regime,
                                              indicators=indicators, is_analytical_hold=True,
                                              start_time=started, note="candidate_rejected", decision_meta=meta)
                evidence_context = dict(context)
                evidence_context["as_of"] = pending["decision_time"]
                calibration = self._get_calibration_estimate(resolved_regime, side, context=evidence_context)
                meta.update({
                    "shadow_signal_id": signal_id,
                    "calibration": calibration,
                    "symbol": context["symbol"],
                    "timeframe": self.timeframe,
                    "execution_policy_id": context["execution_policy_id"],
                    "decision_time": pending["decision_time"],
                    "config_fingerprint": context["config_fingerprint"],
                })
                if calibration["status"] != "evidence_available":
                    return self._build_result(signal="HOLD", setup_quality=quality, hold_quality=0.30,
                                              reason=f"Shadow evidence gate: {calibration['status']}",
                                              price=price, regime=resolved_regime, indicators=indicators,
                                              is_analytical_hold=True, start_time=started,
                                              note="shadow_evidence_gate", decision_meta=meta)
                return self._build_result(signal=side, setup_quality=quality, hold_quality=None,
                                          reason=reason, price=price, regime=resolved_regime,
                                          indicators=indicators, is_analytical_hold=False,
                                          start_time=started, note="heuristic_score_and_evidence_passed",
                                          decision_meta=meta)
            except Exception as exc:
                self.logger.error("[%s] analyze_all failed: %s", self.name, exc, exc_info=True)
                return self._fallback_result(f"Internal error: {type(exc).__name__}: {exc}",
                                             error=exc, price=price, metadata=prep)

    def record_trade_outcome(self, signal_id: str, outcome: dict) -> None:
        """Record one closed OOS shadow result for a known pending candidate.

        The caller must supply ``source='shadow_oos'``, ``out_of_sample=True``,
        ``is_closed=True``, a Boolean ``was_correct``, a timezone-aware
        ``closed_at``, and the matching ``symbol`` and ``execution_policy_id``.
        These are caller attestations, not independently verified provenance.
        """
        if not isinstance(signal_id, str) or not signal_id or not isinstance(outcome, dict):
            self.logger.warning("[%s] rejected invalid outcome input", self.name)
            return
        if outcome.get("source") != "shadow_oos" or outcome.get("out_of_sample") is not True:
            self.logger.warning("[%s] outcome %s lacks OOS shadow provenance", self.name, signal_id)
            return
        if outcome.get("is_closed") is not True or type(outcome.get("was_correct")) is not bool:
            self.logger.warning("[%s] outcome %s must be closed and use a Boolean label", self.name, signal_id)
            return
        closed = self._utc_datetime(outcome.get("closed_at"))
        if closed is None:
            self.logger.warning("[%s] outcome %s has no timezone-aware close time", self.name, signal_id)
            return
        should_flush = False
        with self._lock:
            pending = self._pending_signals.get(signal_id)
            if not isinstance(pending, dict) or pending.get("legacy_unqualified"):
                self.logger.warning("[%s] outcome %s has no qualified pending candidate", self.name, signal_id)
                return
            required_fields = ("symbol", "timeframe", "execution_policy_id", "config_fingerprint",
                               "input_fingerprint", "bar_id", "decision_time", "regime", "direction", "setup_quality")
            if any(key not in pending for key in required_fields):
                self.logger.error("[%s] pending candidate %s is incomplete", self.name, signal_id)
                return
            if any(isinstance(item, dict) and item.get("signal_id") == signal_id for item in self._trade_outcomes):
                self.logger.warning("[%s] duplicate outcome %s", self.name, signal_id)
                return
            decision = self._utc_datetime(pending.get("decision_time"))
            symbol = outcome.get("symbol")
            policy = outcome.get("execution_policy_id")
            if decision is None or closed <= decision:
                self.logger.warning("[%s] outcome %s closes no later than the decision", self.name, signal_id)
                return
            if not isinstance(symbol, str) or symbol.strip().upper() != pending.get("symbol"):
                self.logger.warning("[%s] outcome %s has a mismatching symbol", self.name, signal_id)
                return
            if not isinstance(policy, str) or policy.strip() != pending.get("execution_policy_id"):
                self.logger.warning("[%s] outcome %s has a mismatching execution policy", self.name, signal_id)
                return
            supplied_id = outcome.get("signal_id")
            if supplied_id is not None and supplied_id != signal_id:
                self.logger.warning("[%s] outcome signal_id mismatch", self.name)
                return
            pnl_value = outcome.get("pnl")
            pnl = self._safe_float(pnl_value, math.nan) if pnl_value is not None else None
            if pnl is not None and not math.isfinite(pnl):
                self.logger.warning("[%s] outcome %s has non-finite pnl", self.name, signal_id)
                return
            rec = {
                "signal_id": signal_id,
                "symbol": pending["symbol"],
                "timeframe": pending["timeframe"],
                "execution_policy_id": pending["execution_policy_id"],
                "config_fingerprint": pending["config_fingerprint"],
                "input_fingerprint": pending["input_fingerprint"],
                "bar_id": pending["bar_id"],
                "decision_time": pending["decision_time"],
                "closed_at": closed.isoformat(),
                "regime": pending["regime"],
                "direction": pending["direction"],
                "signal": pending["direction"],
                "setup_quality": float(pending["setup_quality"]),
                "source": "shadow_oos",
                "out_of_sample": True,
                "is_closed": True,
                "was_correct": outcome["was_correct"],
                "pnl": pnl,
                "duration": self._safe_float(outcome.get("duration"), 0.0),
                "max_drawdown": self._safe_float(outcome.get("max_drawdown"), 0.0),
                "timestamp": closed.isoformat(),
            }
            self._pending_signals.pop(signal_id)
            self._trade_outcomes.append(rec)
            self._learning_buffer.append(dict(rec))
            limit = int(self._p("max_outcome_history"))
            if len(self._trade_outcomes) > limit:
                del self._trade_outcomes[:-limit]
            if len(self._learning_buffer) > limit:
                self.logger.error("[%s] legacy learning buffer reached its limit; oldest queued rows removed", self.name)
                del self._learning_buffer[:-limit]
            self._stats["total_outcomes"] = self._safe_int(self._stats.get("total_outcomes"), 0, 0) + 1
            if rec["was_correct"]:
                self._stats["consecutive_losses"] = 0
            else:
                self._stats["consecutive_losses"] = self._safe_int(self._stats.get("consecutive_losses"), 0, 0) + 1
            wins = sum(1 for item in self._trade_outcomes if item.get("was_correct") is True)
            self._stats["win_rate"] = wins / len(self._trade_outcomes) if self._trade_outcomes else 0.0
            pnl_values = [item["pnl"] for item in self._trade_outcomes if item.get("pnl") is not None]
            if len(pnl_values) >= 2:
                pnl_array = np.asarray(pnl_values, dtype=np.float64)
                deviation = float(np.std(pnl_array))
                self._stats["sharpe_proxy"] = float(np.mean(pnl_array) / deviation) if deviation > 1e-12 else 0.0
            key = self._calibration_key(rec["regime"], rec["direction"])
            legacy = self._calibration.setdefault(key, {"wins": 0, "losses": 0})
            field_name = "wins" if rec["was_correct"] else "losses"
            legacy[field_name] = self._safe_int(legacy.get(field_name), 0, 0) + 1
            should_flush = self._p("persist_legacy_learning", False) is True and len(self._learning_buffer) >= int(self._p("flush_buffer_size"))
        if should_flush:
            self._flush_learning_buffer()

    def _flush_learning_buffer(self) -> None:
        if self._p("persist_legacy_learning", False) is not True:
            self.logger.info("[%s] legacy SQLite persistence disabled; retain/serialize strategy state explicitly", self.name)
            return
        with self._flush_lock:
            with self._lock:
                records = list(self._learning_buffer)
            written = []
            for rec in records:
                if not isinstance(rec, dict) or not rec.get("signal_id") or not rec.get("timestamp"):
                    self.logger.error("[%s] invalid queued legacy record; retained", self.name)
                    continue
                try:
                    result = safe_db_operation(
                        db_path="TRADE/strategy_stats.db",
                        query=(
                            "INSERT OR REPLACE INTO strategy_learning "
                            "(strategy_name, signal_id, pnl, was_correct, duration, max_drawdown, timestamp) "
                            "VALUES (?, ?, ?, ?, ?, ?, ?)"
                        ),
                        params=(self.name, rec["signal_id"], self._safe_float(rec.get("pnl"), 0.0),
                                1 if rec.get("was_correct") is True else 0,
                                self._safe_float(rec.get("duration"), 0.0),
                                self._safe_float(rec.get("max_drawdown"), 0.0), rec["timestamp"]),
                        operation_type="EXECUTE", max_retries=2, logger=self.logger,
                    )
                except Exception as exc:
                    self.logger.error("[%s] legacy SQLite write failed: %s", self.name, exc, exc_info=True)
                    continue
                if isinstance(result, dict) and result.get("ok") is True:
                    written.append(rec["signal_id"])
            if written:
                written_ids = set(written)
                with self._lock:
                    self._learning_buffer = [item for item in self._learning_buffer
                                             if item.get("signal_id") not in written_ids]
            if len(written) != len(records):
                self.logger.error("[%s] saved %d/%d legacy rows; unsuccessful rows retained", self.name, len(written), len(records))
            else:
                self.logger.info("[%s] saved %d legacy rows; this table is not a full calibration checkpoint", self.name, len(written))

    def get_dna_parameters(self) -> dict:
        keywords = ("period", "threshold", "distance", "extension", "mult", "factor", "sigma", "offset", "min_", "max_", "slope_")
        with self._lock:
            return {
                key: value for key, value in self.config.items()
                if not isinstance(value, bool) and isinstance(value, (int, float))
                and any(word in key.lower() for word in keywords)
            }

    def apply_dna_parameters(self, params: dict) -> None:
        if not isinstance(params, dict) or not params:
            return
        applied = 0
        with self._lock:
            for key, value in params.items():
                current = self.config.get(key)
                if isinstance(current, bool) or not isinstance(current, (int, float)):
                    continue
                numeric = self._safe_float(value, math.nan)
                if not math.isfinite(numeric):
                    continue
                self.config[key] = int(round(numeric)) if isinstance(current, int) else float(numeric)
                applied += 1
            self._sanitize_params()
            self.min_bars = self._required_bars()
        if applied:
            self.logger.info("[%s] applied %d DNA values; changed configurations require matching new evidence", self.name, applied)

    def get_performance_metadata(self) -> dict:
        with self._lock:
            return {
                "strategy_name": self.name,
                "strategy_type": self.category,
                "version": self.VERSION,
                "timeframe": self.timeframe,
                "total_signals": self._safe_int(self._stats.get("total_signals"), 0, 0),
                "total_outcomes": self._safe_int(self._stats.get("total_outcomes"), 0, 0),
                "win_rate": self._safe_float(self._stats.get("win_rate"), 0.0),
                "avg_confidence": self._safe_float(self._stats.get("avg_confidence"), 0.0),
                "last_signal_time": self._stats.get("last_signal_time"),
                "consecutive_losses": self._safe_int(self._stats.get("consecutive_losses"), 0, 0),
                "sharpe_proxy": self._safe_float(self._stats.get("sharpe_proxy"), 0.0),
                "performance_multiplier": float(self._performance_multiplier),
                "outcome_scope": "stored shadow outcomes, not necessarily live trades",
            }

    def get_stats(self) -> dict:
        with self._lock:
            return copy.deepcopy(self._stats)

    def reset_stats(self) -> None:
        with self._lock:
            self._stats = self._new_stats()
            self._trade_outcomes.clear()
            self._learning_buffer.clear()
            self._pending_signals.clear()
            self._evidence_gaps.clear()
            self._calibration.clear()
        self.logger.warning("[%s] statistics, pending candidates and evidence were reset", self.name)

    def to_dict(self) -> dict:
        with self._lock:
            return {
                "name": self.name,
                "version": self.VERSION,
                "params": copy.deepcopy(self.config),
                "stats": copy.deepcopy(self._stats),
                "timeframe": self.timeframe,
                "performance_multiplier": float(self._performance_multiplier),
                "calibration": copy.deepcopy(self._calibration),
                "shadow_outcomes": copy.deepcopy(self._trade_outcomes),
                "pending_signals": copy.deepcopy(self._pending_signals),
                "evidence_gaps": sorted(self._evidence_gaps),
                "learning_buffer": copy.deepcopy(self._learning_buffer),
                "last_snapshot": self._last_snapshot.to_dict() if self._last_snapshot else None,
            }

    @classmethod
    def from_dict(cls, data: dict) -> "AdvancedMovingAverages":
        payload = data if isinstance(data, dict) else {}
        params = payload.get("params") if isinstance(payload.get("params"), dict) else {}
        instance = cls(config=params, timeframe=payload.get("timeframe", "1H"))
        if payload.get("version") != cls.VERSION:
            instance.logger.warning("[%s] legacy or incompatible state: calibration evidence not restored", instance.name)
            return instance
        with instance._lock:
            stats = payload.get("stats")
            if isinstance(stats, dict):
                merged = instance._new_stats()
                merged.update(copy.deepcopy(stats))
                if not isinstance(merged.get("execution_times"), list):
                    merged["execution_times"] = []
                instance._stats = merged
            multiplier = instance._safe_float(payload.get("performance_multiplier"), 1.0)
            instance._performance_multiplier = multiplier if multiplier > 0.0 else 1.0
            outcomes = payload.get("shadow_outcomes")
            if isinstance(outcomes, list):
                instance._trade_outcomes = [copy.deepcopy(item) for item in outcomes[-int(instance._p("max_outcome_history")):] if isinstance(item, dict)]
            pending = payload.get("pending_signals")
            if isinstance(pending, dict):
                items = list(pending.items())[-int(instance._p("max_pending_signals")):]
                instance._pending_signals = {str(key): copy.deepcopy(value) for key, value in items if isinstance(value, dict)}
            gaps = payload.get("evidence_gaps")
            if isinstance(gaps, list):
                instance._evidence_gaps = {item for item in gaps if isinstance(item, str)}
            buffer = payload.get("learning_buffer")
            if isinstance(buffer, list):
                instance._learning_buffer = [copy.deepcopy(item) for item in buffer[-int(instance._p("max_outcome_history")):] if isinstance(item, dict)]
            calibration = payload.get("calibration")
            if isinstance(calibration, dict):
                instance._calibration = copy.deepcopy(calibration)
            snapshot = payload.get("last_snapshot")
            if isinstance(snapshot, dict):
                try:
                    instance._last_snapshot = PerformanceSnapshot.from_dict(snapshot)
                except (TypeError, ValueError, OverflowError) as exc:
                    instance.logger.warning("[%s] invalid performance snapshot: %s", instance.name, exc)
        return instance

    def self_test(self, sample_df: Optional[pd.DataFrame] = None) -> dict:
        results: Dict[str, Any] = {}
        try:
            base_test = getattr(super(), "self_test", None)
            if callable(base_test):
                base_result = base_test(sample_df)
                if isinstance(base_result, dict):
                    results.update({key: value for key, value in base_result.items()
                                    if key not in ("all_passed", "total_tests", "passed_tests")})
            if not isinstance(sample_df, pd.DataFrame) or len(sample_df) < self._required_bars():
                bars = max(300, self._required_bars() + 20)
                rng = np.random.default_rng(42)
                close = 100.0 + np.cumsum(rng.normal(0.02, 0.30, bars))
                open_price = close + rng.normal(0.0, 0.05, bars)
                high = np.maximum(open_price, close) + 0.15
                low = np.minimum(open_price, close) - 0.15
                sample_df = pd.DataFrame(
                    {"open": open_price, "high": high, "low": low, "close": close},
                    index=pd.date_range("2024-01-01", periods=bars, freq="1h", tz="UTC"),
                )
            valid, validation_reason, frame, price, prep = self._prepare_frame_for_analysis(sample_df)
            results["fast_validation"] = bool(valid and frame is not None and price > 0.0)
            results["fast_validation_reason"] = validation_reason
            results["prep_metadata"] = prep
            if valid and frame is not None:
                indicators = self._calculate_indicators_vectorized(frame)
                regime = self._regime_from_context(indicators["context"])
                side, confidence, reason, meta = self._generate_signal_vectorized(indicators, regime, frame)
                results["ma_calculation"] = (len(indicators.get("details", {})) == 9 and
                                             not indicators.get("metadata", {}).get("indicator_errors"))
                results["regime_detection"] = regime in ("STRONG_TREND", "TRENDING", "WEAK_TREND_OR_TRANSITION", "RANGING")
                results["signal_generation"] = side in ("BUY", "SELL", "HOLD") and isinstance(meta, dict)
                results["confidence_range"] = 0.0 <= float(confidence) <= 1.0
                results["data_quality"] = 0.0 <= self._calculate_data_quality_vectorized(frame) <= 1.0
                output = self.analyze_all(frame)
                results["analyze_all_contract"] = (isinstance(output, dict) and output.get("signal") == "HOLD"
                                                   and output.get("confidence") == 0.0
                                                   and output.get("combine_allowed") is False)
                results["sample_regime"] = regime
                results["sample_signal"] = side
                results["sample_signal_reason"] = reason
            else:
                for key in ("ma_calculation", "regime_detection", "signal_generation", "confidence_range",
                            "data_quality", "analyze_all_contract"):
                    results[key] = False
        except Exception as exc:
            self.logger.error("[%s] self-test failed: %s", self.name, exc, exc_info=True)
            results["self_test_error"] = str(exc)
            results["self_test_completed"] = False
        checks = [value for value in results.values() if isinstance(value, bool)]
        results["all_passed"] = bool(checks) and all(checks)
        results["total_tests"] = len(checks)
        results["passed_tests"] = sum(value is True for value in checks)
        return results

