#=====================================
class TechnicalAnalyzer:
    """
    Technical Analysis Utilities — Institutional Grade V4.0
    Single Source of Truth برای تمام نیازهای تحلیل تکنیکال استراتژی‌ها.

    V4.0 additions (پوشش کامل نیازهای تمام کلاس‌های استراتژی):
      • Wilder RMA / WMA / HMA / ZLEMA / TEMA / ALMA / McGinley / LSMA / T3 / KAMA
      • Williams %R / CCI / MFI / OBV / VWAP
      • Linreg endpoint / linear slope / percent rank
      • Rolling max/min/mean/std/sum (بدون pandas در مسیر اصلی)
      • Swing detection / equal-levels / pivot / fibonacci
      • Volume Profile POC / Cumulative Delta / Delta Volume / Volatility Regime
      • Candle patterns / Divergence detection
      • Alligator / AO / AC / Gator / Fractals (Bill Williams)
      • Chandelier stops / Trend strength / ADX component bundle
    """
    DEFAULT_PARAMS: Dict[str, Any] = {
        "rsi_period": 14, "macd_fast": 12, "macd_slow": 26, "macd_signal": 9,
        "atr_period": 14, "adx_period": 14, "stoch_period": 14,
        "williams_period": 14, "cci_period": 20, "mfi_period": 14,
        "bb_period": 20, "bb_std": 2.0,
        "rsi_oversold": 30, "rsi_overbought": 70,
        "rsi_clamp_min": 5.0, "rsi_clamp_max": 95.0,
        "flat_market_tolerance": 1e-8, "min_data_length": 10,
        # new
        "kama_period": 10, "kama_fast": 2, "kama_slow": 30,
        "hma_period": 20, "zlema_period": 20, "tema_period": 15,
        "alma_period": 21, "alma_sigma": 6.0, "alma_offset": 0.85,
        "mcginley_period": 14, "lsma_period": 25,
        "t3_period": 15, "t3_v_factor": 0.7,
        "chandelier_period": 22, "chandelier_mult": 3.0,
        "swing_order": 5, "pivot_lookback": 24,
        "volume_profile_bins": 24, "vol_lookback": 20,
    }

    def __init__(self, config: Optional[Dict[str, Any]] = None,
                 logger: Optional[logging.Logger] = logger):
        self.name = "TechnicalAnalyzer"
        self.category = "utility"
        self.logger = logger
        self.config = {**self.DEFAULT_PARAMS, **(config or {})}
        self._apply_config()
        self._lock = threading.Lock()
        self._stats = {"total_calls": 0, "fallback_used": 0,
                       "validation_fixes": 0, "type_conversions": 0}

    def _apply_config(self) -> None:
        p = self.config
        self.rsi_period = int(p.get("rsi_period", 14))
        self.macd_fast = int(p.get("macd_fast", 12))
        self.macd_slow = int(p.get("macd_slow", 26))
        self.macd_signal = int(p.get("macd_signal", 9))
        self.atr_period = int(p.get("atr_period", 14))
        self.adx_period = int(p.get("adx_period", 14))
        self.stoch_period = int(p.get("stoch_period", 14))
        self.williams_period = int(p.get("williams_period", 14))
        self.cci_period = int(p.get("cci_period", 20))
        self.mfi_period = int(p.get("mfi_period", 14))
        self.bb_period = int(p.get("bb_period", 20))
        self.bb_std = float(p.get("bb_std", 2.0))
        self.rsi_oversold = int(p.get("rsi_oversold", 30))
        self.rsi_overbought = int(p.get("rsi_overbought", 70))
        self.rsi_clamp_min = float(p.get("rsi_clamp_min", 5.0))
        self.rsi_clamp_max = float(p.get("rsi_clamp_max", 95.0))
        self.flat_tolerance = float(p.get("flat_market_tolerance", 1e-8))
        self.min_data_length = int(p.get("min_data_length", 10))
        self.kama_period = int(p.get("kama_period", 10))
        self.kama_fast = int(p.get("kama_fast", 2))
        self.kama_slow = int(p.get("kama_slow", 30))
        self.hma_period = int(p.get("hma_period", 20))
        self.zlema_period = int(p.get("zlema_period", 20))
        self.tema_period = int(p.get("tema_period", 15))
        self.alma_period = int(p.get("alma_period", 21))
        self.alma_sigma = float(p.get("alma_sigma", 6.0))
        self.alma_offset = float(p.get("alma_offset", 0.85))
        self.mcginley_period = int(p.get("mcginley_period", 14))
        self.lsma_period = int(p.get("lsma_period", 25))
        self.t3_period = int(p.get("t3_period", 15))
        self.t3_v_factor = float(p.get("t3_v_factor", 0.7))
        self.chandelier_period = int(p.get("chandelier_period", 22))
        self.chandelier_mult = float(p.get("chandelier_mult", 3.0))
        self.swing_order = int(p.get("swing_order", 5))
        self.pivot_lookback = int(p.get("pivot_lookback", 24))
        self.volume_profile_bins = int(p.get("volume_profile_bins", 24))
        self.vol_lookback = int(p.get("vol_lookback", 20))

    def _bump(self, key: str, amount: int = 1) -> None:
        with self._lock:
            self._stats[key] = int(self._stats.get(key, 0)) + amount

    def _fallback_array(self, n: int, value: float) -> np.ndarray:
        n = n if n > 0 else max(self.min_data_length, 10)
        return np.full(n, value, dtype=np.float64)

    def _normalize_input(self, data: Any, name: str = "data",
                        min_length: Optional[int] = None) -> np.ndarray:
        if data is None:
            return np.empty(0, dtype=np.float64)
        if isinstance(data, (int, float, bool, np.integer, np.floating)):
            v = float(data)
            return np.array([v if math.isfinite(v) else 0.0], dtype=np.float64)
        try:
            arr = np.asarray(data, dtype=np.float64)
            if arr.ndim != 1:
                arr = arr.ravel()
            arr = arr.copy()
        except (TypeError, ValueError):
            return np.empty(0, dtype=np.float64)
        if len(arr) and (np.isnan(arr).any() or np.isinf(arr).any()):
            try:
                arr = _fast_fillna_1d(arr)
            except Exception:
                arr = np.nan_to_num(arr, nan=0.0, posinf=0.0, neginf=0.0)
            self._bump("validation_fixes", 1)
        if len(arr) and "volume" in name.lower() and (arr < 0.0).any():
            arr[arr < 0.0] = 0.0
        return arr

    def calculate_jma(self, close: Any, period: Optional[int] = None,
                      fast: Optional[int] = None,
                      slow: Optional[int] = None) -> np.ndarray:
        """
        JMA-style adaptive moving average.

        فرمول دقیقاً همان Kaufman Efficiency-Ratio Smoothing است که در
        AdvancedMovingAverages._calc_jma_vectorized به‌صورت دستی تکرار شده بود.
        این متد به‌عنوان canonical جایگزین آن پیاده‌سازی محلی است.
        """
        try:
            p = max(2, int(period or self.kama_period))
            f = max(1, int(fast or self.kama_fast))
            s = max(f + 1, int(slow or self.kama_slow))
            return self.calculate_kama(close, p, f, s)
        except Exception as e:
            self.logger.error(f"[{self.name}_JMA] {e}")
            return self._fallback_array(len(close) if close is not None else 0, 0.0)
            
    def calculate_rsi(self, close: Any, period: Optional[int] = None) -> np.ndarray:
        period = int(period or self.rsi_period)
        try:
            c = self._normalize_input(close, "close")
            n = len(c)
            if n == 0:
                self._bump("fallback_used")
                return self._fallback_array(0, 50.0)
            if n < period + 1:
                self._bump("fallback_used")
                return self._fallback_array(n, 50.0)
            rsi = _fast_rsi_1d(np.ascontiguousarray(c), period)
            rsi = np.clip(np.nan_to_num(rsi, nan=50.0,
                                        posinf=self.rsi_clamp_max,
                                        neginf=self.rsi_clamp_min),
                          self.rsi_clamp_min, self.rsi_clamp_max)
            self._bump("total_calls")
            return rsi
        except Exception as e:
            self.logger.error(f"[{self.name}_RSI] {e}")
            self._bump("fallback_used")
            return self._fallback_array(len(close) if close is not None else 0, 50.0)

    def calculate_rsi_value(self, close: Any, period: Optional[int] = None) -> float:
        arr = self.calculate_rsi(close, period)
        return float(arr[-1]) if len(arr) else 50.0

    def calculate_macd(self, close: Any, fast: Optional[int] = None,
                       slow: Optional[int] = None,
                       signal_p: Optional[int] = None
                       ) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        fast = int(fast or self.macd_fast)
        slow = int(slow or self.macd_slow)
        signal_p = int(signal_p or self.macd_signal)
        if fast >= slow:
            fast, slow = min(fast, slow), max(fast, slow)
        try:
            c = self._normalize_input(close, "close")
            n = len(c)
            if n == 0:
                self._bump("fallback_used")
                fb = self._fallback_array(0, 0.0)
                return fb, fb.copy(), fb.copy()
            if n == 1:
                z = self._fallback_array(1, 0.0)
                return z, z.copy(), z.copy()
            ef = _fast_ema_1d(c, fast)
            es = _fast_ema_1d(c, slow)
            macd_line = ef - es
            sig_line = _fast_ema_1d(macd_line, signal_p)
            hist = macd_line - sig_line
            self._bump("total_calls")
            return (np.nan_to_num(macd_line, nan=0.0),
                    np.nan_to_num(sig_line, nan=0.0),
                    np.nan_to_num(hist, nan=0.0))
        except Exception as e:
            self.logger.error(f"[{self.name}_MACD] {e}")
            self._bump("fallback_used")
            ln = len(close) if close is not None else 0
            fb = self._fallback_array(ln, 0.0)
            return fb, fb.copy(), fb.copy()

    def calculate_macd_value(self, close: Any) -> Tuple[float, float, float]:
        m, s, h = self.calculate_macd(close)
        return (float(m[-1]) if len(m) else 0.0,
                float(s[-1]) if len(s) else 0.0,
                float(h[-1]) if len(h) else 0.0)

    def calculate_atr(self, high: Any, low: Any, close: Any,
                      period: Optional[int] = None) -> np.ndarray:
        period = int(period or self.atr_period)
        try:
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            n = min(len(h), len(l), len(c))
            if n == 0:
                self._bump("fallback_used")
                return self._fallback_array(max(len(c), 1), 0.005)
            h_c = np.ascontiguousarray(h[:n])
            l_c = np.ascontiguousarray(l[:n])
            c_c = np.ascontiguousarray(c[:n])
            atr = _fast_atr_1d(h_c, l_c, c_c, period)
            atr = np.nan_to_num(atr, nan=0.005, posinf=0.005, neginf=0.005)
            self._bump("total_calls")
            return atr
        except Exception as e:
            self.logger.error(f"[{self.name}_ATR] {e}")
            self._bump("fallback_used")
            return self._fallback_array(len(close) if close is not None else 0, 0.005)

    def calculate_atr_value(self, high: Any, low: Any, close: Any,
                            period: Optional[int] = None) -> float:
        arr = self.calculate_atr(high, low, close, period)
        return float(arr[-1]) if len(arr) else 0.0

    def calculate_adx(self, high: Any, low: Any, close: Any,
                      period: Optional[int] = None) -> np.ndarray:
        period = int(period or self.adx_period)
        try:
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            n = min(len(h), len(l), len(c))
            if n == 0:
                self._bump("fallback_used")
                return self._fallback_array(max(len(c), 1), 20.0)
            adx, _, _ = _fast_adx_di_1d(np.ascontiguousarray(h[:n]),
                                        np.ascontiguousarray(l[:n]),
                                        np.ascontiguousarray(c[:n]), period)
            adx = np.clip(np.nan_to_num(adx, nan=20.0, posinf=100.0, neginf=0.0),
                          0.0, 100.0)
            self._bump("total_calls")
            return adx
        except Exception as e:
            self.logger.error(f"[{self.name}_ADX] {e}")
            self._bump("fallback_used")
            return self._fallback_array(len(close) if close is not None else 0, 20.0)

    def calculate_adx_value(self, high: Any, low: Any, close: Any,
                            period: Optional[int] = None) -> float:
        arr = self.calculate_adx(high, low, close, period)
        return float(arr[-1]) if len(arr) else 0.0

    def calculate_adx_di_bundle(self, high: Any, low: Any, close: Any,
                                period: Optional[int] = None
                                ) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        """(ADX, +DI, -DI) — منبع واحد برای همهٔ مصرف‌کنندگان trend."""
        period = int(period or self.adx_period)
        try:
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            n = min(len(h), len(l), len(c))
            if n < period * 2:
                z = self._fallback_array(n, 0.0)
                return z, z.copy(), z.copy()
            adx, pdi, mdi = _fast_adx_di_1d(
                np.ascontiguousarray(h[:n]),
                np.ascontiguousarray(l[:n]),
                np.ascontiguousarray(c[:n]), period)
            return (np.nan_to_num(adx, nan=0.0),
                    np.nan_to_num(pdi, nan=0.0),
                    np.nan_to_num(mdi, nan=0.0))
        except Exception as e:
            self.logger.error(f"[{self.name}_ADX_BUNDLE] {e}")
            z = self._fallback_array(len(close) if close is not None else 0, 0.0)
            return z, z.copy(), z.copy()

    def calculate_bollinger_bands(self, close: Any, period: Optional[int] = None,
                                  std_mult: Optional[float] = None
                                  ) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        period = int(period or self.bb_period)
        std_mult = float(std_mult or self.bb_std)
        try:
            c = self._normalize_input(close, "close")
            n = len(c)
            if n == 0:
                self._bump("fallback_used")
                fb = self._fallback_array(0, 0.0)
                return fb, fb.copy(), fb.copy()
            period = max(2, min(period, n)) if n >= 2 else 2
            s = pd.Series(c)
            mid = s.rolling(period, min_periods=1).mean().to_numpy()
            std = s.rolling(period, min_periods=1).std(ddof=1).to_numpy()
            std = np.nan_to_num(std, nan=0.0)
            fb_val = float(c[-1]) if n else 0.0
            up = np.nan_to_num(mid + std_mult * std, nan=fb_val)
            lo = np.nan_to_num(mid - std_mult * std, nan=fb_val)
            mid = np.nan_to_num(mid, nan=fb_val)
            self._bump("total_calls")
            return up, mid, lo
        except Exception as e:
            self.logger.error(f"[{self.name}_BB] {e}")
            self._bump("fallback_used")
            ln = len(close) if close is not None else 0
            fb = self._fallback_array(ln, 0.0)
            return fb, fb.copy(), fb.copy()

    def calculate_hurst(self, close: Any, lags: Optional[Any] = None) -> float:
        """محاسبهٔ نمای هورست با R/S — هم مسیر Numba و هم fallback اصلاح شد."""
        try:
            c = self._normalize_input(close, "close")
            if len(c) < 40:
                return 0.5
            returns = np.diff(np.log(np.maximum(c, 1e-12)))
            returns = np.ascontiguousarray(returns[np.isfinite(returns)], dtype=np.float64)
            if returns.size < 40:
                return 0.5
            if lags is None:
                n = len(returns)
                candidates = {n // d for d in (8, 4, 2, 1) if n // d >= 4}
                lags_array = np.asarray(sorted(candidates), dtype=np.int64)
            else:
                lags_array = np.asarray(lags, dtype=np.int64).ravel()
            if lags_array.size < 2:
                return 0.5

            if NUMBA_AVAILABLE and _KERNELS_READY:
                try:
                    value = float(_compute_hurst_numba(returns, lags_array))
                    if math.isfinite(value):
                        return float(np.clip(value, 0.0, 1.0))
                except Exception as kernel_exc:
                    self.logger.debug(
                        "[%s_HURST] numba kernel unavailable; using Python fallback: %s",
                        self.name, kernel_exc,
                    )

            log_lags: List[float] = []
            log_rs: List[float] = []
            for lag in lags_array:
                lag_int = int(lag)
                if lag_int < 4 or lag_int > len(returns):
                    continue
                rs_values: List[float] = []
                for start in range(0, len(returns) - lag_int + 1, lag_int):
                    chunk = returns[start:start + lag_int]
                    if len(chunk) < 4:
                        continue
                    mean_c = float(np.mean(chunk))
                    dev = np.cumsum(chunk - mean_c)
                    r_val = float(np.max(dev) - np.min(dev))
                    s_val = float(np.std(chunk, ddof=1))
                    if s_val > 1e-10 and r_val / s_val > 1e-10:
                        rs_values.append(r_val / s_val)
                if rs_values:
                    log_lags.append(math.log(float(lag_int)))
                    log_rs.append(math.log(max(float(np.mean(rs_values)), 1e-10)))
            if len(log_lags) < 2:
                return 0.5
            x = np.asarray(log_lags, dtype=np.float64)
            y = np.asarray(log_rs, dtype=np.float64)
            xc = x - x.mean()
            denominator = float(np.dot(xc, xc))
            if denominator < 1e-12:
                return 0.5
            slope = float(np.dot(xc, y - y.mean()) / denominator)
            return float(np.clip(slope, 0.0, 1.0))
        except Exception as e:
            self.logger.error("[%s_HURST] %s", self.name, e)
            return 0.5
   
    def calculate_sma(self, data: Any, period: int) -> np.ndarray:
        try:
            period = max(1, int(period))
            arr = self._normalize_input(data, "data")
            if len(arr) == 0:
                return np.empty(0, dtype=np.float64)
            return _fast_sma_1d(np.ascontiguousarray(arr), period)
        except Exception as e:
            self.logger.error(f"[{self.name}_SMA] {e}")
            return np.empty(0, dtype=np.float64)

    def calculate_ema(self, data: Any, period: int) -> np.ndarray:
        try:
            period = max(2, int(period))
            arr = self._normalize_input(data, "data")
            if len(arr) == 0:
                return np.empty(0, dtype=np.float64)
            return _fast_ema_1d(np.ascontiguousarray(arr), period)
        except Exception as e:
            self.logger.error(f"[{self.name}_EMA] {e}")
            return np.empty(0, dtype=np.float64)

    def calculate_rma(self, data: Any, period: int) -> np.ndarray:
        """Wilder RMA (alpha = 1/period)."""
        try:
            period = max(2, int(period))
            arr = self._normalize_input(data, "data")
            if len(arr) == 0:
                return np.empty(0, dtype=np.float64)
            return _fast_rma_1d(np.ascontiguousarray(arr), period)
        except Exception as e:
            self.logger.error(f"[{self.name}_RMA] {e}")
            return np.empty(0, dtype=np.float64)

    def calculate_wma(self, data: Any, period: int) -> np.ndarray:
        """Weighted Moving Average (linear weights 1..period)."""
        try:
            arr = self._normalize_input(data, "data")
            n = len(arr)
            p = max(1, int(period))
            out = np.full(n, np.nan, dtype=np.float64)
            if n < p:
                return out
            w = np.arange(1, p + 1, dtype=np.float64)
            w = w / w.sum()
            finite = np.isfinite(arr)
            clean = np.where(finite, arr, 0.0)
            conv = np.correlate(clean, w, mode="valid")
            if not finite.all():
                cnt = np.correlate(finite.astype(np.float64),
                                   np.ones(p, dtype=np.float64), mode="valid")
                conv = np.where(cnt >= p, conv, np.nan)
            out[p - 1:] = conv
            return out
        except Exception as e:
            self.logger.error(f"[{self.name}_WMA] {e}")
            return np.empty(0, dtype=np.float64)

    # ═══════════════════════════════════════════════════════════════════
    # Advanced MAs: HMA / ZLEMA / TEMA / ALMA / McGinley / LSMA / T3 / KAMA
    # ═══════════════════════════════════════════════════════════════════
    def calculate_hma(self, close: Any, period: Optional[int] = None) -> np.ndarray:
        try:
            p = max(4, int(period or self.hma_period))
            c = self._normalize_input(close, "close")
            n = len(c)
            if n < 4 or p < 4:
                return np.full(n, c[-1] if n else 0.0, dtype=np.float64)
            half = max(2, p // 2)
            sq = max(2, int(math.sqrt(p)))
            wma_half = self.calculate_wma(c, half)
            wma_full = self.calculate_wma(c, p)
            raw = 2.0 * wma_half - wma_full
            hma = self.calculate_wma(raw, sq)
            return np.nan_to_num(hma, nan=c[-1] if n else 0.0)
        except Exception as e:
            self.logger.error(f"[{self.name}_HMA] {e}")
            return self._fallback_array(len(close) if close is not None else 0, 0.0)

    def calculate_zlema(self, close: Any, period: Optional[int] = None) -> np.ndarray:
        try:
            p = max(2, int(period or self.zlema_period))
            c = self._normalize_input(close, "close")
            n = len(c)
            if n < 3:
                return np.full(n, c[-1] if n else 0.0, dtype=np.float64)
            lag = max(1, (p - 1) // 2)
            shifted = np.empty_like(c)
            shifted[:lag] = c[0]
            shifted[lag:] = c[:-lag]
            data = 2.0 * c - shifted
            return self.calculate_ema(data, p)
        except Exception as e:
            self.logger.error(f"[{self.name}_ZLEMA] {e}")
            return self._fallback_array(len(close) if close is not None else 0, 0.0)

    def calculate_tema(self, close: Any, period: Optional[int] = None) -> np.ndarray:
        try:
            p = max(2, int(period or self.tema_period))
            c = self._normalize_input(close, "close")
            e1 = self.calculate_ema(c, p)
            e2 = self.calculate_ema(e1, p)
            e3 = self.calculate_ema(e2, p)
            return 3.0 * e1 - 3.0 * e2 + e3
        except Exception as e:
            self.logger.error(f"[{self.name}_TEMA] {e}")
            return self._fallback_array(len(close) if close is not None else 0, 0.0)

    def calculate_alma(self, close: Any, period: Optional[int] = None,
                       sigma: Optional[float] = None,
                       offset: Optional[float] = None) -> np.ndarray:
        try:
            p = max(2, int(period or self.alma_period))
            sg = max(1e-6, float(sigma or self.alma_sigma))
            off = float(np.clip(offset if offset is not None else self.alma_offset, 0.0, 1.0))
            c = self._normalize_input(close, "close")
            n = len(c)
            if n < p:
                return np.full(n, c[-1] if n else 0.0, dtype=np.float64)
            center = off * (p - 1)
            scale = p / sg
            idx = np.arange(p, dtype=np.float64)
            w = np.exp(-((idx - center) ** 2) / (2.0 * scale * scale))
            w = w / w.sum()
            out = np.full(n, np.nan, dtype=np.float64)
            finite = np.isfinite(c)
            clean = np.where(finite, c, 0.0)
            conv = np.correlate(clean, w, mode="valid")
            if not finite.all():
                cnt = np.correlate(finite.astype(np.float64),
                                   np.ones(p, dtype=np.float64), mode="valid")
                conv = np.where(cnt >= p, conv, np.nan)
            out[p - 1:] = conv
            return np.nan_to_num(out, nan=c[-1] if n else 0.0)
        except Exception as e:
            self.logger.error(f"[{self.name}_ALMA] {e}")
            return self._fallback_array(len(close) if close is not None else 0, 0.0)

    def calculate_mcginley(self, close: Any, period: Optional[int] = None) -> np.ndarray:
        try:
            p = max(2, int(period or self.mcginley_period))
            c = self._normalize_input(close, "close")
            n = len(c)
            if n < 3:
                return np.full(n, c[-1] if n else 0.0, dtype=np.float64)
            out = np.empty(n, dtype=np.float64)
            out[0] = c[0]
            for i in range(1, n):
                prev = max(abs(float(out[i - 1])), 1e-10)
                ratio = float(np.clip(float(c[i]) / prev, 0.5, 2.0))
                denom = max(float(p) * (ratio ** 4), 1e-8)
                out[i] = out[i - 1] + (float(c[i]) - out[i - 1]) / denom
            return out
        except Exception as e:
            self.logger.error(f"[{self.name}_MCGINLEY] {e}")
            return self._fallback_array(len(close) if close is not None else 0, 0.0)

    def calculate_lsma(self, close: Any, period: Optional[int] = None) -> np.ndarray:
        try:
            p = max(2, int(period or self.lsma_period))
            c = self._normalize_input(close, "close")
            n = len(c)
            if n < p:
                return np.full(n, c[-1] if n else 0.0, dtype=np.float64)
            x = np.arange(p, dtype=np.float64)
            xc = x - x.mean()
            xvar = float(np.dot(xc, xc))
            if xvar < 1e-12:
                return np.full(n, c[-1], dtype=np.float64)
            finite = np.isfinite(c)
            clean = np.where(finite, c, 0.0)
            mean_y = np.correlate(clean, np.ones(p, dtype=np.float64) / p, mode="valid")
            slope_num = np.correlate(clean, xc, mode="valid")
            slopes = slope_num / xvar
            endpoint = mean_y + slopes * xc[-1]
            if not finite.all():
                cnt = np.correlate(finite.astype(np.float64),
                                   np.ones(p, dtype=np.float64), mode="valid")
                endpoint = np.where(cnt >= p, endpoint, np.nan)
            out = np.full(n, np.nan, dtype=np.float64)
            out[p - 1:] = endpoint
            return np.nan_to_num(out, nan=c[-1] if n else 0.0)
        except Exception as e:
            self.logger.error(f"[{self.name}_LSMA] {e}")
            return self._fallback_array(len(close) if close is not None else 0, 0.0)

    def calculate_t3(self, close: Any, period: Optional[int] = None,
                     v_factor: Optional[float] = None) -> np.ndarray:
        try:
            p = max(2, int(period or self.t3_period))
            v = float(np.clip(v_factor if v_factor is not None else self.t3_v_factor, 0.0, 1.0))
            c = self._normalize_input(close, "close")
            e1 = self.calculate_ema(c, p)
            e2 = self.calculate_ema(e1, p)
            e3 = self.calculate_ema(e2, p)
            e4 = self.calculate_ema(e3, p)
            e5 = self.calculate_ema(e4, p)
            e6 = self.calculate_ema(e5, p)
            c1 = -(v ** 3)
            c2 = 3.0 * (v ** 2) * (1.0 + v)
            c3 = -3.0 * v * ((1.0 + v) ** 2)
            c4 = (1.0 + v) ** 3
            return c1 * e6 + c2 * e5 + c3 * e4 + c4 * e3
        except Exception as e:
            self.logger.error(f"[{self.name}_T3] {e}")
            return self._fallback_array(len(close) if close is not None else 0, 0.0)

    def calculate_kama(self, close: Any, period: Optional[int] = None,
                       fast: Optional[int] = None, slow: Optional[int] = None
                       ) -> np.ndarray:
        try:
            p = max(2, int(period or self.kama_period))
            f = max(1, int(fast or self.kama_fast))
            s = max(f + 1, int(slow or self.kama_slow))
            c = self._normalize_input(close, "close")
            if len(c) == 0:
                return np.empty(0, dtype=np.float64)
            try:
                return _compute_kama_numba(np.ascontiguousarray(c), p, f, s)
            except Exception:
                pass
            n = len(c)
            out = np.empty(n, dtype=np.float64)
            out[0] = c[0]
            if n <= p:
                out[:] = c
                return out
            out[:p] = c[:p]
            fsc = 2.0 / (f + 1.0)
            ssc = 2.0 / (s + 1.0)
            for i in range(p, n):
                direction = abs(c[i] - c[i - p])
                volatility = float(np.sum(np.abs(np.diff(c[i - p:i + 1]))))
                er = direction / volatility if volatility > 1e-12 else 0.0
                sc = (er * (fsc - ssc) + ssc) ** 2
                out[i] = out[i - 1] + sc * (c[i] - out[i - 1])
            return out
        except Exception as e:
            self.logger.error(f"[{self.name}_KAMA] {e}")
            return self._fallback_array(len(close) if close is not None else 0, 0.0)

    def calculate_chandelier_stops(self, high: Any, low: Any, close: Any,
                                   period: Optional[int] = None,
                                   mult: Optional[float] = None
                                   ) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        """(long_stop, short_stop, direction[+1/-1]) با مدل stateful."""
        try:
            p = max(3, int(period or self.chandelier_period))
            m = max(0.1, float(mult or self.chandelier_mult))
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            n = min(len(h), len(l), len(c))
            if n < p:
                z = self._fallback_array(n, 0.0)
                return z, z.copy(), z.copy()
            h, l, c = h[:n], l[:n], c[:n]
            atr = self.calculate_atr(h, l, c, p)
            roll_high = self.calculate_rolling_max(h, p)
            roll_low = self.calculate_rolling_min(l, p)
            raw_long = roll_high - atr * m
            raw_short = roll_low + atr * m
            long_stop = raw_long.copy()
            short_stop = raw_short.copy()
            direction = np.zeros(n, dtype=np.int8)
            start = p - 1
            if start >= n or not (np.isfinite(raw_long[start]) and np.isfinite(raw_short[start])):
                z = self._fallback_array(n, 0.0)
                return z, z.copy(), direction.astype(np.float64)
            mid = (float(raw_long[start]) + float(raw_short[start])) * 0.5
            direction[start] = 1 if float(c[start]) >= mid else -1
            for i in range(start + 1, n):
                prev = i - 1
                if not (np.isfinite(raw_long[i]) and np.isfinite(raw_short[i])):
                    long_stop[i] = long_stop[prev]
                    short_stop[i] = short_stop[prev]
                    direction[i] = direction[prev]
                    continue
                if np.isfinite(long_stop[prev]) and c[prev] > long_stop[prev]:
                    long_stop[i] = max(raw_long[i], long_stop[prev])
                else:
                    long_stop[i] = raw_long[i]
                if np.isfinite(short_stop[prev]) and c[prev] < short_stop[prev]:
                    short_stop[i] = min(raw_short[i], short_stop[prev])
                else:
                    short_stop[i] = raw_short[i]
                pd_ = int(direction[prev]) if direction[prev] != 0 else 1
                if np.isfinite(short_stop[prev]) and c[i] > short_stop[prev]:
                    direction[i] = 1
                elif np.isfinite(long_stop[prev]) and c[i] < long_stop[prev]:
                    direction[i] = -1
                else:
                    direction[i] = pd_
            return long_stop, short_stop, direction.astype(np.float64)
        except Exception as e:
            self.logger.error(f"[{self.name}_CHANDELIER] {e}")
            z = self._fallback_array(len(close) if close is not None else 0, 0.0)
            return z, z.copy(), z.copy()

    # ═══════════════════════════════════════════════════════════════════
    # Williams %R / CCI / MFI / OBV / VWAP
    # ═══════════════════════════════════════════════════════════════════

    def calculate_williams_r_value(self, high: Any, low: Any, close: Any,
                                   period: Optional[int] = None) -> float:
        arr = self.calculate_williams_r(high, low, close, period)
        return float(arr[-1]) if len(arr) else -50.0

    def calculate_cci_value(self, high: Any, low: Any, close: Any,
                            period: Optional[int] = None) -> float:
        arr = self.calculate_cci(high, low, close, period)
        return float(arr[-1]) if len(arr) else 0.0

    def calculate_mfi(self, high: Any, low: Any, close: Any, volume: Any,
                      period: Optional[int] = None) -> np.ndarray:
        try:
            p = max(2, int(period or self.mfi_period))
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            v = self._normalize_input(volume, "volume")
            n = min(len(h), len(l), len(c), len(v))
            if n < p + 1:
                return self._fallback_array(n, 50.0)
            h, l, c, v = h[:n], l[:n], c[:n], v[:n]
            tp = (h + l + c) / 3.0
            rmf = tp * v
            d = np.diff(tp, prepend=tp[0])
            pos = np.where(d > 0, rmf, 0.0)
            neg = np.where(d < 0, rmf, 0.0)
            cp = np.concatenate(([0.0], np.cumsum(pos)))
            cn = np.concatenate(([0.0], np.cumsum(neg)))
            idx = np.arange(n)
            lo = np.maximum(idx - p + 1, 0)
            pos_s = cp[idx + 1] - cp[lo]
            neg_s = cn[idx + 1] - cn[lo]
            mfr = pos_s / (neg_s + 1e-12)
            mfi = 100.0 - (100.0 / (1.0 + mfr))
            return np.nan_to_num(np.clip(mfi, 0.0, 100.0), nan=50.0)
        except Exception as e:
            self.logger.error(f"[{self.name}_MFI] {e}")
            return self._fallback_array(len(close) if close is not None else 0, 50.0)

    def calculate_mfi_value(self, high: Any, low: Any, close: Any, volume: Any,
                            period: Optional[int] = None) -> float:
        arr = self.calculate_mfi(high, low, close, volume, period)
        return float(arr[-1]) if len(arr) else 50.0

    def calculate_obv(self, close: Any, volume: Any,
                      smoothing: Optional[int] = None) -> np.ndarray:
        try:
            c = self._normalize_input(close, "close")
            v = self._normalize_input(volume, "volume")
            n = min(len(c), len(v))
            if n == 0:
                return np.empty(0, dtype=np.float64)
            c, v = c[:n], v[:n]
            d = np.sign(np.diff(c, prepend=c[0]))
            obv = np.cumsum(d * v)
            if smoothing and int(smoothing) > 1:
                obv = self.calculate_ema(obv, int(smoothing))
            return obv
        except Exception as e:
            self.logger.error(f"[{self.name}_OBV] {e}")
            return self._fallback_array(len(close) if close is not None else 0, 0.0)

    def calculate_vwap(self, high: Any, low: Any, close: Any, volume: Any,
                       period: Optional[int] = None) -> np.ndarray:
        """Rolling VWAP — if period is None → cumulative VWAP."""
        try:
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            v = self._normalize_input(volume, "volume")
            n = min(len(h), len(l), len(c), len(v))
            if n == 0:
                return np.empty(0, dtype=np.float64)
            h, l, c, v = h[:n], l[:n], c[:n], v[:n]
            tp = (h + l + c) / 3.0
            if period is None or int(period) <= 0:
                cv = np.cumsum(tp * v)
                sv = np.cumsum(v)
                return np.where(sv > 1e-12, cv / np.maximum(sv, 1e-12), c)
            p = max(2, int(period))
            cv = np.cumsum(tp * v)
            sv = np.cumsum(v)
            cv_p = np.concatenate(([0.0], cv))
            sv_p = np.concatenate(([0.0], sv))
            idx = np.arange(n)
            lo = np.maximum(idx - p + 1, 0)
            num = cv_p[idx + 1] - cv_p[lo]
            den = sv_p[idx + 1] - sv_p[lo]
            return np.where(den > 1e-12, num / np.maximum(den, 1e-12), c)
        except Exception as e:
            self.logger.error(f"[{self.name}_VWAP] {e}")
            return self._fallback_array(len(close) if close is not None else 0, 0.0)

    def calculate_vwap_value(self, high: Any, low: Any, close: Any, volume: Any,
                             period: Optional[int] = None) -> float:
        arr = self.calculate_vwap(high, low, close, volume, period)
        return float(arr[-1]) if len(arr) else 0.0

    # ═══════════════════════════════════════════════════════════════════
    # Rolling statistics
    # ============================================================================
    # ============================================================================
    @staticmethod
    def calculate_rolling_max(arr: np.ndarray, period: int) -> np.ndarray:
        a = np.ascontiguousarray(arr, dtype=np.float64).ravel()
        n = a.size
        if n == 0:
            return np.array([], dtype=np.float64)
        p = max(1, int(period))
        if _NUMBA_AVAILABLE:
            hh, _ = _osc_rolling_max_min_1d(a, a, p)
            return hh
        return pd.Series(a).rolling(window=p, min_periods=1).max().to_numpy(dtype=np.float64)

    @staticmethod
    def calculate_rolling_min(arr: np.ndarray, period: int) -> np.ndarray:
        a = np.ascontiguousarray(arr, dtype=np.float64).ravel()
        n = a.size
        if n == 0:
            return np.array([], dtype=np.float64)
        p = max(1, int(period))
        if _NUMBA_AVAILABLE:
            _, ll = _osc_rolling_max_min_1d(a, a, p)
            return ll
        return pd.Series(a).rolling(window=p, min_periods=1).min().to_numpy(dtype=np.float64)

    @staticmethod
    def calculate_stochastic(
        high: np.ndarray,
        low: np.ndarray,
        close: np.ndarray,
        period: int = 14,
        smooth: int = 3,
    ) -> Tuple[np.ndarray, np.ndarray]:
        h = np.ascontiguousarray(high, dtype=np.float64).ravel()
        l = np.ascontiguousarray(low, dtype=np.float64).ravel()
        c = np.ascontiguousarray(close, dtype=np.float64).ravel()
        n = c.size
        p = max(2, int(period))
        s = max(1, int(smooth))
        if n < p or h.size != n or l.size != n:
            return np.full(n, 50.0, dtype=np.float64), np.full(n, 50.0, dtype=np.float64)
        if _NUMBA_AVAILABLE:
            return _fast_stochastic_1d(h, l, c, p, s)
        s_high = pd.Series(h)
        s_low = pd.Series(l)
        s_close = pd.Series(c)
        lowest_low = s_low.rolling(window=p, min_periods=1).min()
        highest_high = s_high.rolling(window=p, min_periods=1).max()
        denom = (highest_high - lowest_low).replace(0.0, np.nan)
        k_raw = (100.0 * ((s_close - lowest_low) / denom)).fillna(50.0).clip(0.0, 100.0)
        k_sm = k_raw.rolling(window=s, min_periods=1).mean().fillna(50.0)
        d_sm = k_sm.rolling(window=s, min_periods=1).mean().fillna(50.0)
        return k_sm.to_numpy(dtype=np.float64), d_sm.to_numpy(dtype=np.float64)

    @staticmethod
    def calculate_williams_r(
        high: np.ndarray, low: np.ndarray, close: np.ndarray, period: int = 14
    ) -> np.ndarray:
        h = np.ascontiguousarray(high, dtype=np.float64).ravel()
        l = np.ascontiguousarray(low, dtype=np.float64).ravel()
        c = np.ascontiguousarray(close, dtype=np.float64).ravel()
        n = c.size
        p = max(2, int(period))
        if n < p or h.size != n or l.size != n:
            return np.full(n, -50.0, dtype=np.float64)
        if _NUMBA_AVAILABLE:
            return _fast_williams_r_1d(h, l, c, p)
        s_high = pd.Series(h)
        s_low = pd.Series(l)
        s_close = pd.Series(c)
        highest_high = s_high.rolling(window=p, min_periods=1).max()
        lowest_low = s_low.rolling(window=p, min_periods=1).min()
        denom = (highest_high - lowest_low).replace(0.0, np.nan)
        wr = (-100.0 * ((highest_high - s_close) / denom)).fillna(-50.0).clip(-100.0, 0.0)
        return wr.to_numpy(dtype=np.float64)

    @staticmethod
    def calculate_cci(
        high: np.ndarray, low: np.ndarray, close: np.ndarray, period: int = 20
    ) -> np.ndarray:
        h = np.ascontiguousarray(high, dtype=np.float64).ravel()
        l = np.ascontiguousarray(low, dtype=np.float64).ravel()
        c = np.ascontiguousarray(close, dtype=np.float64).ravel()
        n = c.size
        p = max(2, int(period))
        if n < p or h.size != n or l.size != n:
            return np.zeros(n, dtype=np.float64)
        if _NUMBA_AVAILABLE:
            return _fast_cci_1d(h, l, c, p)
        tp = (h + l + c) / 3.0
        s_tp = pd.Series(tp)
        sma = s_tp.rolling(window=p, min_periods=1).mean()
        mad = s_tp.rolling(window=p, min_periods=1).apply(
            lambda x: np.mean(np.abs(x - np.mean(x))), raw=True
        )
        denom = (0.015 * mad).replace(0.0, np.nan)
        cci = ((s_tp - sma) / denom).fillna(0.0).clip(-500.0, 500.0)
        return cci.to_numpy(dtype=np.float64)
    # ═══════════════════════════════════════════════════════════════════
    def calculate_rolling_mean(self, data: Any, period: int) -> np.ndarray:
        return self.calculate_sma(data, period)

    def calculate_rolling_std(self, data: Any, period: int) -> np.ndarray:
        try:
            p = max(2, int(period))
            a = self._normalize_input(data, "data")
            if len(a) < p:
                return np.zeros(len(a), dtype=np.float64)
            return np.nan_to_num(
                pd.Series(a).rolling(p, min_periods=1).std(ddof=0).to_numpy(), nan=0.0)
        except Exception as e:
            self.logger.error(f"[{self.name}_ROLLING_STD] {e}")
            return np.empty(0, dtype=np.float64)

    def calculate_rolling_sum(self, data: Any, period: int) -> np.ndarray:
        try:
            p = max(1, int(period))
            a = self._normalize_input(data, "data")
            if len(a) == 0:
                return np.empty(0, dtype=np.float64)
            if NUMBA_AVAILABLE and _KERNELS_READY:
                try:
                    return _fast_rolling_sum_1d(np.ascontiguousarray(a), p)
                except Exception:
                    pass
            return pd.Series(a).rolling(p, min_periods=1).sum().to_numpy()
        except Exception as e:
            self.logger.error(f"[{self.name}_ROLLING_SUM] {e}")
            return np.empty(0, dtype=np.float64)

    # ═══════════════════════════════════════════════════════════════════
    # Linear regression / slope / percent rank
    # ═══════════════════════════════════════════════════════════════════
    def calculate_linreg_endpoint(self, data: Any, period: int) -> np.ndarray:
        try:
            p = max(2, int(period))
            a = self._normalize_input(data, "data")
            if len(a) == 0:
                return np.empty(0, dtype=np.float64)
            if NUMBA_AVAILABLE and _KERNELS_READY:
                try:
                    return _linreg_vals_numba(np.ascontiguousarray(a), p)
                except Exception:
                    pass
            x = np.arange(p, dtype=np.float64)
            xm = x.mean()
            xc = x - xm
            xvar = float(np.dot(xc, xc))
            out = np.full(len(a), np.nan, dtype=np.float64)
            if xvar < 1e-12:
                return out
            w = (1.0 / p) + ((p - 1 - xm) * xc / xvar)
            out[p - 1:] = np.correlate(np.nan_to_num(a, nan=0.0), w[::-1], mode="valid")
            return out
        except Exception as e:
            self.logger.error(f"[{self.name}_LINREG] {e}")
            return np.empty(0, dtype=np.float64)

    def calculate_lin_slope(self, data: Any, period: Optional[int] = None) -> float:
        try:
            a = self._normalize_input(data, "data")
            if period is None:
                y = a
            else:
                y = a[-int(period):]
            if len(y) < 3:
                return 0.0
            if NUMBA_AVAILABLE and _KERNELS_READY:
                try:
                    return float(_fast_lin_slope_1d(np.ascontiguousarray(y)))
                except Exception:
                    pass
            m = len(y)
            x = np.arange(m, dtype=np.float64)
            xm = x.mean()
            ym = y.mean()
            num = float(np.sum((x - xm) * (y - ym)))
            den = float(np.sum((x - xm) ** 2))
            return num / den if den > 1e-12 else 0.0
        except Exception as e:
            self.logger.error(f"[{self.name}_LIN_SLOPE] {e}")
            return 0.0

    def calculate_percent_rank(self, data: Any, period: int) -> np.ndarray:
        try:
            p = max(2, int(period))
            a = self._normalize_input(data, "data")
            if len(a) == 0:
                return np.empty(0, dtype=np.float64)
            if NUMBA_AVAILABLE and _KERNELS_READY:
                try:
                    return _compute_pct_rank_numba(np.ascontiguousarray(a), p)
                except Exception:
                    pass
            out = np.zeros(len(a), dtype=np.float64)
            for i in range(p, len(a)):
                w = a[i - p:i]
                out[i] = 100.0 * float(np.count_nonzero(w < a[i])) / p
            return out
        except Exception as e:
            self.logger.error(f"[{self.name}_PCT_RANK] {e}")
            return np.empty(0, dtype=np.float64)

    # ═══════════════════════════════════════════════════════════════════
    # True Range / swings / equal levels / pivots
    # ═══════════════════════════════════════════════════════════════════
    def calculate_true_range(self, high: Any, low: Any, close: Any) -> np.ndarray:
        try:
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            n = min(len(h), len(l), len(c))
            if n == 0:
                return np.empty(0, dtype=np.float64)
            h, l, c = h[:n], l[:n], c[:n]
            prev = np.concatenate(([c[0]], c[:-1]))
            return np.maximum(h - l, np.maximum(np.abs(h - prev), np.abs(l - prev)))
        except Exception as e:
            self.logger.error(f"[{self.name}_TR] {e}")
            return np.empty(0, dtype=np.float64)

    def find_swings(self, high: Any, low: Any,
                    order: Optional[int] = None
                    ) -> Tuple[np.ndarray, np.ndarray]:
        try:
            o = max(1, int(order or self.swing_order))
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            n = min(len(h), len(l))
            if n < 2 * o + 1:
                return np.empty(0, dtype=np.int64), np.empty(0, dtype=np.int64)
            h, l = h[:n], l[:n]
            if NUMBA_AVAILABLE and _KERNELS_READY:
                try:
                    return _find_swings_numba(np.ascontiguousarray(h),
                                              np.ascontiguousarray(l), o)
                except Exception:
                    pass
            return _fast_pivots_1d(np.ascontiguousarray(h),
                                   np.ascontiguousarray(l), o)
        except Exception as e:
            self.logger.error(f"[{self.name}_SWINGS] {e}")
            return np.empty(0, dtype=np.int64), np.empty(0, dtype=np.int64)

    def detect_equal_levels(self, values: Any, tolerance: float = 0.001) -> np.ndarray:
        try:
            a = self._normalize_input(values, "values")
            if len(a) < 2:
                return np.empty(0, dtype=np.float64)
            if NUMBA_AVAILABLE and _KERNELS_READY:
                try:
                    return _detect_equal_levels_numba(np.ascontiguousarray(a), float(tolerance))
                except Exception:
                    pass
            # fallback: cluster
            s = np.sort(a)
            clusters = [[float(s[0])]]
            for x in s[1:]:
                c = float(np.mean(clusters[-1]))
                if abs(float(x) - c) / max(abs(c), 1e-12) <= tolerance:
                    clusters[-1].append(float(x))
                else:
                    clusters.append([float(x)])
            return np.array([np.mean(c) for c in clusters if len(c) >= 2], dtype=np.float64)
        except Exception as e:
            self.logger.error(f"[{self.name}_EQ_LEVELS] {e}")
            return np.empty(0, dtype=np.float64)

    def calculate_pivot_levels(self, high: Any, low: Any, close: Any,
                               lookback: Optional[int] = None,
                               fib: bool = True) -> Dict[str, float]:
        try:
            p = max(4, int(lookback or self.pivot_lookback))
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            n = min(len(h), len(l), len(c))
            if n < p + 1:
                return {}
            h, l, c = h[:n], l[:n], c[:n]
            end = (n // p) * p
            if end == n:
                end -= p
            if end < p:
                end = n - 1
            start = max(0, end - p)
            if end <= start:
                return {}
            wh = float(np.max(h[start:end]))
            wl = float(np.min(l[start:end]))
            wc = float(c[end - 1])
            rng = wh - wl
            if not np.isfinite(rng) or rng <= 0:
                return {}
            piv = (wh + wl + wc) / 3.0
            out = {
                "pivot": piv,
                "r1": 2.0 * piv - wl,
                "s1": 2.0 * piv - wh,
                "r2": piv + rng,
                "s2": piv - rng,
                "r3": wh + 2.0 * (piv - wl),
                "s3": wl - 2.0 * (wh - piv),
            }
            if fib:
                out.update({
                    "fib_r1": piv + 0.382 * rng,
                    "fib_r2": piv + 0.618 * rng,
                    "fib_r3": piv + rng,
                    "fib_s1": piv - 0.382 * rng,
                    "fib_s2": piv - 0.618 * rng,
                    "fib_s3": piv - rng,
                })
            return {k: float(v) for k, v in out.items() if np.isfinite(v)}
        except Exception as e:
            self.logger.error(f"[{self.name}_PIVOT] {e}")
            return {}

    # ═══════════════════════════════════════════════════════════════════
    # Volume-based: POC / Cumulative Delta / Delta Volume / Volatility Regime
    # ═══════════════════════════════════════════════════════════════════
    def calculate_volume_profile_poc(self, close: Any, volume: Any, lookback: int,
                                     high: Any = None, low: Any = None
                                     ) -> Dict[str, Any]:
        try:
            c = self._normalize_input(close, "close")
            v = self._normalize_input(volume, "volume")
            n = min(len(c), len(v))
            if n < lookback:
                return {"poc_price": 0.0, "success": False}
            c, v = c[-lookback:], v[-lookback:]
            if float(np.sum(v)) <= 1e-12:
                return {"poc_price": 0.0, "success": False, "reason": "zero_volume"}
            bins = int(min(48, max(12, np.sqrt(len(c)))))
            hist, edges = np.histogram(c, bins=bins, weights=v)
            if hist.sum() <= 0:
                return {"poc_price": 0.0, "success": False}
            idx = int(np.argmax(hist))
            poc = float(0.5 * (edges[idx] + edges[idx + 1]))
            return {"poc_price": poc, "success": True,
                    "vah": float(edges[-1]), "val": float(edges[0]),
                    "hist": hist.tolist()}
        except Exception as e:
            self.logger.error(f"[{self.name}_POC] {e}")
            return {"poc_price": 0.0, "success": False}

    def calculate_cumulative_delta(self, high: Any, low: Any, close: Any,
                                   volume: Any) -> np.ndarray:
        try:
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            v = self._normalize_input(volume, "volume")
            n = min(len(h), len(l), len(c), len(v))
            if n == 0:
                return np.empty(0, dtype=np.float64)
            h, l, c, v = h[:n], l[:n], c[:n], v[:n]
            denom = np.maximum(h - l, 1e-12)
            mfm = np.clip(((c - l) - (h - c)) / denom, -1.0, 1.0)
            mfv = mfm * v
            return np.cumsum(mfv, dtype=np.float64)
        except Exception as e:
            self.logger.error(f"[{self.name}_CUM_DELTA] {e}")
            return np.empty(0, dtype=np.float64)

    def calculate_delta_volume(self, high: Any, low: Any, close: Any, volume: Any,
                               lookback: int) -> Dict[str, Any]:
        try:
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            v = self._normalize_input(volume, "volume")
            n = min(len(h), len(l), len(c), len(v))
            if n < lookback:
                return {"signal": "HOLD", "confidence": 0.0, "value": 0.0,
                        "reason": "insufficient_data"}
            h, l, c, v = h[-lookback:], l[-lookback:], c[-lookback:], v[-lookback:]
            denom = np.maximum(h - l, 1e-12)
            buy = v * (c - l) / denom
            sell = v * (h - c) / denom
            delta = buy - sell
            med = float(np.median(delta))
            mad = float(np.median(np.abs(delta - med))) * 1.4826
            if mad < 1e-12:
                mad = max(float(np.std(delta)), 1e-12)
            z = float((delta[-1] - med) / mad)
            return {"signal": "HOLD" if abs(z) < 1.65 else ("BUY" if z > 0 else "SELL"),
                    "confidence": float(np.clip(0.48 + 0.22 * min(1.0, abs(z) / 1.65), 0.0, 0.88)),
                    "value": z, "reason": f"delta_z={z:.2f}"}
        except Exception as e:
            self.logger.error(f"[{self.name}_DELTA_VOL] {e}")
            return {"signal": "HOLD", "confidence": 0.0, "value": 0.0, "reason": "error"}

    def calculate_volatility_regime(self, high: Any, low: Any, close: Any,
                                    period: Optional[int] = None) -> Dict[str, Any]:
        try:
            p = max(2, int(period or self.atr_period))
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            atr = self.calculate_atr(h, l, c, p)
            atr_win = atr[-max(p * 4, 40):]
            atr_win = atr_win[np.isfinite(atr_win)]
            if atr_win.size < 8:
                return {"signal": "HOLD", "confidence": 0.0, "value": 0.0,
                        "reason": "insufficient", "vol_state": "UNKNOWN"}
            med = float(np.median(atr_win))
            mad = float(np.median(np.abs(atr_win - med))) * 1.4826
            if mad < 1e-12:
                mad = max(float(np.std(atr_win)), 1e-12)
            z = float((atr_win[-1] - med) / mad)
            pct = float(np.mean(atr_win <= atr_win[-1]))
            if z > 2.0 or pct > 0.92:
                state = "EXPANSION"
            elif z < -1.35 or pct < 0.18:
                state = "COMPRESSION"
            else:
                state = "NORMAL"
            return {"signal": "HOLD",
                    "confidence": float(np.clip(0.40 + 0.18 * min(1.0, abs(z) / 2.0), 0.0, 0.72)),
                    "value": z, "vol_state": state,
                    "reason": f"atr_z={z:.2f} pct={pct:.2f}"}
        except Exception as e:
            self.logger.error(f"[{self.name}_VOL_REGIME] {e}")
            return {"signal": "HOLD", "confidence": 0.0, "value": 0.0,
                    "reason": "error", "vol_state": "UNKNOWN"}

    # ═══════════════════════════════════════════════════════════════════
    # Trend strength
    # ═══════════════════════════════════════════════════════════════════
    def calculate_trend_strength(self, high: Any, low: Any, close: Any,
                                 period: Optional[int] = None) -> Dict[str, Any]:
        try:
            p = max(2, int(period or self.adx_period))
            adx, pdi, mdi = self.calculate_adx_di_bundle(high, low, close, p)
            adx_l = float(adx[-1]) if len(adx) else 0.0
            pdi_l = float(pdi[-1]) if len(pdi) else 0.0
            mdi_l = float(mdi[-1]) if len(mdi) else 0.0
            if not np.isfinite(adx_l):
                adx_l = 0.0
            if adx_l > 32 and pdi_l > mdi_l * 1.08:
                sig = "BUY" if adx_l > 40 else "WEAK_BUY"
            elif adx_l > 32 and mdi_l > pdi_l * 1.08:
                sig = "SELL" if adx_l > 40 else "WEAK_SELL"
            else:
                sig = "HOLD"
            return {"signal": sig,
                    "confidence": float(np.clip(0.38 + adx_l * 0.009, 0.0, 0.84)),
                    "value": adx_l,
                    "plus_di": pdi_l, "minus_di": mdi_l,
                    "reason": f"ADX={adx_l:.1f} +DI={pdi_l:.1f} -DI={mdi_l:.1f}"}
        except Exception as e:
            self.logger.error(f"[{self.name}_TREND] {e}")
            return {"signal": "HOLD", "confidence": 0.0, "value": 0.0,
                    "reason": "error"}

    # ═══════════════════════════════════════════════════════════════════
    # Candle patterns + Divergence
    # ═══════════════════════════════════════════════════════════════════
    def detect_candle_patterns(self, open_: Any, high: Any, low: Any, close: Any,
                               atr: Optional[float] = None) -> List[Dict[str, Any]]:
        """الگوهای کندلی روی آخرین کندل — روی tail محاسبه می‌شود."""
        try:
            o = self._normalize_input(open_, "open")
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            n = min(len(o), len(h), len(l), len(c))
            if n < 3:
                return []
            o, h, l, c = o[:n], h[:n], l[:n], c[:n]
            out: List[Dict[str, Any]] = []
            o1, h1, l1, c1 = float(o[-1]), float(h[-1]), float(l[-1]), float(c[-1])
            o2, h2, l2, c2 = float(o[-2]), float(h[-2]), float(l[-2]), float(c[-2])
            rng1 = h1 - l1
            rng2 = h2 - l2
            if rng1 <= 1e-12 or rng2 <= 1e-12:
                return []
            body1 = abs(c1 - o1)
            body2 = abs(c2 - o2)
            uw = h1 - max(o1, c1)
            lw = min(o1, c1) - l1
            b1, s1 = c1 > o1, c1 < o1
            b2, s2 = c2 > o2, c2 < o2
            if b1 and s2 and body1 > body2 * 1.05 and c1 >= o2 and o1 <= c2:
                out.append({"name": "BULLISH_ENGULFING", "type": "BULLISH",
                            "confidence": float(np.clip(0.55 + min(body1 / max(body2, 1e-12) - 1, 1) * 0.30, 0, 0.92))})
            if s1 and b2 and body1 > body2 * 1.05 and c1 <= o2 and o1 >= c2:
                out.append({"name": "BEARISH_ENGULFING", "type": "BEARISH",
                            "confidence": float(np.clip(0.55 + min(body1 / max(body2, 1e-12) - 1, 1) * 0.30, 0, 0.92))})
            if body1 / rng1 <= 0.36:
                if lw >= body1 * 1.8 and uw <= body1 * 0.9:
                    out.append({"name": "HAMMER", "type": "BULLISH",
                                "confidence": float(np.clip(0.50 + lw / rng1 * 0.45, 0, 0.90))})
                if uw >= body1 * 1.8 and lw <= body1 * 0.9:
                    out.append({"name": "SHOOTING_STAR", "type": "BEARISH",
                                "confidence": float(np.clip(0.50 + uw / rng1 * 0.45, 0, 0.90))})
            if body1 / rng1 < 0.10:
                out.append({"name": "DOJI", "type": "NEUTRAL", "confidence": 0.35})
            if h1 < h2 and l1 > l2:
                out.append({"name": "INSIDE_BAR", "type": "NEUTRAL", "confidence": 0.40})
            return out
        except Exception as e:
            self.logger.error(f"[{self.name}_CANDLES] {e}")
            return []

    def detect_divergence(self, close: Any, high: Any, low: Any,
                          oscillator: Any, lookback: int = 40,
                          swing_order: int = 2) -> Dict[str, Any]:
        try:
            c = self._normalize_input(close, "close")
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            osc = self._normalize_input(oscillator, "osc")
            n = min(len(c), len(h), len(l), len(osc))
            if n < lookback + swing_order + 2:
                return {"found": False, "direction": "", "confidence": 0.0}
            c, h, l, osc = c[-lookback:], h[-lookback:], l[-lookback:], osc[-lookback:]
            ph, pl = self.find_swings(h, l, swing_order)
            if len(ph) < 2 and len(pl) < 2:
                return {"found": False, "direction": "", "confidence": 0.0}
            best_dir, best_conf = "", 0.0
            if len(ph) >= 2:
                i1, i2 = int(ph[-2]), int(ph[-1])
                p1, p2 = float(h[i1]), float(h[i2])
                if p1 > 0 and (p2 - p1) / p1 > 0.0015:
                    r1, r2 = float(osc[i1]), float(osc[i2])
                    if r2 < r1 - 1.5:
                        strength = float(np.clip((r1 - r2) / 18.0, 0.30, 1.0))
                        conf = float(np.clip(0.50 + 0.35 * strength, 0, 0.92))
                        if conf > best_conf:
                            best_dir, best_conf = "BEARISH", conf
            if len(pl) >= 2:
                i1, i2 = int(pl[-2]), int(pl[-1])
                p1, p2 = float(l[i1]), float(l[i2])
                if p1 > 0 and (p1 - p2) / p1 > 0.0015:
                    r1, r2 = float(osc[i1]), float(osc[i2])
                    if r2 > r1 + 1.5:
                        strength = float(np.clip((r2 - r1) / 18.0, 0.30, 1.0))
                        conf = float(np.clip(0.50 + 0.35 * strength, 0, 0.92))
                        if conf > best_conf:
                            best_dir, best_conf = "BULLISH", conf
            return {"found": bool(best_dir), "direction": best_dir,
                    "confidence": float(best_conf)}
        except Exception as e:
            self.logger.error(f"[{self.name}_DIVERGENCE] {e}")
            return {"found": False, "direction": "", "confidence": 0.0}

    # ═══════════════════════════════════════════════════════════════════
    # Bill Williams helpers
    # ═══════════════════════════════════════════════════════════════════
    def calculate_smma(self, data: Any, period: int) -> np.ndarray:
        try:
            p = max(1, int(period))
            a = self._normalize_input(data, "data")
            n = len(a)
            out = np.full(n, np.nan, dtype=np.float64)
            if n < p:
                return out
            v = float(np.mean(a[:p]))
            out[p - 1] = v
            inv = 1.0 / p
            for i in range(p, n):
                v += (a[i] - v) * inv
                out[i] = v
            return out
        except Exception as e:
            self.logger.error(f"[{self.name}_SMMA] {e}")
            return np.empty(0, dtype=np.float64)

    def calculate_alligator(self, high: Any, low: Any, close: Any,
                            jaw: int = 13, teeth: int = 8, lips: int = 5,
                            jaw_shift: int = 8, teeth_shift: int = 5,
                            lips_shift: int = 3
                            ) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:
        try:
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            c = self._normalize_input(close, "close")
            n = min(len(h), len(l), len(c))
            if n == 0:
                z = np.empty(0, dtype=np.float64)
                return z, z.copy(), z.copy()
            h, l, c = h[:n], l[:n], c[:n]
            median = (h + l) * 0.5
            jaw_arr = self.calculate_smma(median, jaw)
            teeth_arr = self.calculate_smma(median, teeth)
            lips_arr = self.calculate_smma(median, lips)
            def shifted(arr, sh):
                if sh <= 0:
                    return arr
                out = np.full_like(arr, np.nan)
                out[sh:] = arr[:-sh]
                return out
            return (shifted(jaw_arr, jaw_shift),
                    shifted(teeth_arr, teeth_shift),
                    shifted(lips_arr, lips_shift))
        except Exception as e:
            self.logger.error(f"[{self.name}_ALLIGATOR] {e}")
            z = self._fallback_array(len(close) if close is not None else 0, 0.0)
            return z, z.copy(), z.copy()

    def calculate_ao(self, high: Any, low: Any, fast: int = 5, slow: int = 34) -> np.ndarray:
        try:
            h = self._normalize_input(high, "high")
            l = self._normalize_input(low, "low")
            n = min(len(h), len(l))
            if n == 0:
                return np.empty(0, dtype=np.float64)
            median = (h[:n] + l[:n]) * 0.5
            return (self.calculate_sma(median, fast) -
                    self.calculate_sma(median, slow))
        except Exception as e:
            self.logger.error(f"[{self.name}_AO] {e}")
            return np.empty(0, dtype=np.float64)

    def calculate_ac(self, high: Any, low: Any, fast: int = 5, slow: int = 34,
                     smoothing: int = 5) -> np.ndarray:
        try:
            ao = self.calculate_ao(high, low, fast, slow)
            if len(ao) == 0:
                return ao
            return ao - self.calculate_sma(ao, smoothing)
        except Exception as e:
            self.logger.error(f"[{self.name}_AC] {e}")
            return np.empty(0, dtype=np.float64)

    def detect_fractals(self, high: Any, low: Any, lookback: int = 5,
                        confirm: int = 2) -> Dict[str, np.ndarray]:
        try:
            ph, pl = self.find_swings(high, low, lookback)
            return {"up": ph, "down": pl}
        except Exception as e:
            self.logger.error(f"[{self.name}_FRACTALS] {e}")
            return {"up": np.empty(0, dtype=np.int64),
                    "down": np.empty(0, dtype=np.int64)}

    # ═══════════════════════════════════════════════════════════════════
    # Volatility (kept)
    # ═══════════════════════════════════════════════════════════════════
    def calculate_volatility(self, data: Any, period: int = 20) -> np.ndarray:
        try:
            period = max(2, int(period))
            a = self._normalize_input(data, "data")
            n = len(a)
            if n == 0:
                return np.empty(0, dtype=np.float64)
            if n < 2:
                return np.zeros(n, dtype=np.float64)
            r = np.diff(a) / (np.abs(a[:-1]) + 1e-8)
            r = np.concatenate(([0.0], r))
            return np.nan_to_num(
                pd.Series(r).rolling(period, min_periods=2).std(ddof=0).to_numpy(),
                nan=0.0)
        except Exception as e:
            self.logger.error(f"[{self.name}_VOL] {e}")
            return np.empty(0, dtype=np.float64)

    def _validate_price_data(self, close: np.ndarray) -> Tuple[np.ndarray, int]:
        fixes = 0
        try:
            if close is None or len(close) == 0:
                return (close if isinstance(close, np.ndarray)
                        else np.empty(0, dtype=np.float64)), 0
            cc = np.asarray(close, dtype=np.float64).copy()
            if np.isnan(cc).any() or np.isinf(cc).any():
                cc = _fast_fillna_1d(cc)
                fixes += 1
            return cc, fixes
        except Exception as e:
            self.logger.error(f"[{self.name}_VALIDATE] {e}")
            return (close if isinstance(close, np.ndarray)
                    else np.empty(0, dtype=np.float64)), fixes

    def generate_rsi_signal(self, rsi_values: Any) -> Tuple[str, float, str]:
        try:
            arr = self._normalize_input(rsi_values, "rsi")
            if len(arr) == 0:
                return "HOLD", 0.30, "No RSI data"
            r = float(np.clip(arr[-1], self.rsi_clamp_min, self.rsi_clamp_max))
            if r < self.rsi_oversold:
                return "BUY", min(0.75, 0.45 + (self.rsi_oversold - r) / 60), f"RSI OS ({r:.1f})"
            if r > self.rsi_overbought:
                return "SELL", min(0.75, 0.45 + (r - self.rsi_overbought) / 60), f"RSI OB ({r:.1f})"
            if r < 40:
                return "WEAK_BUY", 0.40, f"RSI low ({r:.1f})"
            if r > 60:
                return "WEAK_SELL", 0.40, f"RSI high ({r:.1f})"
            return "HOLD", 0.30, f"RSI neutral ({r:.1f})"
        except Exception as e:
            self.logger.error(f"[{self.name}_RSI_SIG] {e}")
            return "HOLD", 0.30, f"Error: {str(e)[:30]}"

    # ═══════════════════════════════════════════════════════════════════
    # Stats / serialization / self-test (extended)
    # ═══════════════════════════════════════════════════════════════════
    def get_stats(self) -> Dict[str, Any]:
        with self._lock:
            return self._stats.copy()

    def reset_stats(self) -> None:
        with self._lock:
            for k in self._stats:
                self._stats[k] = 0

    def to_dict(self) -> Dict[str, Any]:
        with self._lock:
            return {"name": self.name, "category": self.category,
                    "config": self.config, "stats": self._stats}

    def self_test(self) -> Dict[str, Any]:
        """تست سلامت TechnicalAnalyzer — فقط مقادیر bool شمرده میشوند."""
        results: Dict[str, Any] = {}
        try:
            t = tuple(range(100, 130))
            results["none_safety"] = self.calculate_rsi(None) is not None
            results["empty_safety"] = self.calculate_rsi([]) is not None
            results["tuple_safety"] = len(self.calculate_rsi(t)) == len(t)
            results["rsi_finite"] = not np.isnan(self.calculate_rsi(t)).any()
            m, s, h = self.calculate_macd(t)
            results["macd_lengths"] = len(m) == len(t) and len(s) == len(t) and len(h) == len(t)
            hh = tuple(x + 1 for x in t)
            ll = tuple(x - 1 for x in t)
            results["atr_ok"] = not np.isnan(self.calculate_atr(hh, ll, t)).any()
            results["adx_ok"] = not np.isnan(self.calculate_adx(hh, ll, t)).any()
            results["stoch_ok"] = not np.isnan(self.calculate_stochastic(hh, ll, t)[0]).any()
            results["williams_ok"] = not np.isnan(self.calculate_williams_r(hh, ll, t)).any()
            results["cci_ok"] = not np.isnan(self.calculate_cci(hh, ll, t)).any()
            v = np.ones(len(t))
            results["mfi_ok"] = not np.isnan(self.calculate_mfi(hh, ll, t, v)).any()
            results["obv_ok"] = not np.isnan(self.calculate_obv(t, v)).any()
            results["vwap_ok"] = not np.isnan(self.calculate_vwap(hh, ll, t, v)).any()
            results["hma_ok"] = not np.isnan(self.calculate_hma(t)).any()
            results["kama_ok"] = not np.isnan(self.calculate_kama(t)).any()
            results["linreg_ok"] = not np.isnan(self.calculate_linreg_endpoint(t, 5)).any()
            results["swings_ok"] = isinstance(self.find_swings(hh, ll), tuple)
            results["pivot_ok"] = bool(self.calculate_pivot_levels(hh, ll, t))
            results["poc_ok"] = isinstance(self.calculate_volume_profile_poc(t, v, 20), dict)
            results["patterns_ok"] = isinstance(self.detect_candle_patterns(t, hh, ll, t), list)
            results["divergence_ok"] = isinstance(self.detect_divergence(t, hh, ll, t), dict)
            results["hurst_finite"] = math.isfinite(float(self.calculate_hurst(t)))
        except Exception as e:
            results["error"] = str(e)

        bool_items = [v for v in results.values() if isinstance(v, bool)]
        results["all_passed"] = bool(bool_items) and all(bool_items)
        results["total_tests"] = int(len(bool_items))
        results["passed_tests"] = int(sum(1 for v in bool_items if v is True))
        return results
   
