#──────────────────────────────────────────────────────────────────────────────────────────

class WindowCalibrator:
    """Conservative window-equivalence checker, not a profitability backtest.

    Comparisons use the same historical endpoint for both windows.  A clone
    is required so the live strategy's state is not modified by replay.
    """

    WINDOW_MULTIPLIERS = [1.0, 1.25, 1.5, 2.0, 3.0]
    MIN_HISTORICAL_POINTS = 50
    MAX_HISTORICAL_POINTS = 500
    MIN_DIRECTIONAL_POINTS = 10

    def __init__(self, window_manager: Optional['StrategyWindowManager'] = None,
                 calibration_interval_seconds: int = 3600,
                 max_calibration_time_seconds: float = 30.0):
        self.window_manager = window_manager or get_strategy_window_manager()
        self.calibration_interval_seconds = max(60, int(calibration_interval_seconds))
        self.max_calibration_time_seconds = max(5.0, float(max_calibration_time_seconds))
        self._last_calibration: Dict[str, float] = {}
        self._calibration_lock = threading.RLock()
        self._stats = {
            "total_calibrations": 0,
            "successful_calibrations": 0,
            "failed_calibrations": 0,
            "last_calibration_time": None,
        }
        logger.info("[WindowCalibrator] conservative same-endpoint replay initialized")

    def should_calibrate(self, strategy_name: str, symbol: str, timeframe: str) -> bool:
        key = f"{strategy_name}|{symbol}|{timeframe}"
        with self._calibration_lock:
            return time.time() - self._last_calibration.get(key, 0.0) >= self.calibration_interval_seconds

    def _clone_strategy(self, strategy_instance: Any) -> Optional[Any]:
        serializer = getattr(strategy_instance, "to_dict", None)
        loader = getattr(type(strategy_instance), "from_dict", None)
        if not callable(serializer) or not callable(loader):
            logger.warning("[WindowCalibrator] strategy lacks to_dict/from_dict; replay skipped")
            return None
        try:
            state = serializer()
            if not isinstance(state, dict):
                logger.warning("[WindowCalibrator] strategy serialization did not return a dict")
                return None
            clone = loader(copy.deepcopy(state))
            if clone is strategy_instance or not callable(getattr(clone, "analyze_all", None)):
                logger.warning("[WindowCalibrator] strategy clone is invalid")
                return None
            clone_config = getattr(clone, "config", None)
            if isinstance(clone_config, dict):
                clone_config["shadow_tracking_enabled"] = False
                clone_config["state_persistence_enabled"] = False
            return clone
        except Exception as exc:
            logger.error("[WindowCalibrator] strategy clone failed: %s", exc, exc_info=True)
            return None
            
    def calibrate(self, strategy_name: str, strategy_instance: Any,
                  historical_data: pd.DataFrame, symbol: str, timeframe: str,
                  config_hash: str = "default", strategy_version: str = "1.0") -> Dict[str, Any]:
        started = time.monotonic()
        result: Dict[str, Any] = {
            "strategy_name": str(strategy_name),
            "symbol": str(symbol),
            "timeframe": str(timeframe),
            "selected_window": None,
            "tested_window": None,
            "reference_window": None,
            "match_rate": 0.0,
            "label_match_rate": 0.0,
            "confidence_error_p95": 1.0,
            "max_confidence_error": 1.0,
            "error_rate_increase": 1.0,
            "crash_count": 0,
            "directional_points": 0,
            "compared_points": 0,
            "passed": False,
            "calibration_time_ms": 0.0,
            "reason": "not evaluated",
        }
        valid_attempt = False
        manager_recorded = False
        try:
            canonical = _STRATEGY_NAME_ALIASES.get(str(strategy_name), str(strategy_name))
            requirements = _STRATEGY_HISTORY_REQUIREMENTS.get(canonical, {})
            if not isinstance(requirements, dict):
                requirements = {}
            hard_min = max(20, int(requirements.get("hard_min_bars", 100)))
            required_method = getattr(strategy_instance, "_required_bars", None)
            if callable(required_method):
                hard_min = max(hard_min, int(required_method()))
            reference = max(hard_min, int(requirements.get("reference_window", 500)))
            default = max(hard_min, int(requirements.get("default_window", 200)))
            result["reference_window"] = reference
            result["selected_window"] = reference
            if not isinstance(historical_data, pd.DataFrame) or len(historical_data) < reference + self.MIN_HISTORICAL_POINTS:
                result["reason"] = "insufficient historical data for a full comparison"
                return result
            if not historical_data.index.is_unique or not historical_data.index.is_monotonic_increasing:
                result["reason"] = "historical index must be unique and increasing"
                return result
            candidates = {int(hard_min * multiplier) for multiplier in self.WINDOW_MULTIPLIERS}
            if default < reference:
                candidates.add(default)
            windows = sorted(value for value in candidates if hard_min <= value < reference)
            if not windows:
                result["reason"] = "no candidate window below the reference"
                return result
            available_points = len(historical_data) - reference + 1
            number = min(self.MAX_HISTORICAL_POINTS, available_points)
            endpoints = np.linspace(reference, len(historical_data), num=number, dtype=np.int64)
            points = sorted(set(int(value) for value in endpoints))
            if len(points) < self.MIN_HISTORICAL_POINTS:
                result["reason"] = "fewer than the minimum comparison points"
                return result
            remaining = self.max_calibration_time_seconds - (time.monotonic() - started)
            reference_outputs = self._run_rolling_test(
                strategy_instance, historical_data, points, reference, max(0.0, remaining * 0.5)
            )
            if reference_outputs is None or len(reference_outputs) != len(points):
                result["reason"] = "baseline incomplete, unavailable or timed out"
                return result
            valid_attempt = True
            for candidate in windows:
                remaining = self.max_calibration_time_seconds - (time.monotonic() - started)
                if remaining <= 0.0:
                    result["reason"] = "time budget exhausted before candidate replay"
                    break
                outputs = self._run_rolling_test(strategy_instance, historical_data, points, candidate, remaining)
                if outputs is None or len(outputs) != len(points):
                    result["reason"] = f"candidate {candidate} incomplete or timed out"
                    continue
                comparison = self._compare_outputs(reference_outputs, outputs)
                if self._check_acceptance_criteria(comparison):
                    result.update(comparison)
                    result["selected_window"] = candidate
                    result["tested_window"] = candidate
                    result["passed"] = True
                    result["reason"] = "same-endpoint equivalence criteria passed; profitability not assessed"
                    break
                result["reason"] = f"candidate {candidate} failed equivalence criteria"
            if valid_attempt:
                self.window_manager.record_calibration_result(
                    strategy_name=strategy_name, symbol=symbol, timeframe=timeframe,
                    tested_window=int(result["selected_window"]), reference_window=reference,
                    is_match=bool(result["passed"]), config_hash=config_hash,
                    strategy_version=strategy_version,
                )
                manager_recorded = True
                getter = getattr(self.window_manager, "get_selected_window", None)
                if callable(getter):
                    selected = int(getter(strategy_name, symbol, timeframe, config_hash))
                    if selected < hard_min:
                        self.window_manager.record_calibration_result(
                            strategy_name=strategy_name, symbol=symbol, timeframe=timeframe,
                            tested_window=reference, reference_window=reference, is_match=False,
                            config_hash=config_hash, strategy_version=strategy_version,
                        )
                        selected = int(getter(strategy_name, symbol, timeframe, config_hash))
                        if selected < hard_min:
                            raise ValueError("window manager retained an insufficient window")
                    result["selected_window"] = selected
                else:
                    result["selected_window"] = reference
                    result["reason"] += "; manager selection could not be read"
            return result
        except Exception as exc:
            logger.error("[WindowCalibrator] calibration failed: %s", exc, exc_info=True)
            result["passed"] = False
            if result["reference_window"] is not None:
                result["selected_window"] = result["reference_window"]
            result["reason"] = f"calibration error: {type(exc).__name__}: {exc}"
            return result
        finally:
            if not manager_recorded and result["reference_window"] is not None:
                try:
                    self.window_manager.record_calibration_result(
                        strategy_name=strategy_name, symbol=symbol, timeframe=timeframe,
                        tested_window=int(result["reference_window"]),
                        reference_window=int(result["reference_window"]), is_match=False,
                        config_hash=config_hash, strategy_version=strategy_version,
                    )
                except Exception as exc:
                    logger.error("[WindowCalibrator] could not restore reference window: %s", exc, exc_info=True)
            result["calibration_time_ms"] = max(0.0, (time.monotonic() - started) * 1000.0)
            key = f"{strategy_name}|{symbol}|{timeframe}"
            with self._calibration_lock:
                self._last_calibration[key] = time.time()
                self._stats["total_calibrations"] += 1
                if result["passed"]:
                    self._stats["successful_calibrations"] += 1
                else:
                    self._stats["failed_calibrations"] += 1
                self._stats["last_calibration_time"] = datetime.now(timezone.utc).isoformat()

    def _run_rolling_test(self, strategy_instance: Any, historical_data: pd.DataFrame,
                          test_points: List[int], window_size: int,
                          deadline_seconds: float) -> Optional[List[Dict[str, Any]]]:
        clone = self._clone_strategy(strategy_instance)
        if clone is None or not isinstance(historical_data, pd.DataFrame):
            return None
        started = time.monotonic()
        outputs: List[Dict[str, Any]] = []
        analyze_method = getattr(clone, "analyze_all")
        for raw_point in test_points:
            if time.monotonic() - started >= max(0.0, float(deadline_seconds)):
                logger.warning("[WindowCalibrator] replay timed out before completing all points")
                break
            endpoint = int(raw_point)
            if endpoint < int(window_size) or endpoint > len(historical_data):
                return None
            frame = historical_data.iloc[endpoint - int(window_size):endpoint].copy()
            try:
                value = analyze_method(frame)
                if inspect.isawaitable(value):
                    try:
                        asyncio.get_running_loop()
                    except RuntimeError:
                        value = asyncio.run(value)
                    else:
                        close = getattr(value, "close", None)
                        if callable(close):
                            close()
                        raise RuntimeError("async replay requires a thread without a running event loop")
                if not isinstance(value, dict):
                    raise TypeError("analyze_all returned a non-dict result")
                signal_token = str(value.get("signal", "HOLD") or "HOLD").upper().strip()
                confidence = float(value.get("confidence", 0.0))
                candidate_only = False
                metadata = value.get("metadata")
                if (getattr(clone, "name", "") == "AdvancedMovingAverages" and signal_token == "HOLD"
                        and isinstance(metadata, dict)):
                    decision = metadata.get("decision")
                    shadow = decision.get("shadow_candidate") if isinstance(decision, dict) else None
                    if isinstance(shadow, dict) and shadow.get("direction") in ("BUY", "SELL"):
                        signal_token = str(shadow["direction"])
                        confidence = float(shadow.get("setup_quality", 0.0))
                        candidate_only = True
                if not math.isfinite(confidence) or not 0.0 <= confidence <= 1.0:
                    raise ValueError("invalid confidence")
                error_type = str(value.get("error_type", "None") or "None").lower().strip()
                validation_error = str(value.get("reason", "")).lower().startswith("validation failed:")
                has_error = bool(value.get("is_fallback", False)) or validation_error or error_type not in (
                    "none", "", "null", "no error", "noerror", "no_error"
                )
                outputs.append({
                    "point_idx": endpoint,
                    "signal": signal_token,
                    "confidence": confidence,
                    "score": float(value.get("score", 50.0)),
                    "hold_quality": value.get("hold_quality"),
                    "error": error_type,
                    "is_error": bool(has_error),
                    "is_crash": False,
                    "candidate_only": candidate_only,
                })
            except Exception as exc:
                logger.warning("[WindowCalibrator] replay point %d failed: %s", endpoint, exc)
                outputs.append({
                    "point_idx": endpoint, "signal": "ERROR", "confidence": 0.0,
                    "score": 50.0, "hold_quality": None, "error": str(exc)[:200],
                    "is_error": True, "is_crash": True, "candidate_only": False,
                })
        return outputs if outputs else None

    def _compare_outputs(self, reference_outputs: List[Dict[str, Any]],
                         candidate_outputs: List[Dict[str, Any]]) -> Dict[str, float]:
        failure = {
            "match_rate": 0.0, "label_match_rate": 0.0,
            "confidence_error_p95": 1.0, "max_confidence_error": 1.0,
            "error_rate_increase": 1.0, "crash_count": 0,
            "directional_points": 0, "compared_points": 0,
            "reference_errors": 0, "candidate_errors": 0,
        }
        if not reference_outputs or not candidate_outputs:
            return failure
        try:
            reference = {int(row["point_idx"]): row for row in reference_outputs}
            candidate = {int(row["point_idx"]): row for row in candidate_outputs}
        except (TypeError, ValueError, KeyError):
            return failure
        if (len(reference) != len(reference_outputs) or len(candidate) != len(candidate_outputs)
                or set(reference) != set(candidate) or len(reference) < self.MIN_HISTORICAL_POINTS):
            return failure
        matches = labels = crashes = ref_errors = cand_errors = 0
        confidence_errors: List[float] = []
        for point in sorted(reference):
            ref, cand = reference[point], candidate[point]
            ref_label = str(ref.get("signal", "HOLD")).upper().strip()
            cand_label = str(cand.get("signal", "HOLD")).upper().strip()
            ref_action = self._normalize_signal(ref_label)
            cand_action = self._normalize_signal(cand_label)
            if ref_action == cand_action:
                matches += 1
            if ref_label == cand_label:
                labels += 1
            if bool(cand.get("is_crash")):
                crashes += 1
            if bool(ref.get("is_error")) or ref_action == "ERROR":
                ref_errors += 1
            if bool(cand.get("is_error")) or cand_action == "ERROR":
                cand_errors += 1
            if ref_action in ("BUY", "SELL") and cand_action == ref_action:
                try:
                    first, second = float(ref.get("confidence")), float(cand.get("confidence"))
                    if not (math.isfinite(first) and math.isfinite(second)):
                        return failure
                    confidence_errors.append(abs(first - second))
                except (TypeError, ValueError, OverflowError):
                    return failure
        count = len(reference)
        return {
            "match_rate": matches / count,
            "label_match_rate": labels / count,
            "confidence_error_p95": float(np.percentile(confidence_errors, 95)) if confidence_errors else 1.0,
            "max_confidence_error": max(confidence_errors) if confidence_errors else 1.0,
            "error_rate_increase": max(0.0, (cand_errors - ref_errors) / count),
            "crash_count": crashes,
            "directional_points": len(confidence_errors),
            "compared_points": count,
            "reference_errors": ref_errors,
            "candidate_errors": cand_errors,
        }

    def _normalize_signal(self, signal: str) -> str:
        token = str(signal or "").upper().strip()
        if token in ("BUY", "STRONG_BUY", "WEAK_BUY", "LONG"):
            return "BUY"
        if token in ("SELL", "STRONG_SELL", "WEAK_SELL", "SHORT"):
            return "SELL"
        if token in ("HOLD", "STRONG_HOLD", "NEUTRAL", "FLAT"):
            return "HOLD"
        return "ERROR"

    def _check_acceptance_criteria(self, comparison: Dict[str, float]) -> bool:
        if not isinstance(comparison, dict):
            return False
        return (
            comparison.get("compared_points", 0) >= self.MIN_HISTORICAL_POINTS and
            comparison.get("directional_points", 0) >= self.MIN_DIRECTIONAL_POINTS and
            comparison.get("match_rate", 0.0) == 1.0 and
            comparison.get("label_match_rate", 0.0) >= 0.99 and
            comparison.get("confidence_error_p95", 1.0) <= 0.02 and
            comparison.get("max_confidence_error", 1.0) <= 0.05 and
            comparison.get("error_rate_increase", 1.0) == 0.0 and
            comparison.get("crash_count", 1) == 0 and
            comparison.get("reference_errors", 1) == 0 and
            comparison.get("candidate_errors", 1) == 0
        )

    def get_stats(self) -> Dict[str, Any]:
        with self._calibration_lock:
            return dict(self._stats)

    def reset_stats(self) -> None:
        with self._calibration_lock:
            self._stats = {
                "total_calibrations": 0,
                "successful_calibrations": 0,
                "failed_calibrations": 0,
                "last_calibration_time": None,
            }


# ═══════════════════════════════════════════════════════════════════════════
# ✅ NEW: Singleton instance
# ═══════════════════════════════════════════════════════════════════════════
_WINDOW_CALIBRATOR: Optional[WindowCalibrator] = None
_WINDOW_CALIBRATOR_LOCK = threading.Lock()


def get_window_calibrator() -> WindowCalibrator:
    """دریافت singleton instance از WindowCalibrator."""
    global _WINDOW_CALIBRATOR
    if _WINDOW_CALIBRATOR is None:
        with _WINDOW_CALIBRATOR_LOCK:
            if _WINDOW_CALIBRATOR is None:
                _WINDOW_CALIBRATOR = WindowCalibrator()
    return _WINDOW_CALIBRATOR
