# Marker name recognised on analyze_all methods / strategy classes. Kept as a
# module constant so no class attribute lookup can fail at import time.
_ANALYZE_WRAPPED_MARKER: str = "_analyze_wrapped"


def _strategy_is_wrapped(cls: type) -> bool:
    """
    Return True when ``cls`` is considered protected by the inline safety
    layer.

    A strategy is considered protected when ANY of the following holds:

      1. Its ``analyze_all`` method carries the marker attribute
         ``_analyze_wrapped = True`` (used by optional external tooling).
      2. The class itself carries the marker attribute.
      3. The class is a subclass of ``StrategyBaseMixin`` and defines its own
         callable ``analyze_all`` — the base mixin's validation, fallback and
         analytical-HOLD semantics provide the safety contract in that case.

    This check never raises and never depends on attributes that may be
    missing; it is safe to call at module import time.
    """
    try:
        if not isinstance(cls, type):
            return False

        method = getattr(cls, "analyze_all", None)
        if method is None or not callable(method):
            return False

        if getattr(method, _ANALYZE_WRAPPED_MARKER, False):
            return True
        if getattr(cls, _ANALYZE_WRAPPED_MARKER, False):
            return True

        try:
            return issubclass(cls, StrategyBaseMixin)
        except TypeError:
            return False
    except Exception:
        return False


def _collect_wrapped_strategies() -> List[str]:
    """
    Names of strategies whose ``analyze_all`` is protected by the shared
    inline safety layer.

    Returns a list (possibly empty) of class names as they appear in
    ``STRATEGIES_LIST``. Never raises.
    """
    out: List[str] = []
    try:
        for cls_name, cls in STRATEGIES_LIST.items():
            if _strategy_is_wrapped(cls):
                out.append(str(cls_name))
    except Exception as exc:
        _patch_logger.error(
            "[UNIFIED_PATCH] _collect_wrapped_strategies failed: %s",
            exc,
            exc_info=True,
        )
    return out


def apply_unified_strategy_patch() -> int:
    """
    Report how many strategies are protected by the inline safety layer.

    This call is intentionally a **no-op side-effect free** operation: the
    safety contract is enforced by ``StrategyBaseMixin`` and by every
    concrete ``analyze_all`` implementation, so no runtime monkey-patching is
    required. Returns the number of protected strategies.
    """
    try:
        wrapped = _collect_wrapped_strategies()
        _patch_logger.info(
            "[UNIFIED_PATCH] Inline safety layer active on %d/%d strategies "
            "(no monkey-patching).",
            len(wrapped),
            len(STRATEGIES_LIST),
        )
        return len(wrapped)
    except Exception as exc:
        _patch_logger.error(
            "[UNIFIED_PATCH] apply_unified_strategy_patch failed: %s",
            exc,
            exc_info=True,
        )
        return 0


def ensure_strategy_patched() -> int:
    """Backward-compatible alias; always returns the current count."""
    return len(_collect_wrapped_strategies())


def get_patched_classes() -> List[str]:
    """Return the list of protected strategy class names."""
    return _collect_wrapped_strategies()


def is_patched(class_name: str) -> bool:
    """Return True if ``class_name`` is protected by the inline safety layer."""
    if not class_name:
        return False
    try:
        return str(class_name) in _collect_wrapped_strategies()
    except Exception:
        return False


def get_unified_strategy_patcher() -> Callable[[], int]:
    """Return a callable that reports the protected-strategy count."""
    return apply_unified_strategy_patch


def _verify_async_preservation() -> Dict[str, bool]:
    """
    Report whether each strategy's ``analyze_all`` is a coroutine function.

    Useful for downstream code that dispatches on sync/async at runtime.
    Never raises.
    """
    out: Dict[str, bool] = {}
    try:
        for name, cls in STRATEGIES_LIST.items():
            method = getattr(cls, "analyze_all", None)
            if method is None:
                out[str(name)] = False
                continue
            try:
                out[str(name)] = bool(inspect.iscoroutinefunction(method))
            except Exception:
                out[str(name)] = False
    except Exception as exc:
        _patch_logger.error(
            "[UNIFIED_PATCH] _verify_async_preservation failed: %s",
            exc,
            exc_info=True,
        )
    return out


# Inline safety-layer health probe at import time. Safe because it has no
# side effects other than a single log record.
_auto_patch = apply_unified_strategy_patch()